/* 平成19年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h19.committeeSessions.push(...[{"id":"h19-20070625-7","meetingId":"h19-cm06","date":"2007年6月25日","dateIso":"2007-06-25","committee":"厚生委員会","time":"午前１０時０３分～午後２時４５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を59件整理しています。","topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"提案","question":"２０年近くにわたって請願が上げられてきましたし、共産党区議団としても１０回の条例提案をしてきたものですので、何点か教えていただきたいんです。１１億４,１９０万５,０００円というのがあるんですけれども、それぞれ国と都の負担額がどれぐらいあって、教えてほしいと求めました。","respondent":"諸岡児童課長","answer":"単純計算をいたしますと、おっしゃるとおりでございまして、年間で約１４億円ぐらいになるかなと予定をしております。平成１９年度からは財調算定になりましたので、予算額につきましては、すべて一般財源ということになります。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"都のほうは、財調算定ということで、平成１９年度からは一般財源ということなんですけれども、国の分はないんですか。そこのところだけ、ちょっと確認します。","respondent":"諸岡児童課長","answer":"この基本制度が東京都の制度ですので、都と区での負担です。","id":"exchange-002"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"東京都の関係で質問があったので、私も関連して伺いたいんですが、そういうのは何かつかんでいるものがあるのかどうか。区のほうからの要望というか、そういうものはしているのかどうなのか、そこのところをお聞かせほしいと求めました。","respondent":"諸岡児童課長","answer":"１月に入り、説明会等がございまして、正式に東京都の予算として計上するということなりました。それを受けて、品川区におきましても、予算に盛り込んだというものです。","id":"exchange-003"},{"speaker":"堺委員","kind":"質問","question":"改正の内容で、ここに書いてあるとおりなので、このまま理解をすればいいんだろうと思いますが、念のため、中学３年生、括弧して、「１５歳到達後最初の３月３１日まで」となっていますが、単純に、要するに中学校を卒業するまでは全員が対象となるというふうに理解すればいいということか尋ねました。","respondent":"諸岡児童課長","answer":"ご質問のとおりでございまして、３月３１日まで、つまり中学校を卒業するまで、最後の３月３１日まで適用となるというものです。","id":"exchange-004"},{"speaker":"堺委員","kind":"確認","question":"２点目は、対象児童数の中に数字がありますけれども、この理解なんですけれども、国籍は日本国籍を有する者ということなんですか。そういう人たちも対象に入っているんですか、その辺はどうですか、ちょっと確認させてください。","respondent":"諸岡児童課長","answer":"もちろん外国人の方も対象になりますが、ただし、保険に入っているということが条件になります。保険が７割、残りの３割分について負担という形をとっておりますので、助成の対象となる要件です。","id":"exchange-005"},{"speaker":"堺委員","kind":"質問","question":"所管外になっちゃうのかもしれませんけれども、品川区に登録されている方は、基本的には全部保険に入っているという理解をしていいんですか。新聞をときどき見たりしていますので、品川区の現況はどうなのかなと思いまして、その辺はいかがか尋ねました。","respondent":"諸岡児童課長","answer":"子どもすこやか医療費助成制度そのものの対象となるのは、保険適用というものです。そういう方は保険に入れませんので、この制度は適用になりませんで、また別の助成の方法になろうかと思います。","id":"exchange-006"},{"speaker":"堺委員","kind":"質問・要望","question":"我々も昭和６２年だったでしょうか、区としてもぜひ実現していただきたいということを訴え始めてから、もうかれこれ２０年になります。私も平成１０年６月の第２回定例会の一般質問で取り上げさせていただいた経緯があります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"須藤委員","kind":"質問","question":"そのあたりはどうですか。品川区でやっている子育て支援策の一環ですよという考え方で、この政策をやっていると理解をしておいてよろしいか、どうか。","respondent":"諸岡児童課長","answer":"医療費助成制度につきましては、すべての子育て世帯を対象といたしました子育て支援策として、今回、実施するものです。ご質問のとおりです。","id":"exchange-008"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"さっき、健康保険に入っているのが前提という話だったので、そのことで確認したいんです。負担を求めるということになると、そういうところの考え方があったら、お聞かせほしいと求めました。","respondent":"諸岡児童課長","answer":"自己負担分について助成するという制度ですので、この制度の中では、ご質問のような件は該当いたしません。それにつきましては、生活全般の支援とか、あるいは、生活保護とか、生活そのものの支援ということになっていくかと思います。","id":"exchange-009"},{"speaker":"宮崎副委員長","kind":"質問","question":"ですから、１０割負担しなきゃいけないということになるんですけれども、適用というのがどういうふうになるのか。生活保護になれば、それは生活保護のほうなのかと思うんですけれども、今のケース、例えば、その世帯が資格証明書になった場合、どうなるのか。","respondent":"諸岡児童課長","answer":"先ほど申し上げましたように、あくまでも保険適用が原則です。この制度で助成をするというものですので、保険が適用にならない分につきましては、この制度も適用にならないという制度です。","id":"exchange-010"},{"speaker":"宮崎副委員長","kind":"質問","question":"そういうところは、具体的にどういうふうになるのか。そういうふうになった場合には、どういうふうな対応をされるんか尋ねました。","respondent":"諸岡児童課長","answer":"ちょっと、個別の具体的な話になりますと、詳しいご答弁はできないんですけれども。領収書をもとに金額をお支払いするということが原則ですけれども、一般的には、そのようなことです。","id":"exchange-011"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"今のお話だと、償還払いということかなと思うんですけれども、現実に払えないという場合には、窓口負担も非常にきつくなるので、そこはちょっと対応を考えたほうがいいかなと思いますので、それは要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"堺委員","kind":"質問・要望","question":"そういう方がないほうがいいんですけれども、万が一あった場合に、そういう人たちについてのフォローもきちっとしていただきたい。漏れのないような形でフォローもしていただければなと、この辺についての考え方だけ、ちょっと教えていただきたい。","respondent":"諸岡児童課長","answer":"その領収書を持って手続いただければ、１０月１日まではさかのぼるです。１１月に入りますと、ポスターを掲示していただくようにお願いするとか、そういったことでいろいろ手を尽くしてまいりたいと考えています。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３園が選ばれたわけですけれども、この３園がなぜ選ばれたのかという、その理由を一つお聞かせほしいと求めました。これからはさらに、この認定こども園が区立保育園の中に拡大されていくという方針があるのかどうかについてもお聞かせほしいと求めました。","respondent":"高橋幼保一元担当課長","answer":"幼児教育の重要性を認識して、学校教育法第７８条についてのいろいろなご指導をいただきながら準備に取りかかり、９月１日に向けているところです。だから、現時点におきましては、３園とし、来年度また拡大するということは考えていません。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"こういう形で、保育園にさらに幼稚園の保育料で５人ずつ入れていくというような、中身だけを拡大していくと考えていいんでしょうか。子どもたちが１０名ずつ増えるわけですけれども、職員体勢というのがどうなっていくのかということについても、教えてほしいと求めました。","respondent":"高橋幼保一元担当課長、小林保育課長","answer":"品川区が区の方針といたしまして、小学校にスムーズな移行をということを考えていますので、質を高めるという方向で考えているところです。それから、職員体制についてですけれども、保育課長からお答えするということで… 保育所型認定こども園の３園の開設に伴います人の問題ということですけれども、基本的に、人の配置は保育園の配置基準に従ってまいります。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１対３０というのが基準だということで、確認をさせていただいていいかということを、一つお願いしたいと思います。そういうことで、この施設は１０人増えたとしてもクリアしているということでとらえていいのかということも、確認をさせてほしいと求めました。","respondent":"古川児童保健事業部長、小林保育課長、高橋幼保一元担当課長","answer":"じゃあ１日４時間教育の中で、どうそれに対応していくかという中では、認定こども園というものを認定しましょうということであります。… 施設基準の関係ですが、４、５歳児におきましては、保育園の基準、園児１名に対しまして１.９８m2の基準適用となっております。… ５歳、５人ずつにしたことにつきましては、待機児解消の一役を担える部分もあるのではないかと考えているところもあります。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"特に区立幼稚園での教育というのがどうなっていたのかというのが、保育園の保育の中身がどう変わるのかというのを、ちょっと教えていただきたいんです。","respondent":"高橋幼保一元担当課長","answer":"０歳から５歳まで保育をしているというところでは、国が言っている認定こども園の一貫した教育保育であるということは、私も認識しています。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それが４歳児から昼寝がなくなるというのは、もし子どもが１０時までいるとしたら、子どもにとっては負担になるんじゃないかなということが一つ。オアシスルームで毎日６人の子どもたちが入れかわり来て、幼稚園に通うような子どもたちが１０人来るとなったら、いかがか尋ねました。","respondent":"高橋幼保一元担当課長","answer":"その２４時間の中で、この３園については、昼寝をしないような環境整備をしていくということを考えています。次の事業について取り組むという姿勢というところで、私は考えていますので、そのことについては進めてまいりたいと思っているところです。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"７５０円ともう決めちゃっているわけですけれども、もっと短い１時間とか、２時間とかというのもあるのではないかなと思ったんです。ここでは、一切所得にかかわりなく一律ということになっているんですけれども、そこら辺の考え方に関してはいかがか尋ねました。","respondent":"高橋幼保一元担当課長、小林保育課長","answer":"条例の説明をしました中で、品川区保育の実施等に関する条例、免除の措置があります。あわせて、認定こども園にする短時間の利用児についても、そのようなことを考えているところです。 品川区の基本的な認識として、親の状況にかかわらず、小学校に向けて必要な保育、教育は提供していく。型にとらわれて不自由なのではなくて、できるだけ柔軟に対応していきたいという意味での保育を必要とするという枠になっております。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"確認をさせていただきたいのは、いつごろ、どういう形でされるのかということを教えてほしいと求めました。３番目に子育て支援事業の実施となっていますが、これは具体的にどんな中身でやるのかということについても、説明を求めました。","respondent":"高橋幼保一元担当課長","answer":"区民への説明会はどのような形で行うかですが、３園が実施するというところでは、保護者会を通してお話ししてきているところです。改めてまた、それぞれの園に説明に行くということと、全体的には、７月１３日の金曜日に、庁舎の中で５時ぐらいから開催をする予定です。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"７月１３日、金曜日、庁舎で５時からの説明会というのは、これは一般区民向けということでいいんでしょうか。そのことだけ、説明を求めました。","respondent":"高橋幼保一元担当課長","answer":"この本会議が７月４日に終了するという意味では、まだ区民に対しては公表できない説明会ですので、これは全区民に対して実施したいと思っています。","id":"exchange-021"},{"speaker":"須藤委員","kind":"意見","question":"そういった場合に、私立の幼稚園なんかでいろいろ子育てをやったりとか、いろいろな形をもってきていますよね。そのあたり、こういう認定こども園という仕組みづくりになってきているのかどうかということを、１点お聞かせ願いたいと思いますとの意見を述べました。","respondent":"高橋幼保一元担当課長","answer":"平成１２年度からきんだぁくらぶというのを７園で実施してくださっていまして、幼稚園における保育機能が活用されているということは認識しています。そのときは、そういった前向きな私立に対しての考え方等も含めて検討していかなくてはいけないと思っているところです。","id":"exchange-022"},{"speaker":"須藤委員","kind":"質問・要望","question":"いい施策を打ってもらうことは当然必要なんですけれども、全体の状況を見ていきながら進めていってほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"堺委員","kind":"質問・要望","question":"何点か確認する意味で、申しわけないんですが、教えていただきたいんです。西五反田にありますぷりすくーるは幼保連携型というんでしょうか、タイプというんですか、これを参考までに教えていただけますか。","respondent":"高橋幼保一元担当課長","answer":"５歳の幼稚園がつくという並列型と、０歳から３歳までが認可保育所で、３歳から５歳が認可幼稚園という年齢区分型があります。ただ、都のほうと、そういった部分もクリアすることが可能か、どうかということは、今、いろいろ話しているところではあります。","id":"exchange-024"},{"speaker":"堺委員","kind":"質問","question":"そうすると、地方裁量型というんですか、これはどういうタイプになるんですかね。ちょっと参考までに、すみません。","respondent":"高橋幼保一元担当課長","answer":"地方裁量型といいますと、東京都におきましては、認証保育所を指しています。","id":"exchange-025"},{"speaker":"堺委員","kind":"質問","question":"お尋ねがあったのかと思うんですが、どうなっていくんだと、質問されたんだろうと思うんです。それについてはどうなんか尋ねました。","respondent":"高橋幼保一元担当課長","answer":"今回の認定こども園の実施に当たりましては、子どもの２４時間を考えて、園長を含めた検討会を進め。","id":"exchange-026"},{"speaker":"堺委員","kind":"質問・要望","question":"万全の態勢というふうに申し上げていいんでしょうか、あるいはお父さん方がお子さんを預けるわけですから、あそこに預けると心配だと。そういう事業をぜひ推進をしていただきたいと、今、お尋ねをしているわけであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"宮崎副委員長","kind":"質問","question":"ちょっと１点伺いたいんですけれども、５歳児のところで、お伺いしたいんです。どんな感じなんか尋ねました。","respondent":"小林保育課長","answer":"このお２人につきましては、現在、解消されております。これも今後対応してまいりますので、５歳の待機児については、対応済みだと考えております。","id":"exchange-028"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"５歳児５名ずつで１０名、３園で３０名の枠を増やすということなんですけれども、どういうふうな見通しを持っておられるんでしょうか。品川区としては、そういう場合に、どういう対応をしていくのかというのをお聞かせほしいと求めました。","respondent":"高橋幼保一元担当課長、小林保育課長","answer":"そして、応募が少ない場合は、月ごとに入園可能ということでやってまいりたいと思います。定員枠は５名ということで考えているところです。 ９月１日の需要想定ではなくて、３園を主とした認定こども園がどのような保育、需要は大きく左右されるであろうと考えています。そういった意味で、今後の推移を見守り、適切に対応してまいりたいと考えております。","id":"exchange-029"},{"speaker":"宮崎副委員長","kind":"質問","question":"鈴木委員のほうから質問があった、保育料が２段階になっていくということが、果たしていいのか。ですから、そういう２段階の保育料の設定というふうになっていくのが果たしていいのかと、どういうふうにお考えなんか尋ねました。","respondent":"古川児童保健事業部長","answer":"しかし、需要については、５人が０かもしれません。幼児教育を継続的に提供していくということが、３園における今までの保育園の園児、これは必ず充実していくと考えております。","id":"exchange-030"},{"speaker":"宮崎副委員長","kind":"意見","question":"そうなると、親のほうからすれば、同じ状態で、保育料の２段階が出てくるということになってしまいますよということを言っているんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"豊かな環境のもとで充実させてほしいというのは、すべての親の願いであって、幼保一元というのは必要であると思っています。認定こども園の保育料や入園料とかも含めて出されている議案ですので、これに対しても反対ということで、態度を述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"堺委員","kind":"質問・要望","question":"いろいろと心配されている点があるやの質問等もございましたので、その辺につきましては、対応はお願いしておきたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"}]},{"id":"topic-02","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ケアホームではなくて、特別養護老人ホームを、という請願というのは、今までも何度か出されていますし、私たちも求めてきたところなんです。在宅の方は、全体の特別養護老人ホームの全体の申込みをされている方の何名中何名ぐらいなのか、このことについてもお聞かせほしいと求めました。","respondent":"蓼沼高齢福祉課長","answer":"２３区の設置状況について把握しているかというお尋ねですけれども、各区がどの程度整備しているかということについては、特に把握しておりません。","id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"新型特別養護老人ホームが当たり前ということになっているわけですから、それで、健全な経営がされていないということでとらえられているのか。ずっとこういう答弁を繰り返しお聞きしていますけれども、７年も８年も頑張ってきて、お聞かせいただきたい。","respondent":"蓼沼高齢福祉課長","answer":"人の配置の基準については多床室と同様ということで、これでは個室のケアということでは十分なサービスの質の確保ができないのではないかです。施設として対応するとすれば、一定程度無理が生じるのではないかということで、お答えを申し上げたものです。","id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２３区で３７カ所もつくっているわけですから、ほとんどの区がつくっているわけですから、２３区と連携して。そのことについては、いかがか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"利用者３人に対して１人の職員配置の基準というようなことが、それでは、一つの区としての考えを述べたものです。これに限らず、必要な働きかけは、都を経由して常々努力をしています。","id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"大方の区がこういうことをやっているわけですから、品川区だけがやらないというのは、やっぱり区民にとっては納得いかないと思うんです。この待機者に対する考え方についても、お聞かせほしいと求めました。","respondent":"木下福祉高齢事業部長、蓼沼高齢福祉課長","answer":"これから予定している原小学校跡とか、どちらに重点を置くかということであれば、そういうことではないかなと考えているところであります。いろいろな角度から検討をして… ８０名の方がいらっしゃって、１年という期間の中では、比較的入所されているという状況です。","id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"港区にお伺いしたときに、待機者が３００人ちょっとなんですけれども、それで待機者解消を目指したいということを言われていたんですよね。入院している方、そういう施設の方の考え方についても、お聞かせほしいと求めました。","respondent":"蓼沼高齢福祉課長","answer":"これにつきましては、現行の入所の調整のあり方では、在宅の方を重視するということで対応しております。要介護５で７年という、簡単にはお答えできませんけれども、対応をしてきているという状況です。","id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"最後にもう一つお伺いしたいのは、ケアホーム、グループホームと特別養護老人ホームの違いだと思うんです。品川区として、こういう介護の格差について、どう考えているのかということについて、その考えをお聞かせいただきたいんです。","respondent":"木下福祉高齢事業部長","answer":"３割近くの方が、医療的な行為が必要で、どうしても特別養護老人ホームで対応できない部分があります。実際には９８０人ぐらいの方が入っておられるわけですので、現時点では、その部分については賄われているのではないかというふうに考えているです。","id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"実際に特別養護老人ホームに入られている４５０人の一人ひとりの生活、暮らし、それに本当に心を寄せていただきたいなと思います。９８０人という５７０人以外の方というのは、三多摩のほかの自治体でお世話になっているわけですから、ぜひつくってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"須藤委員","kind":"質問・要望","question":"そのときに伺っていると、行財政改革で跡地利用ということで話があって、それに沿ってずっと流れてきた。伺っていると、結論を出してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"もうちょっと低廉な施設をつくってほしいという要望がこれだけ寄せられるということを、どういうふうにお考えかということを、伺っておきたい。そこのところを、まずお聞きしたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"それからホームページでパブリックコメント等も実施をした結果として、区として、こういう整備方針を決定したものです。平成１７年１０月の改正の際には、利用者の負担段階２の方については、一定程度対応ができていると考えているところです。","id":"exchange-042"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"そこの点について、これだけの要望が強い。皆さん方の計画とか、それはそれで置いておいて、住民の要望というのをどういうふうに受けとめているかというところを、伺いたい。","respondent":"蓼沼高齢福祉課長","answer":"原小学校跡施設の利用料につきましては、先ほど、ご説明いたしましたとおり、今現在、まだ検討しているという状況です。今回の原小学校跡については、先ほど、申し上げましたような経緯もございまして、区として整備の方針を決定させていただいたというものです。","id":"exchange-043"},{"speaker":"宮崎副委員長","kind":"質問","question":"こういうところを考えるべきだと思うんですけれども、具体的にどういうふうに考えておられるのか、そこのところはどうなんでしょうか。そこのところは、どうなんか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"第４次の長期基本計画の検討に入っておりますけれども、かなり長いスパンでものを見ていく必要があるというのが、まず基本にあります。２階と３階に設ける、当該地については、先ほどから高齢福祉課長のほうから申し上げているような施設内容にしていこうということになったです。","id":"exchange-044"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"こういう要望というのは当然であるし、収入の少ない方のところにまず行くべきじゃないかということは、私は当然だと思うんですよね。そういう人から取って、こういう人が利用できないんですから。","respondent":"木下福祉高齢事業部長","answer":"そういう点では、在宅介護施設福祉も含めまして、かなり丁寧な対応をしています。今後、原小学校跡等に新しく整備されるものの状況を含めてごらんをいただきながら、ご判断をいただければと考えています。","id":"exchange-045"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"見通しが持てる、具体的に１年、２年という話があったけれども、入所調整会議は半年ごとじゃないですか。どうなんか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"いわゆる病院等に入っている方で、収入的に厳しい方もおられるのは事実でありますので、幾つかの課題があるということについては認識しております。ただ、基準の上で、問題認識は持っているということは申し上げたいと思います。","id":"exchange-046"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"ですから、やっぱり圧倒的に数が少ないと。このことを要望して質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"堺委員","kind":"質問・要望","question":"特別養護老人ホームの待機者が５００人近くいますと、こうなっておりますが、これはそのとおりなんですか。これをまず確認をしておきたいんです。","respondent":"蓼沼高齢福祉課長","answer":"そういう意味で申し上げて、おおむね要介護３以上の方が入所されている方が多いです。区内で１２０名、区外を含めると１６０名入所された方がいて、見通しが立つというふうに申し上げているものです。","id":"exchange-048"},{"speaker":"堺委員","kind":"質問","question":"ここに書いてあるように、待機者が５００人近くいますとおっしゃっていますが、そのとおりですかと聞いたんですよね。それから、待機者というのは、どういう人なんか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"今年の３月、昨年の９月では、大体４５０名前後の方が申込みをされているというものです。そのことを、待機者５００人と言われているのかどうかわかりませんけれども、申込者がそれだけあったというものです。","id":"exchange-049"},{"speaker":"堺委員","kind":"質問","question":"そうすると、この請願に書かれている、「現在、特別養護老人ホームの待機者が５００人近くいます」というこの待機者というのは、今の課長の説明からいくと、半年ごとの入所調整会議に向けて、入居申請の希望を出している人がこれだけいますよという理解を、私はすればいいんか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"今、委員ご指摘のように、過去２回の入所調整の際には、要介護１から要介護５の方まで、お申し込みをされている方が約４５０名前後いるです。","id":"exchange-050"},{"speaker":"堺委員","kind":"質問","question":"そうすると、特別養護老人ホーム入所対象者と思える人は大体要介護３以上だとすると、必ずしも５００名全員がその対象者ではないと。例えば要介護１の人が何名、２の人が何名と、お手元でわかるんか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"そういう意味で言えば、要介護１、２の比較的軽度の方については、概して申し上げれば、そういう状態像には当てはまらないのではないかと。要介護１、２でも入所されている方は中にはいらっしゃいますけれども、やはり要介護３以上の方が入所されているという実態です。","id":"exchange-051"},{"speaker":"堺委員","kind":"意見","question":"要介護１、２の人は、私は知りたいのでお尋ねするんです。もし把握されていないんだったら、いいんですけれども、把握されているんならとの意見を述べました。","respondent":"蓼沼高齢福祉課長","answer":"お申込みをされた方については、それは要介護１であっても、当然お断りすることなく、お受けをして、審査にかけているです。待機という表現がどうなのかということで、私どものほうは、お申込みされている方と申し上げているところです。","id":"exchange-052"},{"speaker":"堺委員","kind":"質問・要望","question":"それに準ずる人ですから、２については、名簿から外しているわけではありませんと。ですから、その辺も含めまして、今後のこういう施策については進めていっていただきたいなと思います。","respondent":"蓼沼高齢福祉課長","answer":"施設の整備の状況は、ご指摘のとおりです。平成２１年からは第４期の介護保険の事業計画も始まりますので、制度なりの変更といいますか、検討していきたいと考えております。","id":"exchange-053"},{"speaker":"堺委員","kind":"質問・要望","question":"悪かろうでは困るわけでして、したがって、サービスの質をきちっと確保していただきたい。それから、それを前提にして、なるべく低廉な料金の設定をということを、重ねて要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"須藤委員","kind":"質問・要望","question":"保険料がうんと高くなってもいいんですかと、保険料が５,０００円になりますよということをお話しして、それはなかなか難しいと思う。ですから、ほんとうに僕らは真剣に見ていかないと、一面的にだけ議論をしていくべきではないと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ケアホームというのは特定介護施設で、特定介護施設でも、介護保険財政は、特別養護老人ホームの場合とそれほど大きくは変わらないわけです。２３区の中でダントツトップというぐらいに積み立てられているわけですから、区民の要望をぜひとも実現をさせていくということで、今日。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"本間委員","kind":"質問","question":"そのような意味で、私たちは、高齢者の介護のあり方について、どうあるべきかというのが主の議論だと思います。できないのか、できるだけ、どうしても不可能なものはやむを得ないというような形の中で結論を出していくべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"堺委員","kind":"意見","question":"原小学校跡地に特別養護老人ホームをつくってくださいと、これは願意に沿いがたいと、我々は思っています。それからもう１点、我々もちょっと願意に沿いがたいということだけを、申し上げておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"阿部議員の質問で、児童センターのほうを開設されているという質問だったんですけれども、現状がどうなっているのか。それから、現在実施している要介護４、５への周知をどうしているかということも含めて、お知らせいただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/928192?Template=document&Id=3174#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":58827,"voices":142}},{"id":"h19-20070625-8","meetingId":"h19-cm06","date":"2007年6月25日","dateIso":"2007-06-25","committee":"建設委員会","time":"午前１０時０３分～午後３時３２分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を50件整理しています。","topics":[{"id":"topic-01","title":"第５５号議案、品川区自転車等の放置防止および自転車等駐車場の整備に関する条例の一部を改正する条例","agenda":"第５５号議案、品川区自転車等の放置防止および自転車等駐車場の整備に関する条例の一部を改正する条例","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"５の再整備後の状況というところで、バイクの利用というのが結構求められているんじゃないかと思うんですけれども、３３.３％というのは、どういうふうに考えられている部分か尋ねました。","respondent":"松嶋交通安全担当課長","answer":"およその平均が３０％程度ということで、中延第３のところに自転車の部分を削って、６台分のバイクを確保しています。そこで３３.３％といいますのは、現在の利用者の数２台です。","id":"exchange-001"},{"speaker":"井上委員","kind":"質問","question":"ということは、場所柄で利用台数が少ないのか、周知が少ないのか、今後それをせっかく収容可能台数として６台の分をとっているわけですから、その辺はどういうふうに考えているんか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"現にそれはうちも認識をしていますけれども、この近くに東急電鉄が行っております駐輪場のほう、ここに３０台の収容施設があります。周知を図らなくてはならないというのも認識をしています。","id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"放置がこの地域にあるかどうかはわからないんですけれども、行っていく必要があるんじゃないかと思いますけれども、その辺はいかがか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"中には、アパートに住んでいて、とめるところがないので路上にそのままとめているとか、そういったものもあります。現実の実態として、一時利用というのは、現実的には少ないんじゃないかというふうに認識をしております。","id":"exchange-003"},{"speaker":"井上委員","kind":"質問・要望","question":"実際にどういうニーズがあるかという根拠がちょっとはっきりしていませんので、せっかく４台のスペースをとって確保しているわけですから、この先も調査をしながら検討していただきたいというふうに要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"ちょっと教えていただきたいんですけれども、それでパーセントが出るのかなと思っているんですけど、当日利用というのはどうやって出しているのか。そこはどういうふうな計算なのか教えていただきたいのと、去年ですか、僕がたまたま行ったときにいっぱいだったんですよね。","respondent":"松嶋交通安全担当課長","answer":"中延第２の利用状況ですけれども、この６４.５％といいますのは、逆に少ないときもあります。そういった内容で、６４.５％というのは平均ということでご理解をいただきたいと思います。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"もうちょっと教えていただきたいのと、以前は中延第２の６４.５％ですけど、どれぐらいの頻度でいっぱいになってしまうのか。僕はどこにとめたらいいんだと考えることもあるんですけど、その辺の駅前の状況を説明を求めました。","respondent":"松嶋交通安全担当課長","answer":"とりあえず区営の中延第２、第３といいますのは、都営浅草線中延駅のものとして考えておるところです。いずれにしましても、中延駅前の放置自転車の散乱はちょっとうちのほうも認識しておりますので、撤去もしっかりとやっているところです。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"今回中延第１が廃止になって、きちんと代替地を考えるべきだなと思っているんですけど、エレベーターよりももっともっと大きいと思うんですよね。伺いたいのは、それとエレベーターとして使う部分の面積はそれぞれどうなのかということと、その辺はいかがか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"ただ、今戸越駅のところで同じようなエレベーター設置工事をやっております。かなり歩道部分からエレベーターのあたりが結構下がります、奥に行きますので、かなり厳しい状況にあるんじゃないかなというふうに思っております。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"利用状況をよく見た上で決めていただきたいと思うのと、近所の方でよく聞くのが、今駅前駐輪場だと２時間無料というのが割と増えてきたんですよね。最後にその点だけ、ちょっと関連であれですけど、区の見解を教えてほしいと求めました。","respondent":"松嶋交通安全担当課長","answer":"そういったものは２時間無料だとか、あとはこういった買い物をすれば駐輪場が無料ですよと、いろいろなところで実施をしております。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問","question":"これは東京都の交通局の用地を借りてきたということですから、必ず代替とか、もう一度再整備をされてという話になる。いろいろな啓発をしていくことによって利用率が１００％、ただ、そこら辺の方法論というのをどう考えられているのかということをまずお願いします。","respondent":"松嶋交通安全担当課長","answer":"そういった日の啓発活動もこれから推進していかなければならないと考えています。駐輪場の整備というものも、やはりその一つの課題になるんではないかというふうに考えておりまして、そのように考えております。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１００％に向け、そういう形の中で、商店街も協力をしていただきたい。それをどうやって連携して、どこが主になってやろうと考えられているのか、そこら辺の点をどうお考えになっているのか。","respondent":"松嶋交通安全担当課長","answer":"まさに商店街の部分につきましては、委員ご指摘のとおりです。今後は、今ご指摘になりましたとおり、産業振興課等とも連携を密にしてやっていかなくちゃならない課題と考えているところです。","id":"exchange-010"},{"speaker":"阿部委員","kind":"意見","question":"放置自転車の関係で、放置自転車といっても、当日利用の放置自転車と定期利用的、つまり、朝から夕方まで電車でどこかに行くための放置自転車と。","respondent":"松嶋交通安全担当課長","answer":"それで、大体朝方の段階である程度埋まりますので、通勤・通学が主に占めているというように認識をしています。これがじゃあ何割ぐらいかといいますと、その駐輪場によって違いもありますし、一概に数字というものは出せないところです。","id":"exchange-011"},{"speaker":"阿部委員","kind":"質問","question":"商店街と連携したような駐車場対策、駐輪場対策を進めていくほうがより第一線の放置自転車対策になるのかなという感じだったものですから、そういう放置自転車の種類に合わせた施策をとる必要があるのかなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問・要望","question":"今回の廃止で近隣住民のご意見なり要望なり、区のほうに要望とかご意見を寄せられているのか、その辺をちょっと教えてほしいと求めました。","respondent":"松嶋交通安全担当課長","answer":"逆に先ほどもご説明しましたけれども、パチンコ屋の前だとか、そういったものは来ていることは事実です。中延第２、第３の振り分けも実はくじを実施しておりまして、そういったものはございません。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"広いスペース、場所があるほうがいいということであれば、皆さんかなりの確率で駐輪場にとめると思うんですね。先ほどもお話が出ましたが、区としては近くに今まであったのと同じような代替地というんですか、そういうようなご検討はされているんか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"代替地の問題ですけれども、東京都交通局に対しては、この話があった段階で何とか代替地のお願いができないかという申し入れはしています。交通局のほうからは、特にそういったスペースは持っていないという回答をもらっています。","id":"exchange-014"},{"speaker":"須貝委員","kind":"質問・要望","question":"今駅前の駐輪場というのは、区民にとっては本当に必要不可欠な存在になっていると思うんですね。ここも区として探してほしいし、第３ですか、やはり区としてもできるだけその対策をしてほしいなという要望をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"三上委員","kind":"質問","question":"台数的に中延第１が減ったとしても、ここがなくなったから中延第２と第３があふれて、この周辺に自転車が置かれるという状況になり得るのかどうか。だから、それはそれで別な対策を考えなきゃならないんじゃないかというふうに私は考えるんですけれども、いかがか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"第２、第３で一番使い勝手がいいのはどれかといったら第２というのは、私もそのように考えております。そんな関係で、東急電鉄のほうの例えば高架下だとか、そういったものを貸してもらえないかということを今現実に申し入れを行っているところです。","id":"exchange-016"},{"speaker":"三上委員","kind":"質問","question":"今伺って、できるならば、代替という施設を考えるのは、これはあってもいいかなと思いますけども、だからといって、私はこの条例について、廃止をすることはだめだということを言いたくはないな、それだけは先にちょっと言っておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"認識が違ったら教えていただきたいんですが、区の役割というのは、さまざまあってやっていらっしゃると思うんですね。私の考えが違っているなら違っているで教えてもらいたいけど、そこら辺の考え方を整理するためにもう一度ちょっと教えてもらいたい。","respondent":"岩田まちづくり事業部長","answer":"品川区は歩いて１０分から１５分、そういう面からいうと必要不可欠な道具ではないというふうな認識のもとに、今までずっときてまいりました。","id":"exchange-018"},{"speaker":"須貝委員","kind":"意見","question":"ご高齢者も、自転車を利用する、なくてはならない道具になっていると思うんですね。できるだけそれを安全に確保できれば、私はこれからの時代では必要なのじゃないかなと思いますので、意見だけ言わせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"}]},{"id":"topic-02","title":"第６０号議案、専決処分の承認を求めること","agenda":"第６０号議案、専決処分の承認を求めること","exchanges":[{"speaker":"井上委員","kind":"質問","question":"ということは、この土地、補助第１６３号線の土地収用に対して品川区がやるべきことは終わったということか尋ねました。","respondent":"浜脇街路事業担当課長","answer":"私どもとすれば、事業期間内にこの土地を取得し整備することが使命です。お互い、区とそれから土地所有者と借地権者の中ではうまく和解が成立して、予定どおりいっているです。","id":"exchange-020"},{"speaker":"阿部委員","kind":"質問・要望","question":"今回借家人の権利というのは保留されたまま和解が行われたということなのかということを教えていただきたいのと、それから実際に補償の支払いをした時期と半年ずれているというのは、これは手続的にどういうことだったのかということをお聞きしたいと思います。","respondent":"浜脇街路事業担当課長","answer":"品川区が額の査定をして、今このぐらいの額ですよということをお知らせしている、そういう手続き中です。それから、もう一点ですけども、この方に対して、土地代については、６月２２日にお金を払って、最終的な手続きは終わっているです。","id":"exchange-021"},{"speaker":"阿部委員","kind":"質問","question":"借家人は、そうすると、借地人との和解で、区は直接は今かかわっていないということですか。それと、支払いはここには平成１８年１２月に支払い済みとあったんですけれども、今支払い時期と違ったのではないかと思ったんですけど。","respondent":"浜脇街路事業担当課長","answer":"収用委員会のほうから、改めて双方にこのぐらいの補償ということで出してもらう、それが今手続中ということです。現実的には６月２２日に払っていて、１２月２８日に概算払いをしたという額については、物価の変動がなかったものですから同額だです。","id":"exchange-022"}]},{"id":"topic-03","title":"平成１９年請願第１６号、品川区在住の青年世代への家賃補助を求める請願","agenda":"平成１９年請願第１６号、品川区在住の青年世代への家賃補助を求める請願","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"なぜなら、私去年の秋ですか、同窓会がありまして、久しぶりに、みんな３１歳になりますけど、それぞれ仲間に会ったんですね。先ほど紹介しましたけども、こういう実態が区にあるのかないのか、その認識をまず説明を求めました。","respondent":"齋藤住宅課長","answer":"区内でも５万円台もあれば、２万円台もあります。収入の範囲で生活することが大事だというふうに考えております。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"その他光熱水費を払うと生活が成り立たないと、こういう実態が品川区に生まれていると、こういう認識が区にあるのかどうか伺っているんです。もう少し具体的に伺うと、フリーターの１カ月の月収はどれぐらいなのか、これはどうおつかみになっているんか尋ねました。","respondent":"齋藤住宅課長","answer":"中古の木造でふろなしであれば、４万円、５万円のところもあります。フリーターの方の動向については、把握しておりません。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"このフリーターの動向を把握していないで、なぜ品川区の青年、若い人たちは社会的ニーズがないと言えるんですか。こうしたぎりぎりの方が区内で生まれていることを区はご存じないんか尋ねました。","respondent":"齋藤住宅課長","answer":"それは需要あるいは住みたいという形にマッチした住宅があるからです。委員のお話は極端な例のために家賃補助というのであれば、それは話としてはないでしょうということを申し上げております。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"今の品川区の平均家賃を考えると７万円、ちょっと安くても６万円、それは余りにも今の実態とかけ離れている認識だと思うんですね。学生、新婚世帯の方々の生活状況をきちんと把握する必要性は本当にあるんじゃないかと思うんですけれども、いかがか尋ねました。","respondent":"岩田まちづくり事業部長","answer":"フリーターの方で１０万円から１５万円の月収しかない方が、こういったところに住みたいと思われるのであれば、これは生活はできないと思います。こういうことでご理解をお願いしたいと思います。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問","question":"１Ｋ、１ＤＫ、部長は７万２,０００円はマンションだという言い方をしているけど、どうでしょうかね。先ほど新聞の話もしましたけど、１カ月１０万円しか持っていない方がどうやって品川区で７万円で暮らせと、それは無理じゃないか。","respondent":"岩田まちづくり事業部長","answer":"２万円からアパートというのはありますから。そういう意味で、私は今の時点で区がこういった直接的な家賃補助という考えはない、こう申し上げた次第です。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"ちょっと教えていただきたいのと、もう一人できて２人、広い部屋に引っ越したいと。最後に、子育て世代の経済的負担の軽減、そこについて家賃補助というのは、どういうふうに、なぜやらないのか聞かせてください。","respondent":"齋藤住宅課長","answer":"人数によって４万円とか２万円とか３万円、１０世帯だったり３０世帯だったりというようなことで、その詳細はお答えできませんが。公平性もあるかもしれませんけれども、その新婚世帯に対しての割合というのは、かなり低いということはご認識の範囲内です。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問","question":"最後に、一つ課長に伺いたいのは、新婚世帯、若いカップルのところで子どもが授かって引っ越したいと。いろんな障害がありますけど、その一つに家賃の問題があるという認識があるのかどうなのか、それを最後に説明を求めました。","respondent":"齋藤住宅課長","answer":"確かに新婚世帯の所得水準は、これから上がっていくんだということで、家賃負担が多い世帯がいらっしゃるということは認識しております。","id":"exchange-029"},{"speaker":"井上委員","kind":"質問","question":"もう一つには、持ち家の人に対して一般修築、直すことに対しての１.８％の借受者負担利率ということで区が利子分の補給という融資あっ旋をしている。４０歳未満の単身者を区にとどめておく必要性はないということをおっしゃっていましたけれども、融資あっ旋とか、どんなふうにお考えか尋ねました。","respondent":"岩田まちづくり事業部長","answer":"品川区はそういう方針をとらずに、品川区の社会的問題が起きているということで、これは２３区で飛び抜けたストックをつくっていただいたわけですね。そういうことをお答えしたというご理解をいただけますでしょうか。","id":"exchange-030"},{"speaker":"井上委員","kind":"質問・要望","question":"この請願の金額についてとか、そういうところでは、おっとというところがありますのでね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"三上委員","kind":"質問","question":"１０万円の中でやると、その中からどうやって自分の人生を切り開いていこうか、だれもがみんな思うと思いますよ。質問にはなりませんけども、私なりにちょっと意見として述べさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"石田（秀）委員","kind":"意見","question":"そういう形の中で、先ほど来個々の話がいろいろ出てきたけれども、個々の話をするときりがない。転出も単身で約１万１,０００人、私はそれはやるべきではないという考えですので、これについては不採択でお願いしたいと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問・要望","question":"物価の上昇だって、奨学金制度だって今と昔は違うじゃないですか。採択すべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"井上委員","kind":"質問・要望","question":"２０歳ぐらい、１９歳、そういったところの周知などにも取り組んでいただきたいということを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"阿部委員","kind":"意見","question":"何か直接家賃補助かどうかは別として、若いとか、新婚であるとかという理由で家賃補助ということはちょっと結びつかないのではないか。少なくとも公のお金を使うことではないのではないかと思いますので不採択でお願いしたいと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"須貝委員","kind":"質問・要望","question":"ただ、個人の家に対する家賃補助の要望というのは限りなく出てくると思うんですね。ですから、ちょっと今回の件に関しては、不採択にします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"三上委員","kind":"質問","question":"全国に１００社近くができ上がってきた、そういうやっぱり正規労働という部分についてしっかりと国も手をつけていこうという流れになってきているわけですから、今回の件に関しては不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"}]},{"id":"topic-04","title":"平成１９年請願第２０号、都営大井林町アパートおよび第２大井伊藤町アパートの廃止計画中止と建て直しを求める請願","agenda":"平成１９年請願第２０号、都営大井林町アパートおよび第２大井伊藤町アパートの廃止計画中止と建て直しを求める請願","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今区のお考えになっていること、逆に先ほど伺ってきた高齢者の方々の年齢層のことも考えると、繰り返しにならないようにしていただきたい。お話を伺った、質問の内容も聞いた、そういう方向で進めていっていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"中塚委員","kind":"質問","question":"本会議と請願と、それを同列に並べて審査が終わっているじゃないかみたいな話というのはおかしいと思うんですね。あくまで請願審査ですから、それはそれでしっかり進めることが委員会の活性化じゃないかと思いますけども、意見を踏まえてというのは納得いきません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"中塚委員","kind":"質問・要望","question":"都営住宅の転居の問題、東京都がどういう流れの中で居住者に求めているのか、時系列でご説明いただきたいというのが１点。それぞれ大井林町と第２大井伊藤町と年齢層というんですかね、どういった年齢分布になっているのか、現状を教えてほしいと求めました。","respondent":"齋藤住宅課長","answer":"それを受けて、この５月に各自治会の役員が入居者の方に説明する。６月中に新しく転居を予定する港区、ここに出ているとおり転居するんだと、こういうことを説明されたというふうに聞いております。","id":"exchange-041"},{"speaker":"中塚委員","kind":"質問","question":"区はこの半年後に出ていけと、このやり方が区は正しいと思っているのか、乱暴だと思っているのか、その認識を伺いたいと思うんですね。半年後に出ていけ、こういうやっぱり余りにも人権無視だと思うんですけれども、東京都の乱暴なやり方について区はどう思っているのか説明を求めました。","respondent":"齋藤住宅課長","answer":"丁寧に説明して、不安なく引っ越せるように、私ども各所管で支援をしたいというふうに思っております。引っ越した先でも、コミュニケーションという部分はまた新しい地域で、さまざまな関係の中でつくっていけるものだろうというふうに考えております。","id":"exchange-042"},{"speaker":"中塚委員","kind":"質問・要望","question":"例えば平成１８年度の中で、いわゆる３けた、一つの部屋に１００人以上が申し込んだ。３けたの応募倍率になったところは何月のいつのどの住宅なのか、都営住宅の募集倍率について説明を求めました。","respondent":"齋藤住宅課長","answer":"私ども答えられることと答えられないことがございまして、乱暴かどうかにつきましては、私どもはそのようなことを認識する立場にございません。北品川が１２３倍、同じく２月北品川第２、２８１倍です。","id":"exchange-043"},{"speaker":"中塚委員","kind":"質問","question":"私はきちんと区移管を受けて、公共住宅を増やすべきじゃないかと。きちんと区移管を受けないという、その区の考えは間違っていると思いますけれども、いかがか尋ねました。","respondent":"齋藤住宅課長","answer":"そこに２万円前後で入れますから、人気が高くなる、これは地の利、暮らしやすさから仕方がないことだと思います。都区協議に基づきまして、１００戸以下につきましては、区はほとんど移管を受けておりますので、これ以上区として移管を受ける考えはございません。","id":"exchange-044"},{"speaker":"中塚委員","kind":"質問","question":"品川区はどう思っているのか、本当にできないのか、そこをちょっと教えてください。大体、地形を品川区は手に入れていないんか尋ねました。","respondent":"齋藤住宅課長","answer":"私どもは正確なものは持っておりませんし、責任を持って戸数を申し上げる立場にございませんので、お答えはできない。これは一般質問でお答えしたとおりです。","id":"exchange-045"},{"speaker":"中塚委員","kind":"質問","question":"さっき質問した東京都の図面すら品川区は手に入れることはできないんですか。そのために努力してこそ品川区の役割があるんじゃないかと思いますけれども、いかがか尋ねました。","respondent":"谷田部まちづくり事業部次長、岩田まちづくり事業部長","answer":"あそこはまず東京都が所有している土地でございまして、その土地を品川区に払い下げるとも、売却するとも何もございません。ああだこうだといろいろ青写真を描くのはいいかもしれませんけど、公式の委員会の中ですので… ただ、前面道路が６ｍ未満、４ｍ程度ですから、実際容積率は１６０％レベルしかつくれない。したがって、４階建てを２階建てにしようが、どのようにしようが、容積を目いっぱい使っているのであれば、戸数は増えません。","id":"exchange-046"},{"speaker":"井上委員","kind":"質問・要望","question":"真に住宅に困窮する世帯に向けた住宅対策が求められています」ということで、こういう請願が出されていると思うんですけれども、その対策について品川区としてはどんなふうに考えて進めていくんか尋ねました。","respondent":"齋藤住宅課長","answer":"４,０００人近い方々が住宅関係で公的な扶助を受けております。やはり先ほどの話になりますが、自分の所得、身の丈に合ったところで借りることになるです。","id":"exchange-047"},{"speaker":"井上委員","kind":"質問・要望","question":"区や都が関与する公共住宅の供給などで適切な運用が求められていますということですけれども、そういうところも増やしていってほしいというふうに区民サービスにおいても、見込で結構です。","respondent":"齋藤住宅課長","answer":"その方だけのために多くのお金を使うことは、これはバランスの上でできないと、こういうことです。それは我々が建て替えがしにくい、それは品川区の地域特性の中から難しい、こういうことを申し上げているです。","id":"exchange-048"},{"speaker":"井上委員","kind":"質問","question":"８０歳の方たちはそこで生活をしていて、区民になるわけですから、相当考えなければいけない。きれいなところに移れますよ、よかったですねというふうに見えますので、その辺がどういうふうにケアされているのかなという点を説明を求めました。","respondent":"齋藤住宅課長","answer":"５％ぐらい、生活保護の世帯がいらっしゃいますので、その方についてはお話をさせていただきたい。都の担当者の方からは、区が所掌すべきことについては、区が不安のないようにケアしたいです。","id":"exchange-049"},{"speaker":"中塚委員","kind":"質問・要望","question":"住宅をつくる、住宅があるということは、生きる上で最低限必要な施設ですから、きちんと国なり自治体なりが進めて当然の仕組みだと思います。請願については採択を申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/325823?Template=document&Id=3880#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":42145,"voices":131}},{"id":"h19-20070625-9","meetingId":"h19-cm06","date":"2007年6月25日","dateIso":"2007-06-25","committee":"文教委員会","time":"午前１０時０３分～午前１１時４８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件整理しています。","topics":[{"id":"topic-01","title":"第５６号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"第５６号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"ちょっと教えていただきたいんですが、変更というのは何かあるのかどうかということと、実態を教えてほしいと求めました。","respondent":"古里学務課長","answer":"平成１４年度から、法の一部改正に伴って区の条例となっています。平成１４年以降ですが、本制度の適用となる学校医等の公務災害の補償は１件もしてございません。","id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"それはそれですごくいいことなんですけれども、１つ、５年未満のところが額が減っていますよね。１０年、１５年という枠の中に入っておられるのか、改めてお伺いしたいなと思います。","respondent":"古里学務課長","answer":"こうした５年未満が減額、あるいは２５年以上は増額となった、その影響であると考えています。大半の方はほぼ継続ということで、１０年以上、１５年以上という先生方が大変多いと把握しています。","id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"５年未満に限らず、５年以上がどのくらいいらっしゃるのかという、そこもつかんでいなくてわからないということなんでしょうか。そこも含めてお願いいたします。","respondent":"古里学務課長","answer":"ただ、経験加算ということが重視をされて改定をされたと聞いてありますので、そのような結果になっているです。５年未満の人がどれぐらいいるのかということについては、今のところ数字として把握はしてございません。","id":"exchange-003"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"確認させていただきたいんですが、先ほど５年刻みということで、今、５年未満、２５年ということがあったんですけれども、１５年を境にして、１５年未満と１５年以上ということで減額改定と増額改定ということで先ほどお話を伺ったんですけれども、そこのところをもう一回説明していただけますか。","respondent":"古里学務課長","answer":"２０年以上２５年未満が１万４,２１９円が１万４,７４０円、２５年以上が１万５,５０１円、これが１万５,６８０円となっています。先ほど私の説明で１５年以上と申し上げましたが、１０年以上から経験加算というのが入っているです。","id":"exchange-004"}]},{"id":"topic-02","title":"平成１９年陳情第３号、区内中学校が成績一覧表冊子を都教委へ提出する際に個人名を消去するよう求める陳情","agenda":"平成１９年陳情第３号、区内中学校が成績一覧表冊子を都教委へ提出する際に個人名を消去するよう求める陳情","exchanges":[{"speaker":"西本委員","kind":"質問","question":"名前を出すと出さないとでは何か教育上の取り扱いのしにくさであるとか、何かあるのかなと、この辺はいかがか尋ねました。","respondent":"河野指導課長","answer":"これが平成１４年度、従来のようにパーセントの割合で評価されているのかどうかというようなことが厳しく審査される必要がなくなりました。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"そうすると、評価の方法が変わったということで、その変化に伴ったことで、現在は使うというのがなくなった、という理解でよろしいですか。陳情する方にもう少し今の事情等々がわかっていただければ、こういう形にはならなかったのかなと思いますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"南委員","kind":"質問","question":"自分の内申書が受験する学校に行っているというのはあって当然なんだろうと思っているんですけれども、東京都の教育委員会にも提出するということの意味というのはどういうことなのか、この際教えていただければと思うんですけれども。","respondent":"河野指導課長","answer":"あるいは東京都は学区制を敷いておりましたので、その学区の中に実際に住所があるのかどうかということまで含めて審査をしていた時期があります。第１学期の評定をもとに予備調査、そして第２学期の評定をもとに最終調査という形で、現在も提出を求めているものです。","id":"exchange-007"},{"speaker":"南委員","kind":"質問","question":"今の説明も伺って、なかなかそこは払拭されてはいないんですけれども、ずっともう何年も続いていることなんですか。だからこういうふうになっているんでしょうけれども、もう一つ東京都の教育委員会へ出すことの意味というのがちょっとよくわからないんですけれども。","respondent":"河野指導課長","answer":"東京都教育委員会では、適正な評価の実施のためにということで、研修等々も開いて、それぞれの学校が適正に評価できるように指導をしています。","id":"exchange-008"},{"speaker":"南委員","kind":"質問","question":"要するに、そうすると、受験のために学校側の、あるいは親の立場で考えてみると、少しでもよく評価してもらいたいという思い、心理が働いて、若干成績をよく評価して出しちゃう、そういうことを防ぐためのブレーキになるのがこれだという理解でもいいんか尋ねました。","respondent":"河野指導課長","answer":"公正かつ公平な評価をするためには、こういうチェックも必要であろうと考えております。","id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"１８年度からは出さなくなったということなんですが、こういう感じなのかという比較をする、これはそういうふうに使われるということなんですか。言っている意味がわからないか尋ねました。","respondent":"河野指導課長","answer":"例えば国語なら国語で５を与えた数であるとか、４を与えた数であるとかという、それを把握するための調査と理解しております。例えば先ほど平成１８年度入試からと申し上げましたけれども、平成１８年度入試というのは平成１８年１月から２月にかけて実施された入試ですが。","id":"exchange-010"},{"speaker":"南委員","kind":"質問","question":"既にやっているということなので、継続にする必要はないし、結論を出していいんじゃないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"山内委員","kind":"質問・要望","question":"いわゆる子どもたちに親がこうするんだよ、ああするんだよというような、そういう教育というものをちゃんと教えていくという必要性があるかと思って。そういうものを図書館で、そのような要望がございまして、この２点を私ども自民党は調査項目に挙げさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"金野委員","kind":"提案","question":"そこにお子さんが通っているお母さんたちからの１つの提案というか、要望も耳にするんですけれども、これは１つの要望というか。６歳児のお子さんがどういう、学校生活もうまくいく１つではあるかなと思うので、ここの調査研究を進めていきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"石田（慎）委員","kind":"質問","question":"もう１つは、全国大会に出場して非常にいい成績をおさめたということで、文武両道を目指す教育というのが必要なのではないかと。人がいなくて、例えば１つの学校は野球にすごい力を入れて、そういった各学校の特色を持っていくのはどうでしょうかということで３つを挙げました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"南委員","kind":"質問","question":"いろいろ多種多様にあるわけですから、これとこれが、私たちのもちろん要求も含めて判断していく以外にないんじゃないかなと思うんです。似ているところも、幾つか重なるところはありますので、正副のところにお任せしていいんじゃないかなと私は思うんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"南委員","kind":"意見","question":"だからそういう点では、もうちょっと文教委員会として深めて、勉強もしながら見ていければいいかなと思ったので出させていただきました。少しでも取り上げていただければありがたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問・要望","question":"ご年配の方たちもいらっしゃるわけですから、ちょっと別枠でとって議論していくのもいいのではないかなというところは思っております。そういう意味で、そこで議論するというところでちょっと整理していただいて、それで項目を決めていただきたいなという希望でおります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"市川委員","kind":"質問・要望","question":"それからどういう課題が出ているとかというのはぜひこの場で共有をして、教育改革についてはぜひこの場で取り上げていただきたいなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]},{"id":"topic-04","title":"今定例会の一般質問に関する所管質問でございますが、今定例会の一般質問中、文教委員会にかかわる項目","agenda":"今定例会の一般質問に関する所管質問でございますが、今定例会の一般質問中、文教委員会にかかわる項目","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"現状はどうなっているのかなというところのスケジュールの確認と、それから荏原西地区、今後の予定と問題の把握をさせていただきたいと考えています。教育委員会としてはどういうふうに感じられているのかということもお聞きしたいと思いますので、この３つをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"市川委員","kind":"質問・要望","question":"生活者ネットワークの井上八重子議員の一般質問に関してなんですけれども、石けんの利用促進をという質問項目です。調理代行というのはどういう順番で進めていくのかという定義みたいなものがありましたら教えていただきたいということと、。","respondent":"市川庶務課長、長田教育次長","answer":"これらについては、これまで文教委員会では大体３カ月から４カ月に１度ぐらいでまとめて進捗状況の報告をさせていただいてあります。今、まとめの作業をしていますので… こちらも今回の鈴木議員の一般質問の中でお答えさせていただいたとおり、今、教育委員会との最終的な詰めを行っているところです。","id":"exchange-020"},{"speaker":"西本委員","kind":"質問","question":"今の次長のご説明で一応わかったんですが、例えば考え方というのまではお話できない、それもだめですか。なぜするのかとかというところまでの公表も、教育委員会のところでの手順があるのでということで、それも難しいか尋ねました。","respondent":"長田教育次長","answer":"事務局の考え方としてはある程度整理をしている部分がありますけれども、一般質問とほぼ同じ回答になってしまうというようなことですので、その辺のところもご判断をいただければと思います。","id":"exchange-021"},{"speaker":"西本委員","kind":"質問","question":"では、次回にというスケジュールになるんでしょうか。７月のということになるんか尋ねました。","respondent":"長田教育次長","answer":"実は明日、教育委員会がございまして、その中でこの案件を諮る予定です。それは正副委員長と相談をして、その時期をいつにするかというような部分は協議をしてまいりたいと、このように思っています。","id":"exchange-022"},{"speaker":"西本委員","kind":"質問・要望","question":"あした教育委員会があって、そこでお話しになると、結論が出なければ継続になるんでしょうけれども、その状況によってはちょっと、なるべく早く情報をいただきたいなと考えていますので、何かしらお示しできるものがあればいただきたいと考えていますので、よろしくご配慮をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"その他のところでなんですけれども、大間窪小学校の給食代行の件なんですが、今年度から実施されたのかしら。その辺の関係で、違うのであれば違うでいいんですけれども、教えていただきたいと思うんです。","respondent":"古里学務課長","answer":"会社から品川区に対して、業者から辞退と申しますか、責任を持って業務を果たすことができないという相談がございました。どうしても経験のあるチーフ、やむを得ずこの代行業者については辞退届を受理し、違う代行業者にお願いしたという経緯です。","id":"exchange-024"},{"speaker":"南委員","kind":"質問・要望","question":"どこの業者なのか、改めて業者名、そして新しく入ったところはどこなのかを教えてほしいと求めました。２カ月、この辺の教育委員会としての認識はどういうふうになっているのか、そこもあわせて説明を求めました。","respondent":"古里学務課長","answer":"これらをきちっと業者と話をしながら契約を進めたいということで、この試行に対して参加をするという形でやってまいりました。評価ということでは、特段、今のところ教育委員会としては考えているものはございません。","id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"ですから私はこのところで、保育園で力量があったって学校給食とは全然違うということは、教育委員会は既に承知のことだと思います。初めての経験じゃないし、学校給食に調理代行を入れてきているのは何年間かの経験があるわけですから、その点についての認識はどうか尋ねました。","respondent":"古里学務課長","answer":"今後１年間これを継続していくというにあたって、品川区に迷惑をかけるわけにはいかないということから、事前にそうした申し出が出たです。","id":"exchange-026"},{"speaker":"南委員","kind":"質問","question":"１日のプログラムの中の給食の時間という時間にちゃんと出されていた、そういう実態があったんですか。調べていないんですか、調べているんか尋ねました。","respondent":"古里学務課長","answer":"学校には若干迷惑をかけましたけれども、１０分、１５分というふうなおくれが生じたという事例は認識しています。そうした指導を繰り返ししながらここまで来た時点での代行業者の変更ですので、そうした点もあわせてご理解をいただければと思います。","id":"exchange-027"},{"speaker":"南委員","kind":"質問","question":"そして午後の授業に臨むということになるわけですから、２回、そういうふうな認識で教育行政を担当されたらとんでもないと思います。現実的にこういう問題が起きているわけですから、業者を取りかえると、こういうことになっているわけですから。","respondent":"長田教育次長","answer":"学務課長が説明したような方式で選定をしたと、この手続自体は、手続自体には問題がなかっただろうと思います。ただ、給食の調理代行というのは、既に品川区で実施してきまして、これは定着をしてきた方法です。","id":"exchange-028"},{"speaker":"南委員","kind":"質問","question":"給食がおくれる、サービスの向上と言えるんですか。低下じゃないか尋ねました。","respondent":"長田教育次長","answer":"今回は、先ほど学務課長が説明しましたけれども、総合評価方式というようなことでの選定をしていったというようなことです。ですからそういう中で、今、説明したように、業者の熱意というのもヒアリングの中で重視する１つの項目です。","id":"exchange-029"},{"speaker":"南委員","kind":"質問・要望","question":"こういうことですから、現実的にはそういうふうにできなかったんだと、こういうことの結果なわけです。そこのところはきちんと認識をしていくべきだということを私は申し上げているんですから、そういうふうに受けとめてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問・要望","question":"できないときにはこのぐらいの期間でやめていただきます、かえますよというようなことは多分あると思うんですが、その点はいかがですか。強制力というか、リスクマネジメントの。","respondent":"古里学務課長","answer":"この業者が４月に入った時点から、そういう意味では、ずっとそういうふうなマネジメントはしてきたです。その結果、やはりやり切れないという業者の、指導になかなか従い切れないというところが出てきたというところから辞退に至ったです。","id":"exchange-031"},{"speaker":"西本委員","kind":"意見","question":"やはりありますので、そこをいかに何か起きたときの迅速な対応をどれだけとれるかが一番大切なことで、私たちはそれをチェックすべきだと思うんです。起きたときにどう処理したかということも大切だと思いますので、今後ますますよろしくお願いしたいと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"山内委員","kind":"質問","question":"１点だけ教えてください。これは契約的な部分になっちゃうんですけれども、今後そういうことはいかがなんか尋ねました。","respondent":"古里学務課長","answer":"ただ今回については、新規参入ではあるけれども、そうした職員を必ず持ってくることが可能だという業者の説明でございました。厳格な対応ということでいえば、今後も契約にあたっては同様の観点で業者の選定あるいは条件づけをしてまいりたいと考えています。","id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/120587?Template=document&Id=4604#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":28281,"voices":85}},{"id":"h19-20070625-5","meetingId":"h19-cm06","date":"2007年6月25日","dateIso":"2007-06-25","committee":"総務委員会","time":"午前１０時０２分～午後３時０８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を53件整理しています。","topics":[{"id":"topic-01","title":"２の議案審査に入ります。第４９号議案、職員の退職手当に関する条例の一部を改正する条例","agenda":"２の議案審査に入ります。第４９号議案、職員の退職手当に関する条例の一部を改正する条例","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"６カ月を１２カ月にした理由のところを教えていただきたいのと、この規定に当てはまるような職員は実際にいらしたのかどうか、これもちょっと説明を求めました。","respondent":"榎本人事課長","answer":"任期を１年間に限って、去年の４月から今年の３月で任期１年が切れるんですけれども、これについて該当している人が１件いらっしゃいます。","id":"exchange-001"},{"speaker":"菊地委員","kind":"質問","question":"法律のほうで一般と短時間ですか。短期間のところをなくした理由というのかな、そこをもう少し詳しく教えていただけますか。","respondent":"榎本人事課長","answer":"ただし、雇用期間が短くても救うべき人に対しては、解雇、倒産の場合には、今までどおり６カ月入っていれば救えるという形に整理したものです。そのほか、雇用保険３事業の見直しですとか、この被保険者の資格および受給者の要件の見直しというものが行われてきたというものです。","id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"１０月から施行だからあれかもしれないけれども、１０月過ぎると、その方の場合はどういう形になるんですかね。これまでの６カ月以上という規定から外れるわけですけれども、その方の場合は１０月１日以降、どういう形になるのか、ちょっとそこを。","respondent":"榎本人事課長","answer":"それから、例えば６カ月で正規職員をやめたとなると、その人についてはこの失業者退職手当の該当にはならないという形になります。これは任期付、任期なしにかかわらず、７カ月とか８カ月でやめた場合には、この失業者の退職手当の該当にはならないという形です。","id":"exchange-003"},{"speaker":"菊地委員","kind":"意見","question":"そうすると、任期を例えば１０カ月とかと区切ったときには、全く対象にならないことになっていくわけですよね。あるいは１０カ月であろうと、公務員法か何かで法的な部分というのがあるのかどうか、ちょっとそれだけ最後に聞かせてもらえますかとの意見を述べました。","respondent":"榎本人事課長","answer":"正規職員についても任期がありませんけれども、大体２年か３年ぐらいのところで、逆転してこの該当ではなくなるという形になります。それは民間についても同じく１２カ月以上被保険者期間がないと失業給付の対象にならないということなので、そこで整合性を保ってくるです。","id":"exchange-004"},{"speaker":"浅野委員","kind":"質問","question":"退職手当が出るけれども、一般企業の場合ですと、例えば退職をして失業給付が出るのは３カ月ぐらい先だったと思うんですね。それともまた一般企業と同じように、少し後になって出るのか、そこら辺をお伺いしたいんですけれども。","respondent":"榎本人事課長","answer":"区の正規職員の場合にはその該当でないという形です。実際には３３日たって、その２８日分の部分を払うという形になってきますので、民間企業と同じような形での支給となります。","id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問・要望","question":"１点だけなんですけど、第７条の４、これは非常にまれなケースですね。それがあったかどうかということと、あえてこれをまた明確にという考え方といいますか、その内容をお聞かせいただきたいと思うんですが。","respondent":"榎本人事課長","answer":"職層が高くいた在職期間が４０歳以上で長ければ長いほど、退職手当が多くなるという形で、そうじゃない限りには退職手当が低い水準になるという。説明したように、要は整理退職等であれば、その部分できちんと読みかえ規定を置いて明確にしたというものです。","id":"exchange-006"},{"speaker":"伊藤委員","kind":"質問","question":"その降格というのは非常にまれなケースでしょうから、そういう場合については、そういう理解でいいんでしょうか。それだけです。","respondent":"榎本人事課長","answer":"委員おっしゃるとおりだと思います。","id":"exchange-007"},{"speaker":"菊地委員","kind":"意見","question":"職員外で行政の仕事を担うという労働者が増えていく中で、行政そのものが雇用保険法に準じてこれを改正するというのは、基本的に反対をせざるを得ない内容だと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"土井委員","kind":"意見","question":"最終的に２社しか残らなかったということなんですけれども、こういう事例が多いというか、都合２社なんですよね。３、４社あったかもしれないという感じがするんですが、その辺をとの意見を述べました。","respondent":"中島経理課長","answer":"実際その後に、図面に基づいて試算等を各企業で行いまして、私どもで示している予定価格以内での入札ができないという判断を３社のほうでしたです。人手不足が生じていて、人件費が高騰しているというような理由で、予定価格内で工事できないというようなことが考えられるです。","id":"exchange-009"},{"speaker":"土井委員","kind":"質問","question":"２つぐらいお話があるように思うんですけれども、１つは、いろいろな要素で変動するわけですから。そういうものの見積もりが適切なのかどうかというものと重なっているんじゃないかという気もするんですけれども、その辺はどうお考えか尋ねました。","respondent":"中島経理課長、宍戸施設担当課長","answer":"それ自体が実態にそぐわないとかということは一概には言えないと思いますけれども、私どもの積算の段階では、そういった積算式に基づきまして計算をしているです。改定するんですが、やはり国ですとか都の基準自体が、こういうふうに急激にいろいろなものが高騰する時期には、少し追いついていけない状況です。","id":"exchange-010"},{"speaker":"土井委員","kind":"質問","question":"膨大なものですから、少なくとも基本的な基幹的な材料ぐらいはぽんと変えるとか、そういうことは１回もないんですかね。そのときはもっと安く落とすところも出てくるのかもしれませんけれども、その辺はどのようにお考えか尋ねました。","respondent":"宍戸施設担当課長","answer":"大きく改定するのは年に１回なんですけれども、部分的な改定というのは年４回行っております。このような時期ですので、年４回出ている小さいというか、部分的な改定もあわせて考慮に入れて積算をしております。","id":"exchange-011"},{"speaker":"土井委員","kind":"意見","question":"その上に立って２社というときには、どう考えますか。こういうものに対してどう考えるかとの意見を述べました。","respondent":"中島経理課長","answer":"先ほど申し上げましたこの予定価格、私どもが積算した予定価格以内でできないという会社が実際今回の場合は３社あったということで、どちらかというと残念な結果だったなというふうには思ってあります。","id":"exchange-012"},{"speaker":"伊藤委員","kind":"確認","question":"その間にどう考えても物理的に物価が上がっていくこともあるわけですから、そこで確認したいのが、品川区としての。さらに自分たちで積み上げていく、そういうお考えがまずあるかどうかということと、お考えがあることだけをまず説明を求めました。","respondent":"宍戸施設担当課長","answer":"工夫しながら内容に、それから、積算も変更して出し直していくということはあります。契約が成立したものにつきましては、そういうことで合意に達したものについては、そのまま契約するという考え方をとっているものです。","id":"exchange-013"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、契約されたことについてはいいとして、その金額でなぜ落ちたのか。確認したいのが、これは将来建て替えるべきでしょう。","respondent":"宍戸施設担当課長","answer":"それが１つ理由としてはありますが、もう１つ非常に大きいのが、今のボリュームは確保できないんですね。やはりあそこは重要な施設と考えておりまして、保育園も児童センターもシルバーセンターも図書館もあそこの場所で続けたいという認識があります。","id":"exchange-014"},{"speaker":"伊藤委員","kind":"確認","question":"だったら思い切って新しいのをつくったらいいんじゃないでしょうかということになりますよね。今回はこういう耐震改修ということですけれども、もう少しそのときの考え方を改めてお聞かせいただけると思うんですが、いかがか尋ねました。","respondent":"宍戸施設担当課長","answer":"耐用年数ですけれども、コンクリート躯体につきましては６０年から６５年という耐用年数があると言われています。２０年ぐらい同じ用途でいくと仮定すれば、手を入れて２０年間もたせるという選択もあるんじゃないか、そういう意味でも考えております。","id":"exchange-015"},{"speaker":"菊地委員","kind":"質問・要望","question":"さっきの予定価格のところで１つだけ教えていただきたいんですけれども、最初の説明ですと、都財務局の基準に基づいて積算をやってこの数字ですよと。そこでかかる費用を考えると、最初から実勢価格という見方はできないんか尋ねました。","respondent":"宍戸施設担当課長","answer":"何社かとって、実勢価格に近い金額で算定して、その２つを足し合わせる。だから、実勢価格により細かく対応し直して積算しているというやり方で、実勢価格そのものに合うような形というのはなかなか難しくなっております。","id":"exchange-016"},{"speaker":"菊地委員","kind":"質問","question":"ということは、その平米単価そのものが合っていないということのとらえ方でいいんですか。鉄骨材料が値上がりするだとか何とかというのは、それは当然あり得る話なんですけれども、基準そのものが。","respondent":"宍戸施設担当課長、田中総務部長","answer":"基本的にはつくられたときには合っているんです。合っているんですが、このような労務単価ですとか、材料費が高騰しているときには、少し追いついていけない部分が部分的に出てくるです。幸いにして２社入って、今回は私ども幸いにも予定価格内に入ったですので、その辺をまずお考えいただきたいと思います。","id":"exchange-017"},{"speaker":"原委員","kind":"質問・要望","question":"ですから、これは全体的な要望としては、そこを下げていただきたいという要望です。それからもう１点が、かかっていたんですけれども、これはリースということか尋ねました。","respondent":"中島経理課長","answer":"南大井保育園の仮設園舎のご質問だと思いますけれども、これにつきましてはリースでございまして、工事も含めた形で借り入れていくです。もちろんこの工事とは別の契約です。","id":"exchange-018"},{"speaker":"原委員","kind":"質問","question":"これには細かくは書いていないんですけれども、３７年前ですから、普通は改修工事があっても、アスベスト調査とか、この辺というのは、ちょっとこれは視点がずれるんですが、その辺もちょっとお聞かせほしいと求めました。","respondent":"宍戸施設担当課長","answer":"アスベスト調査はやってございまして、機械室にアスベストがございまして、こちらも今回の工事に合わせて行うです。","id":"exchange-019"},{"speaker":"原委員","kind":"質問","question":"それに関しての金額というのは入っているという解釈でよろしいか尋ねました。","respondent":"宍戸施設担当課長","answer":"今回の議案審査でご提案している本体工事の中に入ってあります。","id":"exchange-020"},{"speaker":"浅野委員","kind":"意見","question":"例えばこの５ページですとか６ページ、応募を受け付ける段階では、最初の説明ですと出していなかったという説明があったと思うんですね。その後のご説明ですと、これは基本的なやり方としてはどういう手順でやられているか、１回ご説明ほしいと求めました。","respondent":"中島経理課長","answer":"それに基づいて具体的な詳細まではっきりわかるということでございまして、ですから、その点で申し込みと実際の入札とタイムラグが当然あります。その間できちっとした詳細の計算した中で、実際に最終的に入札するか、あるいはしないかということを判断できるです。","id":"exchange-021"},{"speaker":"浅野委員","kind":"質問","question":"これだと約２億１,０００万円ですけれども、おさまるかどうかという検討をして、今回の結果ということでよろしいでしょうか。そうした場合に、５ページ目ですとか６ページ目の図面は、購入した資料の中には入っているということでいいんか尋ねました。","respondent":"中島経理課長","answer":"もっと詳しい図面が、設計図も含めてあります。","id":"exchange-022"},{"speaker":"井桁委員","kind":"質問・要望","question":"先ほど図面をいただいたんですけれども、人工芝を入れてやっていて、野球場のラインというのを入れて完成という形なんでしょうか。勉強不足で教えていただきたいんですが、利用としては野球のできる多目的広場とあるんですが、聞かせていただきたいなということがありますけれども。","respondent":"松代管理工事課長","answer":"そういったことから、フットサル、サッカー等のラインは今回、色を少し変えるような形で入れたいと考えています。こういった方法も併用してやっていければと考えているところです。","id":"exchange-023"},{"speaker":"井桁委員","kind":"質問","question":"もう１つだけちょっとお聞きしたいんですけれども、ここの完成予想パースというところで見る限りですと、休憩をするような場所であったりとか、あと休む場所、見る場所というのは、まだ考えておられないということか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"菊地委員","kind":"質問・要望","question":"こういうのは２社になっている理由なんかがあれば教えていただきたいのと、もう１つ、割合をちょっと説明を求めました。","respondent":"中島経理課長、日下部企画財政課長","answer":"ですから、今回で言えば親が４社ですから、４つの組める可能性があったんですけれども、実際にうまく組めたのが２社だったです。それと２社だけでやった入札ですけれども、結果として、落札率でいいますと９４.９％という落札率で… 都市計画交付金ということで財源上の措置がありますけれども、この程度の規模のものについては、国とか都の補助金等については対象になりません。ただ財調算定の対象にはなってくるというものです。","id":"exchange-025"},{"speaker":"菊地委員","kind":"質問","question":"最初の質問のほうなんですけれども、１グループ、２グループ。それぞれのグループ、いろいろな組み合わせでたくさんの共同企業体が応募してくるという、実例としてそういうものはあるんか尋ねました。","respondent":"中島経理課長","answer":"工事の種類とか額によりますけれども、例えば１０社近くのＪＶが結成されることもよくあります。今回は非常に少ない例です。","id":"exchange-026"},{"speaker":"土井委員","kind":"質問","question":"今、この公園がもともとお返しをした部分との関係じゃなくて、都との関係の深い中身ですよね。そういうことでの何か、何もないか尋ねました。","respondent":"松代管理工事課長","answer":"そこで２件の死亡事故が起こったということから、シャーシー置き場に変換して、この安全対策に全力を注ぐということでやってきていました。こちらからお持ちをしまして、都市計画の手続等を経まして、品川区のほうに移管された、こんな動きになっているところです。","id":"exchange-027"},{"speaker":"土井委員","kind":"質問","question":"前のところも無償ですからね。代替えのものをくださいと言っているんですから、そう簡単じゃないのもよくわかっていて、よくぞいただけたという見方もあると見ていいんですかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"浅野委員","kind":"質問","question":"今回のデジタル移動通信システム導入の件ですけれども、細かいことをお伺いするんですけれども、１３ページの図面で可搬局が９３ということで訂正されたんですが、統制局というのは防災センターの中にある親分となるような施設だという認識でよろしいんか尋ねました。","respondent":"久保田防災課長","answer":"そのとおりでございまして、防災課の隣に機械室というのがありますけれども、ここが無線の基地局になってあります。","id":"exchange-029"},{"speaker":"浅野委員","kind":"意見","question":"それ以外のところはビジーになって通じないということなのかどうかということと、もう１つ、わざわざ可搬型にしている理由ですね。これをお聞かせほしいと求めました。","respondent":"久保田防災課長、中島経理課長","answer":"２つ目、３つ目になるかと思いますけれども、このデジタル化はかなりコンパクトになってあります。同時回線が８回線ということですけれども、それでも８回線あるので、かなりその点では融通できるという話です。 先ほどのアンテナが２つ立っているということですが、これは地域的に電波の死角ができないように、アンテナを２基設置しているです。","id":"exchange-030"},{"speaker":"浅野委員","kind":"質問","question":"先ほどの同時接続回線が８回線というところで、このぐらい使われるのではないかという見積もりというんでしょうか、それが８回線以内におさまるという考え方でいらっしゃると思ってよろしいんか尋ねました。","respondent":"久保田防災課長","answer":"いっぱい確保回線があれば一番好ましいんですが、とはいいながら、これは無線ですので、いわゆる許可の部分も含めて限界があります。応急対策本部を設置しますけれども、そのときにも大体６回線を確保しておりますけれども、今回こういう形になっているです。","id":"exchange-031"},{"speaker":"浅野委員","kind":"質問・要望","question":"現行が移動系と地域防災無線で合計で１５８ありまして、今回１７６で１８局ぐらい増えるんですけれども、増えた理由を教えてほしいと求めました。","respondent":"久保田防災課長","answer":"今回、従来あった移動無線と従来あった地域防災無線を合わせまして１７６局確保しています。これからもそういう形での必要な局数は出てくるだろうということで、そういう点では少し余分に局数も持って、最大限確保していくという状況です。","id":"exchange-032"},{"speaker":"伊藤委員","kind":"質問・要望","question":"デジタル系にするメリットということを説明していただきたいのと、それから、屋外スピーカーのところは変更なしですよね。屋外スピーカーは現状のままというのは何か理由があると思いますので、なぜ屋外スピーカーはそのままなのかということと２つお聞かせいただきたい。","respondent":"久保田防災課長","answer":"先ほど経理課長が説明したとおり、国の方針が１つありまして、一番大きな理由です。それともう１つは、老朽化したスピーカーを取り替えていく予定ですので、今回は見送っているという状況です。","id":"exchange-033"},{"speaker":"伊藤委員","kind":"質問・要望","question":"確認したいのは、この契約案件の中に、ただ声だけじゃなくて、映像を送るとか、そういうこともデジタルは自由にできるはずなんですよ。確認いただきたいのと、デジタル化のメリットはもっと発揮できるはずですので、そのことの考え方を説明を求めました。","respondent":"久保田防災課長","answer":"今、委員がおっしゃられたように、デジタル化のもう１つのメリットというのは映像とかデータ通信ができるということだと思います。私ども一番今最大限に重視しているのは、音声でもっての会話をまず確保したい、確実にやっていきたいという思いで今回お願いしているものです。","id":"exchange-034"},{"speaker":"伊藤委員","kind":"質問","question":"デジタルシステムのメリットはもっとあるはずですから、２６０MHzに合わせれば映像が送れるわけですから、そういうことの可能性も検討してくださいとお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"土井委員","kind":"質問","question":"新しいのはデジタルにする。となるとこの古いものが残るんですけれども、古いものはどうなるんか尋ねました。","respondent":"久保田防災課長","answer":"古いものというのは、今の移動無線とかあるいは地域防災無線、廃棄処分にするという形になるかと思うんですけれども。","id":"exchange-036"},{"speaker":"土井委員","kind":"質問","question":"場合によっては金をくれという場合も当然起こるわけですから、そのようになるので、今どう考えているのかなということが聞きたかったわけです。それらのものをうまく活用できるということも含めて考えなきゃいけないものですから、ちょっと聞いてみました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"菊地委員","kind":"質問","question":"１つだけ教えてもらいたいんですけれども、こういうものの予算を組むときに、この中では消防署とか警察署がありますよね。消防署だったら消防署の予算でそういうものを含んではいけないのかなという気がするんですが、ちょっとその辺、あれば。","respondent":"久保田防災課長","answer":"通常、こういう無線を設置するときには、本もとである区のほうで全部用意してそれぞれ配備するということが多くあります。同じ関係じゃないかと考えています。","id":"exchange-038"},{"speaker":"菊地委員","kind":"質問","question":"そうすると、この数字というのは、総務省の方針ということですけれども、国なり都なりからこれも出てくるという考え方なんか尋ねました。","respondent":"久保田防災課長","answer":"今のところそういう対象から外れているという状況はありますけれども、現在、東京都の補助金担当のほうに今かけあっている最中です。今のところはそういう交渉中ですので、何とも言えないんですけれども、そういう制度はあるです。","id":"exchange-039"},{"speaker":"菊地委員","kind":"質問","question":"交渉中ということは、総務省の方針なんだけれども、２３区すべてでこれが行われるわけではないということなんか尋ねました。","respondent":"久保田防災課長","answer":"総務省の方針として、この地域防災無線を持っている自治体は全部切りかえるようになるかとは思っています。例えば私どもが今までやってきたので言えば、同じ総務省の中にある消防庁関係の予算として、補助金なんかの対象になっていたという経緯はあります。","id":"exchange-040"},{"speaker":"原委員","kind":"意見","question":"これも入札関係、さっき２社残って安いほうということで決まっておりますけれども、全体的には１３ページを見てわかるんですが、スペック、これの仕様関係に関しては、全く同一の基準で出てきているのか、ぶれがあるのか、聞かせてほしいと求めました。","respondent":"中島経理課長","answer":"これにつきましては、当然同一の仕様に基づいて行っているです。","id":"exchange-041"},{"speaker":"原委員","kind":"質問","question":"その辺は、盗聴器は意外と簡単に拾えるという可能性もあるんでしょうが、この辺の金額であれば。ただその辺のところ、具体的なことがもしあれば、ちょっと教えてほしいと求めました。","respondent":"久保田防災課長","answer":"電波ジャックの関係なんですけれども、以前、１０年ぐらい前になるんですかね。当然今回のこの機器に関してもそれは込みということで、電波ジャックの防止機器が入っているという形です。","id":"exchange-042"},{"speaker":"原委員","kind":"質問・要望","question":"それもどんどんいろいろ新しい攻め方で来ていると思いますので、その辺は要望としてご注意をお願いしたいということと、あと非常に具体的な細かい点なんですが、車両３基というのは、その辺をちょっと教えてほしいと求めました。","respondent":"久保田防災課長","answer":"車両３基は、特にこういう震災になったときには、防災課所有の車、公安委員会に許可を得て、サイレンが鳴らせるような装置もついております。そこに設置する予定です。","id":"exchange-043"}]},{"id":"topic-02","title":"に移りたいと思います。 先ほど報告事項の(1)については終わっておりますので、(2)を議題に供します。中小企業センター耐震補強及び大規模改修工事（Ａ棟）請負契約","agenda":"に移りたいと思います。 先ほど報告事項の(1)については終わっておりますので、(2)を議題に供します。中小企業センター耐震補強及び大規模改修工事（Ａ棟）請負契約","exchanges":[{"speaker":"土井委員","kind":"質問","question":"今、Ａ棟のお話がありましたけれども、体育館のところはしなくても大丈夫だという意味でしょうかというのが１つですね。","respondent":"宍戸施設担当課長","answer":"今回実は別途発注する予定です。持っていく機械が大き過ぎるというのも１つ理由にありますけれども、１回工事として発注すると、それで別の発注でやらせていただくです。","id":"exchange-044"},{"speaker":"土井委員","kind":"質問・要望","question":"もう１点は先ほどもちょっと忘れたんですけれども、耐震補強だものですから、さっきの南大井のほうも含めてお聞かせいただきたいんです。役所レベルというだけでも違いますから、そのレベルはどうなんか尋ねました。","respondent":"宍戸施設担当課長","answer":"南大井複合施設につきましては、児童施設は全般的にそのように取り扱っているんですが、学校と同じ、Ｉｓ値０.７５という目標値にしております。中小企業センターにつきましては、耐震補強の規模その他した上で、Ｉｓ値０.６という法定の基準にさせていただきました。","id":"exchange-045"},{"speaker":"土井委員","kind":"質問","question":"1)、2)、幾つまであるかわからないですけれども、その残りの丸はどうなっているんか尋ねました。","respondent":"中島経理課長","answer":"1)、2)というふうに整理したものでございまして、建物の構成……。たくさんあるそうです。","id":"exchange-046"},{"speaker":"土井委員","kind":"意見","question":"やってくれという意味じゃなくて、要するに子どもたちがそこでいろいろ作業をしたり、授業をしたりするような場所が、1)、2)で全部なんですねと。いわゆる補強をしなきゃならんとか何とかいう以前のもの、関係ないものなんですよということを聞けば安心するんですとの意見を述べました。","respondent":"宍戸施設担当課長","answer":"今、委員の話にあったとおりです。","id":"exchange-047"},{"speaker":"土井委員","kind":"意見","question":"ただ物置までやれるかやらないかはいろいろあるけれども、そのレベルのところは、今回調べたけれども大丈夫なんですねと言ったんです。今回調べたけれども、今回の工事には入ってきませんよということなのかとの意見を述べました。","respondent":"宍戸施設担当課長","answer":"これが1)、2)棟です。それからもう１つ、言葉が足らずに説明不足でしたけれども、対象外になってあります。","id":"exchange-048"},{"speaker":"原委員","kind":"意見","question":"具体的にですけれども、ＳＲＣブレースに関して、８本入るということなんですけれども、岩盤まで届いているのかどうかなのかということをお教えほしいと求めました。","respondent":"宍戸施設担当課長","answer":"当初、杭を打たなくても大丈夫かなとこちらで踏んでいたんですが、評定機関のほうの指導により打つことになったものです。長さは７ｍで径も２０cm余りで、非常に小型な住宅等で使う簡易な杭です。","id":"exchange-049"},{"speaker":"伊藤委員","kind":"確認","question":"要は耐震改修についてはこういうメニューでしなさいということが決まっているんですかということを１つ確認したいのと、そういう基準があってこういうふうに耐震工法を選んだんですかということなのか、その基準を説明を求めました。","respondent":"宍戸施設担当課長","answer":"これをもっとたくさん建物の内側に設置するという方法も１つにはありますが、夏休み期間中という短期間に、その工法を選択した。したがいまして、これをどういうふうにやるかという工法の選択は我々のほうで、教育委員会とも相談しながら決めさせていただきました。","id":"exchange-050"},{"speaker":"伊藤委員","kind":"質問・要望","question":"メニューは品川区独自の対応で変えられるというわけですから、もとの意味は経済効果を考えながら、お墨付きをもらいながらいい工事をやる。ああするとかいうものは、あったと思うんですけれども、あえてこれを選んだということについての確認のお話をもう少しいただきたいと思うんですが。","respondent":"宍戸施設担当課長","answer":"それぞれの学校で比較検討はすべてしております。比較検討した上で、一番いいと思われる工法を、それなりに学校に応じて選んでいくです。","id":"exchange-051"},{"speaker":"伊藤委員","kind":"質問","question":"先ほどの答弁の中でお墨付きをもらうという話がありましたよね。だから、それをどこからどういう形でお墨付きをもらうかということを最後に教えてもらいたいと思います。","respondent":"宍戸施設担当課長","answer":"国交省の認定した機関で、東京都の場合７社ぐらい認定されております。その中から我々のほうで選びまして、そこのお墨付きをもらうです。","id":"exchange-052"}]},{"id":"topic-03","title":"大原小学校1)・2)棟耐震改修工事請負契約","agenda":"大原小学校1)・2)棟耐震改修工事請負契約","exchanges":[{"speaker":"林委員長","kind":"質問・要望","question":"これまでの総務委員会の行政視察の調査事項等について、あらかじめ参考資料として配付されておりますので、ご参照、ご確認をほしいと求めました。〔「はい」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/495406?Template=document&Id=1752#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":41738,"voices":166}},{"id":"h19-20070626-6","meetingId":"h19-cm06","date":"2007年6月26日","dateIso":"2007-06-26","committee":"区民委員会","time":"午前１０時０４分～午後 ２時３０分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"稲川委員","kind":"質問","question":"報告第１６号のほうなんですけれど、先ほど接触してけががないという話だったんですが、車と自転車ですから、よくありがちな後からどうこうとか、そういう話には、２月ですからもうないと思うんですけれど、その後はどうか尋ねました。","respondent":"島袋品川区清掃事務所長","answer":"事故のほうは保険会社と接触しまして、解決しております。","id":"exchange-001"},{"speaker":"山路委員","kind":"質問・要望","question":"ちょっと確認をさせていただきたいんですが、この損害賠償額は保険会社と交渉されて、和解されたということで当然、保険会社から支払われるものですよね。","respondent":"島袋品川区清掃事務所長","answer":"今、山路委員がおっしゃったとおりでございまして、保険会社から払われているです。","id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"車の保険なんですけれど、これは直営の車両の場合にこういう専決処分が出るんですか。そうすると、そういうときはこういう報告に乗ってくるんか尋ねました。","respondent":"島袋品川区清掃事務所長","answer":"専決処分の場合は直営車、我々が持っている車の事故だった場合には報告するんですけれど、雇上車の場合は、雇上会社とその被害者と民民でやりますので、専決処分には乗ってこないです。","id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"質問","question":"例えば２月に事故が起きて、けががなかったということで幸いなんですけれど、我々に何の報告もどこにも出てこないわけですよね。逆に言うと、役所の中でも担当部署しかわからないのかもしれませんが、何か事故が起きたということをほかに伝える方法はないんか尋ねました。","respondent":"島袋品川区清掃事務所長","answer":"重大な事故が起きましたときには報告する場合もあると考えられますけれど、今のところは重大なものはありませんので、ケース・バイ・ケースで考えるしかないかなと思うところです。","id":"exchange-004"},{"speaker":"山路委員","kind":"質問","question":"大崎第二の２９日は３時までということなので、参議院選挙とぶつかっているのは影響ないんでしょうか。夜はないということなんか尋ねました。","respondent":"中山地域活動課長","answer":"基本的に、投票所とバッティングしていないところにつきましては当初の予定どおりやっていきたいということで、実際に実施しているものです。そういう意味では影響のない範囲でやっていこうという判断をさせていただいたものです。","id":"exchange-005"}]},{"id":"topic-02","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"鈴木（真）委員","kind":"意見","question":"この２２日の週でいいと思うんですけれど、その中で２２日からとか、２３日から、２４日からというスタートの日まで決めちゃうのかどうか。できればもうちょっと、時間もわからないのでとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"安藤委員","kind":"提案","question":"１１月よりは、今、委員長が提案されたほうがいいですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"稲川委員","kind":"質問","question":"委員長は可能なんでしょうか。月、火、水じゃなくて、火、水、木とか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"稲川委員","kind":"質問","question":"そういうのはどうなんですか、この視察の中で。ただ行政対行政で行って、ただ視察に行きますよで、こういう取り組みをしているということを口頭で説明を受ける、そういうものになるんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"稲川委員","kind":"意見","question":"東海道はよく宿場祭りをやりますけれど、普通の平日の東海道を視察で回ってというと、何かピンと来ないんじゃないかなと。ただ行って視察というか歩くだけなのか、何かにぶつけて視察をするのかとの意見を述べました。","respondent":"川西委員長","answer":"それから時期が定例会と定例会の間に実施しますので、なかなか難しい。それから市の受け入れ体制、市役所もみんな総出で出ておりますので、まず難しいということになります。","id":"exchange-010"},{"speaker":"安藤委員","kind":"意見","question":"どういうふうに工夫しているのかというのを見に行くという意味では、富山市とか、ふだんのそういうものを見に行ってもいいのかなと思います。そのまちの何をどういう事業を見に行くかということが先にあって、で、結果としてどこかというふうに考えていくんですよねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"調査票の中身自体を一緒につくっていく感じのイメージでいいんでしょうか。商店街に限らずいわゆる大企業の皆さんにはどういう調査をされているのかなと思って、ちょっと知りたいなと思いまして、一応参考に。","respondent":"田村環境課長","answer":"実はもう進めているんですが、リサイクル団体とジョイントを組みまして、区内の大手スーパーのマイバッグの取り組みの調査を進めています。","id":"exchange-012"},{"speaker":"飯沼副委員長","kind":"質問","question":"経過をお伺いしてわかったんですが、選び出した後どうするのかなというのと、今後についても何かありましたら。","respondent":"田村環境課長","answer":"今はアンケート調査を実施中なので、そのアンケート結果を踏まえて、実際に学生さんが何回かおじゃまをして実態を把握する。来年度以降も、ああいう取り組みだったらうちも取り入れようとか、全体が底上げできるような取り組みができればと考えているところです。","id":"exchange-013"},{"speaker":"飯沼副委員長","kind":"質問","question":"予算的には何か手だてはされているんでしょうか。ぜひ今後に生かしていきたいということなら。","respondent":"田村環境課長","answer":"予算的にはほんとうに事務的な、紙とかそういう経費で全体で４７万円ほど予算計上しまして、学生さんのほうは授業なので無償で、授業の一環としてやっていただくと。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"意見","question":"事務事業概要の中に、この「地球にやさしいお店発見」というものが既に出ているんですが、この前に「エコクリーン店認定事業」がちょうど出ている中で、今回の分はエコクリーン店に結びつけていく感じなのか。","respondent":"田村環境課長","answer":"事業自体は平成２０年度まで、平成２１年３月まで継続します。これから申請されたものも平成２０年度が最後のおしりになりますので、いずれ平成２０年度以降はこちらのほうに移行していくという形になります。","id":"exchange-015"},{"speaker":"飯沼副委員長","kind":"質問","question":"ちょっと１つだけ。事業期間が１年間ということで、事業主体が青物横丁商店街振興組合ほか７商店街ということで、経過をお伺いできたらと思います。","respondent":"金子産業振興課長","answer":"ただ、それぞれの理解を得て実施しやすい部分があるんですけれど、１つ１つの個店に対してつかんでいただくのは難しかったということがあります。平成１８年度にこの事業を実施した以降、「じゃあ、それについては平成１９年度でも実施していくという実態があります。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"主にまちなみ、どう景観をつくるかというところで話し合って、今回事業として実施したということでよろしいんですか。東京都の事業というのはどういうもので、そこら辺の兼ね合いといいますか、お伺いしたいと思います。","respondent":"金子産業振興課長","answer":"先ほどちょっと簡単にご説明してしまいましたが、こういったものを支援していこうというもので、また今年度は３件という予定になっておりまして。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"その東京都と区がやっている事業名だけちょっと教えていただきたいんですが。その枠組みを使って今回はまち並みを整備されたということなんですけれど、その枠組みの名前といいますか。","respondent":"金子産業振興課長","answer":"で、この形に合わせた形で今回実施したのが「東海道周辺まちなみ整備事業」であると。区として実施した事業名ということで、名前がたくさんあるのでちょっと混乱しやすいかと思いますけれど、ご理解いただければと思います。","id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/598842?Template=document&Id=2490#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":15559,"voices":81}},{"id":"h19-20070626-7","meetingId":"h19-cm06","date":"2007年6月26日","dateIso":"2007-06-26","committee":"厚生委員会","time":"午前１０時０２分～午後１時５２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を52件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"どのくらいの所帯を予想されているかどうか、事業について申請があるかどうかということが１点。委託業者が１社で載ってきていますけれども、この１社に決められた根拠というのか、１社に限定された状況というのを説明を求めました。","respondent":"蓼沼高齢福祉課長","answer":"そして、３年間かけて時限的に段階的に実施していこうということで考えてございまして、大体予算的には約１,０００万円程度というものです。","id":"exchange-001"},{"speaker":"山元委員","kind":"質問・要望","question":"ちょっとお伺いしたいのは、また再申告して、またそして４分の１をお支払いするのか。この対象にはならないんですが、それ以外、対象外の方にも何かそういう補助的なことをお考えなのかを教えてほしいと求めました。","respondent":"蓼沼高齢福祉課長","answer":"これにつきましては、今、区で設置を予定している機種は、電池が１０年保つというタイプのものです。１０年後、事業の進捗を見て、今後の対応についてはまた検討を進めてまいりたいというふうに考えております。","id":"exchange-002"},{"speaker":"須藤委員","kind":"質問・要望","question":"平成２２年から全部義務化されるということになってくると、このあたりに対する配慮というのもしっかりＰＲをしておいてあげていただきたい。高齢者の住宅だと、まがいものがいっぱい出てくる気がしてならないので、そのことを気をつけるようにひとつお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ガス漏れ警報器というのも義務化されているのでしょうか。そこら辺のところのちょっと制度的な基本的なところでお聞かせいただきたいのですけれども。","respondent":"蓼沼高齢福祉課長","answer":"これについては、さっき出ておりましたけれども、平成２２年４月からは既存の住宅に義務化がされる。まだ義務化はされていないと思います。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"何万円もするものを東京ガスがつけていったんですけれども、ちょっとお聞きしたいんですけれども、これはまたちょっと別なところで調べます。それともう１つ、ここのところでは、それはそのまま続けてされるということでいいのか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"自動消火装置の給付事業のお尋ねですけれども、それについては変わりなく実施をしてまいります。","id":"exchange-005"},{"speaker":"堺委員","kind":"確認","question":"２点ほど確認させてください。来なかったので、この場で申しわけないんですが、ちょっとご説明いただけますか。","respondent":"高橋障害者福祉課長","answer":"障害者のみの世帯か、今回の消防法の義務化に伴いまして、今までの対象者を７月から拡大ということで予定しております。障害者手帳の３級の方までに拡大し、また愛の手帳の方については３度の方まで、１・２級の方まで拡大する予定でおります。","id":"exchange-006"},{"speaker":"堺委員","kind":"質問","question":"費用については３％から１０％ですか。その負担割合は、どういう人が３％で、どういう人が１０％になるんか尋ねました。","respondent":"高橋障害者福祉課長","answer":"給付ですので、私どもに申請しますと、ケースワーカーがお伺いしまして、状況を確認した上で設置をお願いするというようになります。費用負担については、先ほど申し上げた部分で一部負担していただくものです。","id":"exchange-007"},{"speaker":"堺委員","kind":"質問","question":"業者なんですが、高齢者についても、障害者についても、一括してこの和田商会というところになるのでしょうか。要するに、この和田商会という会社の規模が私は全くわからないので、その辺の業者選定についての考え方もあわせて教えていただけますか。","respondent":"高橋障害者福祉課長、蓼沼高齢福祉課長","answer":"障害者の業者ですが、日常生活用具給付ですので、１社ではなくて、日常生活用具の登録業者ということで、何業者かありますので、設置するときに訪問した段階で、ここのところもありますということで周知しているものです。業者についての考え方ですけれども、平成１９年度の措置をした予算で実施するということにおいて、今後３年間使っていくということではございません。","id":"exchange-008"},{"speaker":"堺委員","kind":"質問","question":"今回、設置業者については高齢福祉課としては、この１年間、和田商会という１社に決定したからこれにしたんですが、障害者のほうの登録業者というのは、ちょっとごめんなさい、幾つぐらいあるんか尋ねました。","respondent":"高橋障害者福祉課長","answer":"そこのところでこの火災警報器を設置しているのを得意とする業者が何社あるかというのは、ちょっとピックアップはできないような状況です。そこの中でここの業者、何社かというのを具体的にここでお答えすることはできないので、ご理解いただければと思います。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"この障害者のほうは、自立支援法の地域生活支援事業の中でやっているという事業ではないのでしょうか。そこのところをちょっと確認させて下さい。","respondent":"高橋障害者福祉課長","answer":"この日常生活用具の給付につきましては、昨年の１０月から地域生活支援事業で行っているものです。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうですか。そこら辺のところは、なぜ１社になったのかということについて、もうちょっとお聞かせいただけますか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"複数社ということになりますと、経費といいますか、費用についての対応が違ってくると思います。なるべく予定の金額の中で入札をして、そこで落札した業者にお願いをするということで、今回はこういう形で対応したものです。","id":"exchange-011"},{"speaker":"宮崎副委員長","kind":"確認","question":"ちょっと確認したいんですけれども、そこのところをちょっと１点確認したいのと、やっぱり心配なんですよね。そういうふうな対応というのは、これはできないのかどうなのか、ちょっとそこら辺はどうか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"６０歳代の後半の方等で、設置したほうが適当ではないかというようなことが考えられるようなケースについては柔軟に対応していこうということで。","id":"exchange-012"},{"speaker":"宮崎副委員長","kind":"質問","question":"火災報知器は年に１回、２回、点検もこの業者に一緒に委託ということになるのでしょうか。その場合の費用はどういうふうになるのか、そこら辺のところはどうか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"ここの警報器の点検については、特段、今回、想定はしてございません。その機器の安全性といいますか、持続性についてはそういう検定をパスして、一定程度担保されているというふうに考えてあります。","id":"exchange-013"},{"speaker":"宮崎副委員長","kind":"質問","question":"そうすると、この電池が切れるかどうかだけが問題であって、定期的な点検は必要ないという、そういう機種だということでいいんか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"そういうタイプだというふうに考えております。","id":"exchange-014"},{"speaker":"本間委員","kind":"意見","question":"この「新たに」というのと、その活字が強調されている部分、非常に重要な部分ではないかというふうに受けとめました。この表現について、ひとつまずお答えをお願いしたいと思いますとの意見を述べました。","respondent":"蓼沼高齢福祉課長","answer":"新たに給付事業を開始するという、そういう背景がありまして、この設置の義務化というものが法制化されたという状況です。あるいは区議会等からも火災警報器の設置については何回かご質問をいただいているような、そういう意味では、今まで実施していなかったものですから。","id":"exchange-015"},{"speaker":"本間委員","kind":"質問・要望","question":"なぜ今話をしていますかというと、地域によって違うかもしれませんけれども、すぐ丸投げしてしまう民生委員が多く見られます。そのようなことがありまして、特にこの部分は人の家の中に入るものですから、そのことについてのご見解をほしいと求めました。","respondent":"蓼沼高齢福祉課長","answer":"そちらのほうでご説明してＰＲするとともに、そういったときにも機会をとらえてＰＲをしていただくようにお願いをしています。消費者センターとも連携をとりながら、慎重といいますか、丁寧に進めてまいりたいと考えています。","id":"exchange-016"},{"speaker":"本間委員","kind":"質問・要望","question":"言葉遣いだとか、それから服装なんかも、きちっとした服装で人のうちに入るときに気をつけていただくようなことも指導していただきたい。服装とか言葉遣いについてのことの間違いがあったようですので、その辺も何かの機会にお伝えしてほしいと求めました。","respondent":"高橋障害者福祉課長","answer":"先ほどの日常生活用具の登録業者の件ですが、住宅設備等日常生活用具の、いわゆる警報器の取り付け等の業者が１８社あります。","id":"exchange-017"},{"speaker":"須藤委員","kind":"質問","question":"８月１日から適切なということなんだけれども、それからもう１つ、一緒に今ケアされている方々と一緒に面倒を見てもらうような形がいいと思うんです。今度、そのあたりはどうなるのかなという心配がやはり地域の方々がしていらっしゃるので、そのあたりはどう考えているのか説明を求めました。","respondent":"蓼沼高齢福祉課長、木下福祉高齢事業部長","answer":"今、協定に違反したですので、これについてはコムスン社のほうも品川区の場合は別途対応すべきですねということで話を進めているところです。今回なかったわけですけれども、品川区といたしましても、当然… コムスンの品川区のほうで対応した経過ですけれども、面接をいたしましたのは私でしたが、独自の地方のホームヘルプを中心とした事業者でありました。","id":"exchange-018"},{"speaker":"須藤委員","kind":"意見","question":"ありがとうございました。他の２事業者という表現をしているけれども、かといって、そのあたりはどういうふうに考えていますかとの意見を述べました。","respondent":"蓼沼高齢福祉課長","answer":"それぞれ努力をしながら、いろいろな研修について支援を行ったりとか、これについては１つの今後の大きな課題ではあろうというふうに考えております。","id":"exchange-019"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"ちょっとそこのところがどうなっているのかという、要するに、どういうことで中延のところの協定を解除するということになったのかということが１つ。ここは品福だったかと思うんですけれども、ちょっとそこの品川区とコムスンとの関係のところをもう１回教えてほしいと求めました。","respondent":"蓼沼高齢福祉課長","answer":"従業員のことを考えれば、速やかに新たな事業者に変更したほうがよろしいだろうということで、協定に違反したということで協定を解除するです。速やかに事業者を変更して、問題がないように適切に移行するということで、今回こういうような措置をとっているというものです。","id":"exchange-020"},{"speaker":"宮崎副委員長","kind":"確認","question":"そこのところの確認をしたいのと、１つは、そのときの考え方というのはどういうふうにされていくのかということをちょっとお伺いしたいと思うんです。そこら辺のところも含めて区の見解を伺いたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"在宅介護支援センターとヘルパーステーションは基本的にすべて併設をして良質なサービスを継続的に提供しようということで進めてきておりますが。","id":"exchange-021"},{"speaker":"宮崎副委員長","kind":"確認","question":"それをちょっと確認しておきたいのと、それならちょっと伺いたいのですが、そこのところをちょっと伺っておきたいと思います。そういうところをどういうふうに判断されたのか伺いたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"２４時間のホームヘルプの問題ですとか、一定程度、他の事業者にないような部分もあったかというふうに考えております。中延についてそういう経過があって選定をして、これまでもサービスについては適切に提供してきているというふうに考えているところです。","id":"exchange-022"},{"speaker":"宮崎副委員長","kind":"質問","question":"私は当時、コムスンをめぐる事態というのは、面接されたという方がいるわけですから、当時はそういう問題をどういうふうに判断したのかというふうに聞いています。","respondent":"木下福祉高齢事業部長","answer":"保険あって介護なし、サービスなしというようなことをよく言われましたけれども、そういうことについて適切に対応できるようにするためには。","id":"exchange-023"},{"speaker":"宮崎副委員長","kind":"質問","question":"そういうところの管理というか、そういう問題というのをどういうふうにされていくのか、そこのところはどうなんでしょうか。そこのところはどうか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"いずれにいたしましても、そういう法令遵守の部分については、今後さらに適切に体制をとっていく必要があるということは考えております。","id":"exchange-024"},{"speaker":"宮崎副委員長","kind":"確認","question":"ちょっと確認しますけれども、指定管理者等のところも、労働条件がどうなっているかというのは、それはしっかり区のほうも把握している。そこのところをちょっと確認したいと思います。","respondent":"蓼沼高齢福祉課長","answer":"ですから、労働条件といいますか、要するに、運営基準、人員の基準、これについてはもちろん区としてきちんと把握しているです。","id":"exchange-025"},{"speaker":"宮崎副委員長","kind":"意見","question":"そうなると、一体そこの指定管理者、非常に危うい橋を渡っていくということになりますよということを言っているんですね。そこのところは把握するのかどうなのかとの意見を述べました。","respondent":"蓼沼高齢福祉課長","answer":"虚偽の申告です。そういうことで言えば、私どもも指定管理者の施設等についてはきちんと基準に適合しているかどうかはもちろん把握をしているというものです。","id":"exchange-026"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"私が言っているのは、そういう配置基準に合っているかどうかだけでは不十分だというふうに言っているんです。私はぜひそういう目も持っていただきたいということを要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"さまざまな資料を求めたんですが、それでこの不正の問題ですから、不正をどうチェックするかということの問題ですから。私はそういうところもしっかりと議会が求めたときには出していただきたいし、今、委託先の更に下請けがああいう事故を起こした。","respondent":"蓼沼高齢福祉課長","answer":"区では企画のほうが中心になって指定管理者の評価のあり方というものを平成１８年度検討してまいりまして、その評価についての手法といいますか。それから、まず情報公開につきましては、私どもは公開条例に基づいてきちんと対応しているというふうに考えております。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、そこら辺のところも指定管理者の先の委託先の労働条件や安全性、そこら辺のところまでしっかりと区のほうで把握していただいて、万が一にも文京区のような事態にならないようなチェックの仕組みをしっかりとつくっていただいてチェックをしていただきたいということでお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"３歳から１２歳までの幼児もしくは児童とその保護者ということですけれども、平日は就学前までの子どもたちが対象になるということなのでしょうか。そこら辺のところを詳しいところをお願いします。","respondent":"高橋障害者福祉課長","answer":"１点目の職員体制ですが、定員２０名に対して４人の常勤の対応です。これは自立支援法に基づきまして、１０名に対して２名ですので、常勤の職員で対応しております。","id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ごの４人の常勤の職員の方の職種をちょっと教えていただきたいのと、それから、この対象になる子どもというのは、区で把握をしている人数というのはどれぐらいいらっしゃるのかについても教えてほしいと求めました。","respondent":"高橋障害者福祉課長","answer":"職員の職種ですが、社会福祉士が１名、心理職が２名、保育士が１名の計４名です。６月２１日以降、広報に出したところ、２名の申し込みがあったという状況です。","id":"exchange-031"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"宮崎副委員長","kind":"質問・要望","question":"私どもの会派のほうは、期日までに要望を出させていただいています。これは所管の委員会でやるべきだというふうな話で、これはぜひそういう経過も踏まえて、ぜひそれも入れていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"宮崎副委員長","kind":"確認","question":"やっぱりそれはしっかり所管事務調査として取り上げていかなければ、各派協議会の確認も何だったんだということにもなってしまうと思うんですよね。ですから、ぜひにということをお話ししているわけで、頭からだめだというふうなことではちょっと納得ができないということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"宮崎副委員長","kind":"提案","question":"各派協議会で少子化対策の特別委員会をというふうに提案したのは、そういうことで提案したんですよね。ですから、そういう議論を踏まえていただければ、ここはやっぱり厚生委員会でということになるのだと思うんですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"須藤委員","kind":"提案","question":"正副で今、ああだこうだやられたのでは、我々委員としては出した意味がないと思うんです。あらかじめ正副でちゃんと出されたものを委員長提案という形で出してこないと、その辺連携をとって委員会運営をやっていただきたいということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"議会運営委員会のほうの特別委員会をどうするかという議論の中では出されたんですけれども、結局はこの厚生委員会の中ではできなかったんですよね。後期高齢者についても、これは本当に来年の４月から新しく始まる制度ですから、その点も含めてご検討いただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"本間委員","kind":"質問・要望","question":"もっと自信を持ってやっていただきたいと思うんですけれども、確かにいろいろな意見を持っておりますし、たくさんの部分がいっぱい出てくる。さまざまな意見を吸収し、いろいろな情報を集めた中での今年１年の方向性だと思いますので、それを支持していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"私は、この委員会運営のあり方として、やっぱり正副でしっかりと議論してこの場に提案をしていただきたいというふうに思うんです。そういうことで、ぜひ正副で改めて今回の出された意見も踏まえて、２人で相談していただいて、提案をしていただくということでいいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"堺委員","kind":"提案","question":"申し送り確認事項、それで委員長の権限があるわけですから、最終的には委員長のご判断で決められるのが委員会の運営ですから。３点目は、こういう形で一定の結論を出されたですから、我々は賛成をいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"}]},{"id":"topic-03","title":"その他を先に議題に供します。 （１）所管質問","agenda":"その他を先に議題に供します。 （１）所管質問","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"オアシスルームに関して、実施箇所数が減っているという、そしてまた児童センターのほうにオアシスルームが設置をされているということで、現状と今年度どのように変わっていくのか、今後の考え方も含めて教えてほしいと求めました。","respondent":"小林保育課長","answer":"今年度の実施園は、先日の当委員会の事務事業概要２１ページでご説明させていただきましたが、８カ所です。この実施園の一部変更につきましては、この６月に変更する旨の周知、円滑にそれぞれの実施箇所で実施ができているものと考えております。","id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１０園から２園オアシスルームを取りやめたその理由と、中身についてもお聞かせいただきたいのと、そこら辺の現状についてもお聞かせほしいと求めました。","respondent":"小林保育課長","answer":"その実施なんですが、本来あります就労支援としての保育園の役割はもちろんその重要性を維持しておりますので、在宅子育て支援の事業の柱として。","id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"東中延、この４園が閉鎖をして、そのかわりに保育園としては東五反田と荏原保育園で新たにすることになったということでいいんでしょうか。今後、どういう形で具体的に児童センターのほうで場所とかも、人員的にもどうなっていくのかということもあわせて説明を求めました。","respondent":"小林保育課長","answer":"現在は３階の児童センターの部分、そちらの１室をオアシスルームの拠点としながら、東五反田保育園のほうでオアシス業務を対応しています。その辺の対応の仕方は、そして区の職員も含めた中で適切に対応していくということで、今後検討を重ねてまいりたいと考えています。","id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"北品川、五反田、中延、東中延の今までしていたところが閉鎖をされたということだと思うんですけれども、ここの閉鎖された理由についても教えていただきたいのですが。","respondent":"小林保育課長","answer":"あくまでも需要想定に的確に対応していくということと、そちらのほうへ最適化していく、シフトしていくという考え方です。新たな展開を来年度考えてまいりたいと考えていますが、地域交流ルームで半径１キロ圏内の需要については対応できているように印象を持っております。","id":"exchange-043"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"このオアシスルームは在宅で子育てされている方にとっては大変人気ある事業だということで聞いていますので、本当に子どもたちにとっても、さらにお母さんたちにとってもよりよい事業としてこれからも充実するということでご検討ほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"中度の要介護３まで拡大の方向で準備をしているということで、それから周知についてどうしていくのかということについて、現在実施している要介護４と５の方への周知をどうしているのかということも含めて教えてほしいと求めました。","respondent":"蓼沼高齢福祉課長","answer":"周知の方法については、広報等を活用してどのようにＰＲしていくかは今後検討していきたいと思います。今後ともそういうような方法で周知に引き続き努めていきたいというふうに考えてあります。","id":"exchange-045"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"５のところの広報というのを確かめたら、この制度そのものがどういう制度かという、その１行だけだと。合わせて３,５００人ぐらいですから、３,５００人に直接お知らせする通知を出していただきたいというふうに思うんですが、いかがか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"ただ、そのうちの課税されている方ということで、最大１,０００人ぐらいの方が単純に言えば対象となるのではないかというふうに思います。税務課とも相談しながら検討させていただきたいと思いますけれども、本来、そのご指摘については困難かと思います。","id":"exchange-046"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"制度そのものについてのお知らせですから、本人が申請しないのに適用してしまうということではないですから、ぜひそれは要介護４と５も含めて。今、こういうことから考えると、ぜひ約３,５００人の方に直接制度のお知らせをしていただくということでご検討をお願いして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"リバースモーゲージの制度が７月から実施されるというようなところをちょっと聞いたんですけれども、どうなっているかということを教えていただきたいのと、お願いします。","respondent":"志村生活福祉課長","answer":"国のほうからは早く実施しろと、実際の資金の貸し出しは、社会福祉協議会が窓口になります。今その絞り込みと、それから新たに開始する方についての誘導の仕方というんですか、決まった段階でご案内しようというふうには考えております。","id":"exchange-048"}]},{"id":"topic-04","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"須藤委員","kind":"意見","question":"我々がこうだこうだというのはなかなか言いにくいところなので、それらを踏まえながら正副で決めていただければいいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"},{"speaker":"堺委員","kind":"意見","question":"平成１２年度から平成１８年度までの厚生委員会の行政視察日程等一覧表をご提示いただいてありがとうございました。その辺のところも加味していただきながら、最終的には正副に一任したいというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"提案するということはないんですけれども、本当に２３区内の新型特別養護老人ホームですとか、ぜひそういうものもご検討いただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"本間委員","kind":"意見","question":"日程の関係は、既に明らかになっておりますように、１０月の下旬の部分と相手の都合というようなことがありますので、その辺でよかろうかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/928192?Template=document&Id=3176#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":45465,"voices":136}},{"id":"h19-20070626-8","meetingId":"h19-cm06","date":"2007年6月26日","dateIso":"2007-06-26","committee":"建設委員会","time":"午前１０時０３分～午後０時２９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を62件整理しています。","topics":[{"id":"topic-01","title":"の品川南ふ頭公園整備工事（その２）","agenda":"の品川南ふ頭公園整備工事（その２）","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"昨日、現場でもお伺いしたんですけれども、駐輪場の計画が未定というお話だったと思うんですが、どの場所に何台ぐらいで考えていらっしゃるのか、駐車場の問題を含めて、説明を求めました。","respondent":"松代管理工事課長","answer":"そこの部分に駐輪場を３０台ほど置けるようなスペースを今から考えていこうと考えています。駐車場は１７台計画しておりまして、有料という形でご利用いただくように考えてあります。","id":"exchange-001"},{"speaker":"須貝委員","kind":"意見","question":"やはりほかの競技もできるようなラインもあらかじめ引いておかないと、また設置しておかないと使えないと思うんですね、現実的に。その辺に対する対応は一体どのように考えているのか、説明を求めました。","respondent":"松代管理工事課長","answer":"ここでどういったものができるのか検討していきますが、今の主立った貸し出しとしては、そのようなことが考えられております。そういったことも重ね合わせて利用いただけば、そんなふうに考えてあります。","id":"exchange-002"},{"speaker":"須貝委員","kind":"質問・要望","question":"人工芝の上部のほうにあるわけですから、やはりスポーツ場としては、私は不適格だと思うんですね。特に新幹線側に関しては十分な高さを維持するように設置するべきだと思うんですが、その辺、もしちょっとお考えがありましたら。","respondent":"松代管理工事課長","answer":"こちらの道路側ですか、そういったところへのボールの飛び出し等への配慮ということで、いろいろと検討しました。試合等ができるような、ボールが外に出ないような形で最大限配慮したものがこの形だということで、我々は計画したところです。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問・要望","question":"要望なんですが、今データからのお話をお伺いいたしましたら、ここの高さまで飛び越える人というのは私は本当にないと思うんですね。それだけちょっと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"端っこに置くのかわかりませんけれども、そういうのはどういう形になるのか、またフットサルだったら２面ぐらいとれるんですか。足とか手とか顔を洗う水場の整備ですとか、そういうところはどういうふうになっているのか、現状を教えていただけますか。","respondent":"松代管理工事課長","answer":"それとコインシャワーを設置したいと考えております。足洗い場、手洗い等をその周辺に設けたいと考えているところです。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ使いやすい状態にしていただきたいと思うんですけれども、利用料については、もうかたまっているのか。半日ないし１日だと幾らぐらいになるのか、そういう辺の制度はぜひ必要なのかなと思うんですけれども、料金体系について教えていただけますか。","respondent":"松代管理工事課長","answer":"これは２時間単位です。区主催だとか、そういったときには料金等は減免もしくは主催者側が用意する、そういった形で運営されているというように承知しております。","id":"exchange-006"},{"speaker":"中塚委員","kind":"意見","question":"以前、青空広場野球場が無料で使えて、ここは有料になるということで、やはり僕は無料で行うべきではないかという意見だけ申し上げて終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"三上委員","kind":"質問・要望","question":"この野球場ができたことはいいと思うんです。事故という問題が過去にあったという現状とは変わっていないわけですから、利用者にとって交通が問題だという声が出ないように、きちっと今から。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"井上委員","kind":"質問","question":"今のお話なんかを含めると、この管理体制というのはどうなっているんか尋ねました。","respondent":"松代管理工事課長","answer":"管理は、基本的に民間委託で行う予定です。基本的には天王洲野球場と同じような管理体制で臨みたいと考えています。","id":"exchange-009"}]},{"id":"topic-02","title":"の荏原町駅不適合処分取り消し請求事件の概要","agenda":"の荏原町駅不適合処分取り消し請求事件の概要","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"人工地盤というんですか、それがないのに建てちゃったら、けしからん話だと東急に思います。こういう合意自体が、もうだめだと、そういうふうに言いがかりというか、ちょっとそこをもう少し教えてくれますか。","respondent":"岩田まちづくり事業部長","answer":"東急は安心安全ステーションや公衆便所の設置については、これは今回の東急側の建築計画とは切り離して対応したい。したがって、協力することは残念ながらできない。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問","question":"この６番目の、東急の請求を棄却した理由の２番目に、今回みたいな建物がほかにあるんですか。ＪＲなのか、わからないんですけれども、過去にはあるんか尋ねました。","respondent":"齋藤住宅課長","answer":"昔は陸橋として使っていたようですけれども、その後、転貸しして使っている。もともと東急のもので、いわゆる今回のようなオーバーハングのような形での建設は、東急はそこだと言いましたが、ございませんでした。","id":"exchange-011"},{"speaker":"阿部委員","kind":"質問","question":"今後なんですけれども、いったん建築審査会で棄却をして、そのあと、東急が主体になることなので、区に伺うのはおかしいかもしれないんですけれども、これは東急としては、訴訟ないし請求の準備というのはなさっているような状況なんか尋ねました。","respondent":"齋藤住宅課長","answer":"この段になって、訴訟を起こすかどうかはわかりません。ただ６カ月以内に訴訟を起こさなければいけない、私がいままで応対した考え方で言うと、工事を進めたいという感触は私どもは持っております。","id":"exchange-012"},{"speaker":"阿部委員","kind":"質問","question":"では、とりあえず区としては、今後の東急の出方を待つということになるんでしょうか。それともこの間に区として何かやることはあるんか尋ねました。","respondent":"齋藤住宅課長、松代管理工事課長","answer":"訴訟だけに関して言いますと、私どもは本件については受け身です。ただ、公衆便所関連につきましては、実施の予定で考えております。 平成１９年度再計上となりましたが、平成１９年度中に建築できるように東急のほうにはぜひそのような形で進めさせてほしい、進めたいということで臨んでいきたいというふうに思っております。","id":"exchange-013"},{"speaker":"阿部委員","kind":"質問・要望","question":"区としてはどういう別の方法で、この安心安全ステーションおよび公衆便所について、東急に要望していくのか。それとも特に持ち駒はないんか尋ねました。","respondent":"岩田まちづくり事業部長","answer":"当初から私ども東急に対して、東急は表向きは切り離して対応しますよと、こうおっしゃっておりますけれども、実態は一体なんですね。これで、今後どう出るかによって、また次のやり方を考える、こういうことです。","id":"exchange-014"},{"speaker":"阿部委員","kind":"確認","question":"確認なんですけれども、公衆便所も安心安全ステーションも動かないと決まったわけではない、というふうに考えてよろしいんでしょうか。ちょっとその辺を伺います。","respondent":"岩田まちづくり事業部長","answer":"公衆便所と安心安全ステーションを駆け引きとしてもし考えておられるのであれば、それは私どもはきちっと襟を正して、それは東急に対応しております。","id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今のお話の中で公衆便所と安心安全ステーションを一体としてそれはお願いをしていくのかどうかというお話の部分と、東急側は、今のお話はね。ここら辺のところはやはり地域の要望を聞いて、そこら辺の考えというのは、区はどう思いますか。","respondent":"松代管理工事課長","answer":"平成１８年度の計画を進めるに当たって、ここにありますような３ページの図面のような形のものをつくって計画を進めているところです。今後、こういう一体的な整備として進めていきたいというふうに考えております。","id":"exchange-016"},{"speaker":"三上委員","kind":"提案","question":"住宅が非常に不足している時代に、山手線、線路上に住宅を建設してもいいのではないかという話を提案したことがあります。そこらあたりの判断については、品川区としては、どういうふうに受け止めていらっしゃいますかとの意見を述べました。","respondent":"齋藤住宅課長","answer":"難しいんですが、鉄道の上に建物が建って、仮に地震があってつぶれてしまうと、交通インフラが全部つぶれてしまう。こういったこともございまして、なかなか国のほうとしても、どこまでいいかというのは難しいです。","id":"exchange-017"},{"speaker":"三上委員","kind":"質問","question":"どう法律等を解釈するかによっての話でしかないとなるので、これは住民にとっては不幸な話であるとしか言いようがない部分があるわけです。それから区が建てようとしている安心安全ステーションをひっくるめた、そちら側の中での一体的な建物というのは考える余地というのはないんか尋ねました。","respondent":"片田建築課長","answer":"法そのものの考え方は、それに沿った形での考え方になってきますから、長期戦になることが明らかになるだろうなということで認識があります。だめだぞということではなくて、まるでできないという問題ではないということで、計画の工夫が当然必要なものかなと考えております。","id":"exchange-018"},{"speaker":"三上委員","kind":"意見","question":"東京都が１万m2以上の要綱をつくったということになると、１万m2行かない部分については、それの判断はどういうふうになっていますかとの意見を述べました。","respondent":"片田建築課長","answer":"基本的には東京都の要綱等に準ずるということで考える、当然検討のしようがある、このように考えてあります。国土交通省あるいは東京都のほうに確認をとったところ、現時点では東京都のみがこのような基準を設けているというのがわかりました。","id":"exchange-019"},{"speaker":"三上委員","kind":"質問・要望","question":"状況としては、お互いの利という部分がやはりあるわけですから、そこらあたりがどういうふうに調整されていくか、大幅な考え方の変更というものがしていただけるのであれば、それはありがたいと思いますので、それは品川区のほうも考えていただいて対応していただきたいなと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"須貝委員","kind":"質問・要望","question":"トップ会談でもいいですから、私はもっと責任の重い方たちが交渉して、お話し合いを持っていただくということを考えていただければいいなと思います。それだけちょっと要望します。","respondent":"岩田まちづくり事業部長","answer":"東急側は、この件に関しましては顧問弁護士が私どもとの対応をしております。逆に我々が被告になれば、全国の自治体が我々の後ろで応援してくれるということになる可能性が高いと考えています。","id":"exchange-021"}]},{"id":"topic-03","title":"の原動機付自転車の売却処分への移行","agenda":"の原動機付自転車の売却処分への移行","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"移行なんだから、逆に言えば、いままでもやろうと思えばいつでもやれたのか。条例改正がないということは、移行するということを決断したことは非常にいいことなんだけれども、そこら辺の法的な関係を説明を求めました。","respondent":"松嶋交通安全担当課長","answer":"これまで条例には、処分については、売却もしくは再生利用ということが載っておりまして、これまでもやろうと思えばできたものです。したがって改正は必要ないです。","id":"exchange-022"},{"speaker":"阿部委員","kind":"質問・要望","question":"これまでの処分についてちょっと教えていただきたいんですが、これはどういう仕組みになっていたのか教えてほしいと求めました。これは何社ぐらい入札があったのかということも説明を求めました。","respondent":"松嶋交通安全担当課長","answer":"この６番の部分はちょっと説明が文字足らずです。それと、入札の会社につきましては全部で６社ございました。","id":"exchange-023"},{"speaker":"阿部委員","kind":"質問","question":"それで、この廃棄処分というのも、これはどこかの業者に委託してやっていたということなんでしょうか。委託業者、これは区内の業者か尋ねました。","respondent":"松嶋交通安全担当課長","answer":"それと、委託業者につきましては区内ではございません。立川市のほうに所在する有限会社です。","id":"exchange-024"},{"speaker":"阿部委員","kind":"確認","question":"確認なんですけれども、そうすると、その協力会から１台当たり１,０００円の寄付を受け取っているということでよろしいんでしょうか。何かちょっと不思議な感じがするんですけれども。","respondent":"松嶋交通安全担当課長","answer":"いわゆる捨て車ですね。あなたのところで処分しなさいではなくて、それに対しては、寄付は１,０００円を出しますよです。","id":"exchange-025"},{"speaker":"井上委員","kind":"確認","question":"さっきの石田委員の質問のところなんですけれども、いままでもできたという、その方針を変えた理由というところの確認をさせてください。","respondent":"松嶋交通安全担当課長","answer":"これまでも実はこの条例に載っておりますとおり、売却の検討は区としてはしてきております。自動二輪車も含めていろいろ検討して、そういったことを慎重に検討した結果、こうなっています。","id":"exchange-026"},{"speaker":"井上委員","kind":"質問","question":"そうすると、この売却のほうは原付バイクに限るんだと思うんですけれども、二輪車のほうは、台数としては、割合とか、たぶん二輪車のほうが多いのかなと思うんですけれども、その辺の状況というのはどうなっているのか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"割合的には原付バイクが主です。原付バイクにつきましては年間６３３台、原付バイク以外につきましては９７台、これが撤去台数です。","id":"exchange-027"},{"speaker":"井上委員","kind":"確認","question":"すると、このことについてではないんですけれども、その６３３台というのは、警察との確認をした中で、ただ単に自転車のように捨てちゃった、というと変ですけれども、盗難でもないし、盗難だったら、それは処分できないわけですから、そうすると、そういう、ただ単に放置されたものなんか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"撤去した台数は６３３台で、その中で返還をしたのが３５０台あります。それで、そのほかのものが、いままでは廃棄処分という部分です。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"いわゆる壊れかかっているというか、壊れているものも１台あたり６,５３０円、その辺の考え方をちょっと教えていただきたいのが１点。それと、費用対効果のところで話がありましたけれども、このお金はどこに入るんか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"逆に言えば、いいバイクであっても６,５３０円であれば、例えば後ろのタイヤがなくても６,５３０円、そういう考えです。それと、費用対効果ですけれども、これは一般財源のほうへの歳入になります。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問","question":"この委託業者ですけれども、これは年間契約なんですか。それとも一定契約したら、期間が過ぎたらまた契約が変わるというか、入札をし直すとか、そこを説明を求めました。","respondent":"松嶋交通安全担当課長","answer":"年間です。１年しかやっておりません。","id":"exchange-030"},{"speaker":"阿部委員","kind":"質問","question":"全体的な流れを教えてください。だいたい撤去してからどのぐらいの期間のときにどういうふうになって、それぞれの行き先が最終的に決まるのかという流れを説明を求めました。","respondent":"松嶋交通安全担当課長","answer":"ただ、バイクにつきましては慎重を期しておりまして、これは自転車法によって６カ月間で所有権の帰属が必要となりますので、それまで待っております。それで６カ月間たった後に改めて売却ということで考えております。","id":"exchange-031"},{"speaker":"阿部委員","kind":"質問","question":"この概要のところで「再生利用のほか、効率的な予算執行の観点から、売却処分に移行」とあったものですから、再生もあり、売却もあり、と読んだんですけれども、そうではないんか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"それと、部品を取って違うところに取り付けて、新たなバイクをつくり出すとか、そういったものもあります。いずれにしても再生利用、売却は、今回のバイクにつきましては、すべて売却にして再生利用にするというものです。","id":"exchange-032"},{"speaker":"阿部委員","kind":"質問","question":"とすると再生利用かと思って、売却して、売却した先の人がどうしようか勝手よというあれなんですか。そういうことならそれでいいのですが。","respondent":"松嶋交通安全担当課長","answer":"すみません、これは文章の問題であって、この「ほか」というのは、効率的な予算執行の観点、この二つを含めて売却処分に移行ということでご理解をいただきたいと思います。","id":"exchange-033"},{"speaker":"三上委員","kind":"確認","question":"どう事業を展開してバイク置き場を拡大するかということの、そこらあたりの考え方というのがあったら教えてもらいたいんですが。ということに対してどう取り組むかということを、法律はちょっと違うから、そこのところだけ確認させてもらいたい。","respondent":"松嶋交通安全担当課長","answer":"ほかの業者に対してもできるだけそういった施設の中でのバイクの利用箇所、スペースを確保してもらいたい旨はいろいろな面でお願いをしています。","id":"exchange-034"},{"speaker":"井上委員","kind":"質問","question":"すべてに通知が１００％行くことができているのか、それとも所有者不明という状況にあるのか、その２点だけちょっと説明を求めました。","respondent":"松嶋交通安全担当課長","answer":"例えばナンバーのついていないものは所有者照会はできませんので、これはたどり着くことができません。それはそういうものを見ながらとりに来てもらう必要がありますし、そういった面では、そういう返却に当たっての対応はしていると考えております。","id":"exchange-035"},{"speaker":"井上委員","kind":"質問・要望","question":"よく撤去されたときに、本当になくなった瞬間、どこに連絡していいかというのがわからないという人もよくあるんですね。どういったルートで、「あ、その辺はきちっと親切にわかるような表示とか方法を取り組んでいただきたいなというふうに思いますので要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"区の役割分担だけ確認させてください。これは要望だけ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]},{"id":"topic-04","title":"の平成１９年度区民・都・区合同立会川環境美化運動の実施","agenda":"の平成１９年度区民・都・区合同立会川環境美化運動の実施","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これは土日にやらないという理由が何かあるんですか。行政側の理由なのか、それを教えていただきたいのが一つと、町会のところはなんでポイントが小さい字なのかなとちょっと思ったんだけれども。","respondent":"家壽田下水道河川課長、岩田まちづくり事業部長","answer":"土日にしない理由ですけれども、これは地元の町会の方だけではなくて、都とそれから区の職員も大勢参加いたします。その辺のことも配慮いたしまして、本年は土曜日を避けて実施するです。徐々に地域の方々の理解が得られまして、では手伝いましょうというお声をいただいて、徐々に広がりを見せて今のようになりました。","id":"exchange-038"},{"speaker":"中塚委員","kind":"質問","question":"今回のこの環境美化運動ということですけれども、そもそもこの立会川の親水護岸にするという話は、今はどういうふうな状態になっているのかという経過を教えてほしいなと思います。","respondent":"家壽田下水道河川課長","answer":"いろいろなサイドで検討した経緯がございまして、その中で、東京都のほうで環境護岸をつくるということは伺っております。今、あの幹線を待ってそういった防潮護岸ですとか環境護岸にするということになっておりますので、今はその完成を待っているです。","id":"exchange-039"},{"speaker":"中塚委員","kind":"質問","question":"勝島運河ですか、あそこの水質の問題とかもありますので、親水護岸の計画はしっかり進めていく必要があるなと思うんですよね。仮にこれが完成したとして、勝島運河内はどれぐらいきれいになる、そういう予測というか、データみたいなものはあるんか尋ねました。","respondent":"家壽田下水道河川課長","answer":"現在の雨ですね、今一番降雨時にどうかといいますと、汚水が雨と一緒に流れ出す状況というのが立会川の流れです。今の立会川のところから勝島運河に出なくなりますので、ここの部分が汚濁物が出なくなるということで、かなりきれいになると期待しております。","id":"exchange-040"},{"speaker":"井上委員","kind":"質問","question":"高濃度酸素溶解水による浄化実験についてちょっと説明していただいていいか尋ねました。","respondent":"家壽田下水道河川課長","answer":"この状況を改善するためにはいろいろなことが考えられるのですが、これで河川の本来持つ浄化能力を引き出してやるという実験です。これについては、先週から試運転をしておりまして、先週の土曜日から２週の連続運転に既に入っております。","id":"exchange-041"}]},{"id":"topic-05","title":"の東急目黒線上部利用計画","agenda":"の東急目黒線上部利用計画","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"商業スペースなのか、そうでないのか、まず現状わかるところを教えてほしいと求めました。品川区のほうで、この武蔵小山駅の入居者関連のところを教えていただきたい。","respondent":"浜脇街路事業担当課長","answer":"３階建てと言ってございまして、実は自分たちも検討している案はあるんですが、そういったものを今現在検討している中で。ですから、それは地元の方々があったらいいなというような話があるのかもしれませんが、それはちょっと私たちのほうでは聞いてございません。","id":"exchange-042"},{"speaker":"中塚委員","kind":"質問","question":"今３階建てということで、東急のほうは案があるというお話ですけれども、その東急が持っている案自体は、品川区は見たことはあるんか尋ねました。","respondent":"浜脇街路事業担当課長","answer":"それを詰めている途中といいますか、それを今発表するわけにはいかないということで、今回はこの程度の発言になってあります。","id":"exchange-043"},{"speaker":"中塚委員","kind":"質問・要望","question":"現時点の案の状態になっているものをぜひ見せていただきたいと思うんですけれども。","respondent":"浜脇街路事業担当課長","answer":"今現在、ある程度一定の解決をしたところで私どもはお知らせしたほうがいいのではないかと考えていますので、案の取り扱いについては慎重にしたい。計画案については、東急のほうと一定の結論が出たところで出すべきものと考えています。","id":"exchange-044"},{"speaker":"井上委員","kind":"質問","question":"この３駅の緑道部分について、各進捗状況の差があるかと思いますけれども、それぞれ今どういう状況になっているのかということを教えていただけますか。","respondent":"松代管理工事課長","answer":"次が第３緑道ということで、三つの緑道ということで計画を進めておりまして、平成１９年度はこの第１緑道と第２緑道の実施設計を進めてまいります。","id":"exchange-045"},{"speaker":"井上委員","kind":"質問","question":"平成１９年度実施計画の部分でお伺いしたいんですが、実施計画の今後のスケジュール、どういった時期に住民の方たちに説明をするのか、そういうことをされていくのか、それとも、完成までの近々のスケジュールというのはどうなっているんか尋ねました。","respondent":"松代管理工事課長","answer":"１０月ぐらいに工事費等の予算編成に向けて、地元説明会等も開き、計画を立てまして進めたい。今のところそういうふうに考えているところです。","id":"exchange-046"},{"speaker":"須貝委員","kind":"質問・要望","question":"ぜひ東急に、より駐輪場の確保をできるだけしてくださるように、ご協力をよろしくお願いいたします。それだけ要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"三上委員","kind":"質問","question":"不動前駅の駐輪場の拡大について、これは要するに宿題というか、課題になっているんだけれども、現状でこれはどうなっているんでしょうか。そこらあたり、どうなんか尋ねました。","respondent":"浜脇街路事業担当課長","answer":"現状８５％ぐらいの利用率だということで、現状ではそれで足りているというふうに認識しておりますので、そういうままです。Ｎ－１の西小山駅の補助３０号線の隣ですけれども、駅から補助３０号線から真っ直ぐに入ってくるような貫通通路をつくりたいと考えているところです。","id":"exchange-048"},{"speaker":"三上委員","kind":"意見","question":"暫定的にだってバイク置き場という形で、チェーンゲート式でも何でも設置するぐらいのことはできるはずなんだけれども、なぜやらないのか。そこらあたり、本当に交渉していただいているのかどうか、私はわからないんですよねとの意見を述べました。","respondent":"浜脇街路事業担当課長","answer":"バイクより自転車の通勤通学のために利用したいというのが会社としての方針としてあるものですから、ちょっと考え方がかたくなになっていて、そういった形で改めて申し入れをして調整をしてもらいます。","id":"exchange-049"},{"speaker":"三上委員","kind":"質問","question":"言葉尻をとらえるわけではないけれども、たまになんて言われたら、では、１カ月の間に何回見にいっているんですか。きちっとそれならそれで、現状把握を毎日やった上で、そうでなければ、ここは違法駐車、駐輪になっているわけだから撤去すればいいじゃないか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"バイクの調査を毎年２回やっておりまして、放置自転車、バイクが多い駅の中の一つとして挙がっております。これまでも東急のほうには駐輪場設置の申し入れをやっているんですけれども、今後、駐輪場の整備のほうの申し入れをしていきたいと思います。","id":"exchange-050"}]},{"id":"topic-06","title":"の区営住宅（あき家）入居予定者登録募集","agenda":"の区営住宅（あき家）入居予定者登録募集","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"年に１回やっているものですけれども、まず昨年、何人の方が募集、この入居予定者の申し込みを行い、何人がその予定者になって、何人が入れたのか、昨年の実績を説明を求めました。","respondent":"齋藤住宅課長","answer":"結果として入れたのは２４人。各住宅ごとに１０戸ずつ登録をいたしますので、１６７人の方が登録をされてございました。","id":"exchange-051"},{"speaker":"中塚委員","kind":"質問","question":"さらに年齢制限が５０歳から６０歳に上がりましたよね。そのような意味でもこの実態ですから、私は急いで区営住宅を多くつくるべきだと意見だけ申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"井上委員","kind":"提案","question":"検討が必要じゃないかという提案があったんですけれども、そういう検討も必要じゃないかという提案がありましたけれども、そういう考えはされているのか尋ねました。","respondent":"齋藤住宅課長","answer":"何が公平か、どういうところでバランスをとっていったらいいかということがございまして、やはり住宅ごとに応募状況を見ながら応募をお願いしたい。どこでもいいので優先をということは、なかなかそういうのは難しい、こういう話をしています。","id":"exchange-053"},{"speaker":"井上委員","kind":"提案","question":"同じ１０戸の住宅に登録しているよりも、全体で困窮者の人たちのための仕組みも必要ではないかという提案が出て、どういう検討をされたのかという質問ですとの意見を述べました。","respondent":"齋藤住宅課長","answer":"区としては全体のバランスから考えまして、検討していますが、行う考えはございません。住宅ごとに選ぶ方との枠をどういったバランスで選ぶかというのはなかなか難しゅうございまして、今の方法を見直すという考えは持っておりません。","id":"exchange-054"}]},{"id":"topic-07","title":"の区営住宅・区民住宅からの暴力団員の排除","agenda":"の区営住宅・区民住宅からの暴力団員の排除","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それだから、該当したら明け渡しを求めるとなっていることですよね。求めるということは、区の職員の方は交渉をしなくてはならないということなんだよね。","respondent":"齋藤住宅課長","answer":"私たち区の職員ではなかなか、警察の方と連携をとりながら、私ども体制を組んでいく。広島市で２０代の、本当に開き直られたときには大変不安が広がりますので、区としても困難を極めるだろうというふうに考えてあります。","id":"exchange-055"},{"speaker":"中塚委員","kind":"質問・要望","question":"その辺、どういうふうな仕組みを考えているのか、ちょっと教えていただきたいのが一つ。先ほどのお話の中で、警察のほうでデータベースがあって問い合わせたら教えてくれるんだというお話がありましたけれども、教えていただけますか。","respondent":"齋藤住宅課長","answer":"入居審査はいたしますが、ご本人が来られませんと、本当のところはなかなか難しい。警察が見る暴力団関係者と我々の認識だとたぶんずれる場合がありまして、具体的に言うと、籍を外した奥さんが住宅に住んでいる。","id":"exchange-056"},{"speaker":"中塚委員","kind":"質問・要望","question":"もう一つ教えてもらいたいのは、そのところに住んでいなくても近隣の方もいらっしゃるでしょうから、そこら辺についてちょっと教えていただきたい。そういうのは区だけが判断できるのかどうかわからないけれども、それは判断をどういうふうにしていくのか、もうちょっと教えていただけますか。","respondent":"齋藤住宅課長","answer":"正確な判断はできないというふうに考えてあります。積極的に果敢に対応して、それを教えてください、それはやらないです。","id":"exchange-057"},{"speaker":"中塚委員","kind":"確認","question":"２点目の耐震化促進事業についてという部分、もう一回教えてください。今年、地域防災計画を見直すという時期にあたっておりますので、改めて委員長の仕切りについて確認します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私もそこに手を入れるべきだと思っているんだけれども、そういうところがあれば、これをやはり取り込んでいただきたいなと思います。そういうことも含めて、考えたらどうかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"中塚委員","kind":"質問","question":"それもまた問題もあちこちで起きているみたいだけれども、どういう街並みが望んでいる姿なのか、そういうふうに意見をする中で合意点を見出している。そういう話も伺いますので、それぞれの住民が参加するテーマなんかも委員の皆さんもどこに注目しているのか、そういう意見が出し合えていけば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"石田（秀）委員","kind":"意見","question":"よく考えて言いなさいと言ったんです。何でも言ったらいいということではないとの意見を述べました。","respondent":"本多委員長","answer":"最終的には正副委員長はじめ、検討しますが、項目はどうぞ出してください。","id":"exchange-061"},{"speaker":"阿部委員","kind":"意見","question":"いろいろ検討すべきだと思うんですが、あるいはどういうふうな点、機会を設けたような視察ができればなと考えていますとの意見を述べました。","respondent":"本多委員長","answer":"調査項目も出てまいりましたので、調査項目の次に実施について考えていくわけですけれども、参考までに申し上げます。第３回定例会が終了後、１０月２２日に道路大会の予定がありまして、１０月２９日の週でというふうに考えているんですけれども。","id":"exchange-062"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/325823?Template=document&Id=3882#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":43063,"voices":169}},{"id":"h19-20070626-9","meetingId":"h19-cm06","date":"2007年6月26日","dateIso":"2007-06-26","committee":"文教委員会","time":"午前１０時０２分～午後 ０時１０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を53件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"当初と今日の選択の状況というのが、同じ角度で選択されているのか、あるいは変化があるのか。あるのであれば、どういうところなのかというようなことを教えてほしいと求めました。","respondent":"古里学務課長","answer":"今年度は、先ほど申したとおり、小学校が５校、それから中学校が６校、抽選に至るという状態になっております。なお、この動向が今後も続くかどうかということにつきましては、今後の動向をよく見定めてまいりたいと考えております。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"選ぶ人たちが増えているというのは、教育委員会としてはどういうふうに分析しているのかというのを改めて伺いたいと思います。今年度は入れたのかどうか、その辺の状況も教えていただきたいのと、その辺も伺いたいと思います。","respondent":"古里学務課長","answer":"こちらは入学希望が非常に強くあらわれているという傾向が出てきており、６校構想を早く進めるということの必要性を感じているところです。その意味では、教育改革プラン２１の効果ということは十二分にあらわれているかと考えています。","id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"ある先生にたまたまお話を伺う機会があったんですけれども、過去問をずっと取り上げて子どもたちに教えてきたとか、そういう話を聞いたんです。その辺どういうふうに、学校の中の努力というのをどういうふうに分析して見ておられるのか、その結果について伺いたいと思うんですけれども。","respondent":"河野指導課長","answer":"プラン２１に掲げている目標の中には、それぞれの学校ではいろいろ工夫をしながら、基礎学力定着のための取り組みを行っている。その取り組みの内容といたしましては、ただ単に学力テストに向けての練習だけではなくて、基礎学力充実のための方法の一つであると理解しております。","id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"１つの学校で、それから朝８時からの個別指導をするとかいう、私はそういう印象を受けたんです。プラン２１に沿っている方向だからよしというふうに、その辺の見解だけ伺って、終わりたいと思います。","respondent":"河野指導課長","answer":"学力の定着は、単に授業の充実だけでなされるものではありません。学校がさまざまな時間帯を使って、これは基礎学力の定着にとって非常に重要な取り組みであると認識しておりますし、私どもは持っておりません。","id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"改めて、じゃ、これでよしにしておきます。よしというか、一応終わりますけれども、また改めて機会を持って、ご質問させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問・要望","question":"減っているところから分析というのは何かあるのかなというところを教えていただきたいということと、重点支援校の中での変化というんですか。そういう形では分析しないのか、その辺、いかがか尋ねました。","respondent":"古里学務課長","answer":"基本的にはブロック外からの受け入れということはいたしませんので、それ以外の学校で、学校の就学予定者に余裕があった場合です。そうした重点支援校という形で、教育委員会事務局と協力していろいろな検討、その結果があらわれていくと考えています。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"その辺を分析していただきたいなと思うんですが、保育園とかの保護者たちが、どういうふうにその学校を見ているのか。評価に対する分析というのを何か認識されていることがあれば、教えてほしいと求めました。","respondent":"古里学務課長","answer":"自分の求めに合っている学校というところで選択をしているということがアンケートの結果からはよく見えると私どもは認識しています。それから学校を選択する上での資料になる案内パンフ、こうしたものをしっかりつくり込み、情報提供に努めてまいりたいと考えています。","id":"exchange-007"},{"speaker":"市川委員","kind":"質問・要望","question":"今までどうで、これから先どういうふうな見通しになるのかというところが、もし何かありましたら教えていただきたい。高いところと低いところが、区のその辺の施策と何か関係があるのかというところについて聞きたいんですけれども、お願いします。","respondent":"古里学務課長","answer":"これは学校によって２回やるところ、３回やるところありますけれども、あるいは学校の教育目標等について学校側で説明をするという。最終的に２月に入りましては、最終段階として入学説明会を行い、またその中でも学校での説明をしていると聞いております。","id":"exchange-008"},{"speaker":"金野委員","kind":"質問・要望","question":"西本委員からご質問があった、小規模ならではの学校独自の自助努力というんでしょうか、学校運営をされているんでしょうか。それとも、区としてというか、教育委員会として何かアドバイスしながら学校運営をしているのか、そこら辺ちょっと教えてほしいと求めました。","respondent":"河野指導課長","answer":"それから大規模校には大規模校のよさがあるということを前提に、それぞれの学校運営を学校長にゆだねるという形で実施しています。学校としてのいわゆる教育機能という点から考えると、極端な小規模校に限って言えば、現場からそういう指摘の声も実際に出ております。","id":"exchange-009"},{"speaker":"山内委員","kind":"質問","question":"例えばそういう形で、Ａ校とＢ校に分かれていっちゃっているときに、地域地域での交流とかというのはあるんか尋ねました。","respondent":"河野指導課長","answer":"これが教育課程外の活動ならばかなり柔軟性がありますけれども、教育課程に位置づけられた活動ということになると、実際には非常に難しいかと考えます。","id":"exchange-010"},{"speaker":"西本委員","kind":"確認","question":"確認といいますか、先ほど質問するのを忘れたんですけれども、中学校のところで、特別支援のところなんですが、伊藤学園に新設されたんですよね。原が１０人という形になっているんですが、この辺はどういうふうに分析されていて、今後の周知徹底というのはいかがか尋ねました。","respondent":"河野指導課長","answer":"小中一貫教育を進めるに当たって、平成１９年度に伊藤学園の中に特別支援学級を開設したという経緯です。伊藤学園にある特別支援学級についての紹介というか、どこどこに特別支援学級がありますよという形で、周知徹底を図っているところです。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"それから、最後の確認なんですが、日野学園の小学部には新設はしないんでしょうか。一貫という形になると、やはりその辺も一貫的なというところの意味で、新設するのもいいんじゃないかなと思うのですが、いかがか尋ねました。","respondent":"河野指導課長","answer":"第二日野小学校は特別支援学級の設置校ではございませんので、今そのままの形で、中学部のみに特別支援学級があるという形でやっております。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"学校もそうなんですけれども、情報公開も絡んでなんですけれども、どういうふうな学校なのかということをもうちょっと宣伝してほしい。わかりやすく、日々の生活にあるような形でぜひしていただきたいということを要望して、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]},{"id":"topic-02","title":"の「平成１９年度品川区立幼・小・中学校（園）長、副校（園）長異動者名簿について」","agenda":"の「平成１９年度品川区立幼・小・中学校（園）長、副校（園）長異動者名簿について」","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"教えていただきたいと思って言うんですけれども、そのうちの２人が再任用されて、あることなんか尋ねました。","respondent":"河野指導課長","answer":"この再任用の管理職というのは、昨年度新たな制度として設けられたものです。団塊世代の大量退職に対する対応策ということで、今年度についても積極的に進めていただきたいということで、この制度は当分続くと見ております。","id":"exchange-014"},{"speaker":"南委員","kind":"確認","question":"ちょっと確認したかったのは、能力を発揮していただくということは大事だけれども、一定の年齢が来て退職される。私は意外に思ったんですけれども、そういうことって、あって当然なんか尋ねました。","respondent":"河野指導課長、若月教育長","answer":"その後補充ということで新採教員も大量に採用されておるわけですが、管理職も同じような、まさに大量に退職されているという実態があります。従来は再任用、再雇用と２つの制度の中から選択できるような制度になっておりましたけれども… 定年延長ですよ、要するに。そのかわり給料は少し減る。","id":"exchange-015"},{"speaker":"南委員","kind":"確認","question":"ここに「定年退職」と書いてあるので、一度職を、いわゆる公務員を退いて、そして新たな再任用制度で雇用されるって、こういう形ですよね。いろいろな能力をいろいろな分野で発揮していただくということは大事なことですから、その辺が私は全然わからなかったから、確認をしたいんですが。","respondent":"若月教育長","answer":"教員もあるんですよ。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"私はわからないので、もう一度伺いますが、待遇はどうなっているんですか。その仕組みをちょっと説明を求めました。","respondent":"河野指導課長","answer":"再任用管理職の待遇ですが、細かなことは私もよく存じ上げておりませんが、給与等については現職時のおおよそ３分の２程度ということで、職務、内容的には現職のときと全く同じという制度です。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"再雇用で、指導課で「品川区非常勤職員（保育課）」となっているんですが、これはどういう意味でしょうか。教えていただけますか尋ねました。","respondent":"河野指導課長","answer":"現在本区では園長心得発令ができませんので、小学校長が兼任園長ということで、園長を兼務されているです。ぜひ空いている２日のうち１日でも結構なので、週１日だけ品川区の非常勤職員ということで、保育課に勤務されているです。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"すばらしい教育をされているなと思うんですけれども、園長先生、前は副園長先生だったんですかね。ですから、こちらも資格要件があるならば、そういう形で採用できるというか、昇任するということでよろしいんか尋ねました。","respondent":"河野指導課長","answer":"基本的には、資格要件がそろえば、これは品川区独自の制度ということで、園長心得発令をしております。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問・要望","question":"副園長先生等々、頑張っておられる先生が現場におりますので、できれば園長先生という形で、昇格していただくような形で、そうしていただきたいなと要望して、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]},{"id":"topic-03","title":"続きまして、(4)「夏期巡回ラジオ体操品川区大会の実施について」","agenda":"続きまして、(4)「夏期巡回ラジオ体操品川区大会の実施について」","exchanges":[{"speaker":"南委員","kind":"質問","question":"ちょっと聞き漏らしちゃったんですけれども、１７年ぶりというのは、品川区で開催するのが１７年ぶりという、そういう意味なんですか。この会場というのは主催者側が選んでこられるんですか、その辺の、会場の関係はどういうふうに設定されるのかというのを教えていただけますか。","respondent":"富田生涯学習課長","answer":"委員おっしゃるとおり、品川区内がラジオ体操の中継会場となるのが１７年ぶりということです。全国初の小中一貫校を会場に、品川区の元気を全国に向けて発信したいということで招致をし、今回決定をしたものです。","id":"exchange-021"},{"speaker":"南委員","kind":"質問","question":"全然否定するものではないし、みんなの健康を向上するという点でも、体操をするというのはいいことだと思うんですけれども、５時半から受付。ちょっとどうかなというのがちょっと気になったので、どんなふうに考えておられるのか伺って、終わりにしたいと思います。","respondent":"富田生涯学習課長","answer":"大崎第一地区の町会長会議にも従前にも話をしておりますし、本日も町会長会議が開かれておりますので、そちらのほうでご案内をしております。","id":"exchange-022"},{"speaker":"西本委員","kind":"意見","question":"呼びかけもどういうところまで行っているのか。それによっては、２,０００人というといろいろな方がいらっしゃると思うんですが、安全確保、セキュリティーの問題はどういうふうに解決されるのかとの意見を述べました。","respondent":"富田生涯学習課長","answer":"そういった意味で、周知につきましては、朝早いので、大崎第一周辺の地域の方々を中心にお知らせをさせていただいているところです。生涯学習課はじめスポーツ協会ですとか、体育指導委員会の応援等々もいただいて、その辺の会場整備には万全を期したいと考えています。","id":"exchange-023"},{"speaker":"大沢副委員長","kind":"質問","question":"小学校でもラジオ体操を教えていると思うんですけれども、お母さん方、地域の子どもたちに対する投げかけはどういうふうにされるのかというのが一つ。６時半ですか、これはラジオでやっているんでしょうか、教えるわけなんか尋ねました。","respondent":"富田生涯学習課長","answer":"日野学園のほうが中心になって検討しているところでありますが、そういう意味では、ちょっとその辺は難しい面もあろうかなと思っています。そういった意味では強い動員ということはかけておりませんで、希望される方々においでいただければと思っているところです。","id":"exchange-024"},{"speaker":"大沢副委員長","kind":"質問","question":"もしくはラジオ体操連盟ということなんですけれども、これ、現状として車いすの方というのは参加されているんでしょうか。これというのは今まではどういう形で、そういう方も参加されているんか尋ねました。","respondent":"富田生涯学習課長","answer":"申しわけございません。日野学園の校庭なり、体育館なりというところについては、車いすの方もおいでいただける場所というふうには考えております。","id":"exchange-025"},{"speaker":"南委員","kind":"意見","question":"調査項目に上がらなかったので残念なんですけれども、少人数学級、あるいは少人数学級をチームティーチングという形で少人数教育をしているという、そういうとらえ方もあるので、少人数教育をしているところを見てみたいなと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"西本委員","kind":"質問・要望","question":"そういうところがあったら、調査させていただきたいなと思っているところがあります。あればというところですけれども、それらも含めていい事例があったら、調査させていただきたいなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"金野委員","kind":"質問","question":"平成１７年度も視察をされているようですし、続いてしまうことがあってもいいのであれば私も研究をしたい、そのように思っています。日程的なものなんですけれども、内容の件に行ってもよろしいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"金野委員","kind":"質問","question":"できれば週末の週というんでしょうか、１０月２９日の週あたりというふうに、いかがなものなんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"南委員","kind":"質問・要望","question":"それぞれ事前に理事者からレクチャーを若干受けてという、そういう委員会運営をしていたところもあるので、改めて希望しておきたいと思います。私は、できれば月末ぎりぎりよりも、その前の週、２２日からの週に設定していただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"１１月が入っていないのでわからないんですが、第４定例会の日程はどうなっているんでしょうか。それによっては月末でも構わないんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"山内委員","kind":"質問","question":"これは視察先の日程というものも絡んでくると思うので、正副委員長で一任という形で。そうしないと、まとまらないですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"西本委員","kind":"質問","question":"今どういう形で小学校、先生方の機能的なところはどういうふうに変わってきているのかとか、その辺のところを伺いたいと思います。","respondent":"藤森小中一貫教育担当課長","answer":"日野学園では１年少したったわけですけれども、今のところ１件もないという報告を日野学園のほうからは受けているところです。１年たって、あるいは、指導の難しさみたいなものを改めて認識しているというような声をいただいているという報告をいただいておるところです。","id":"exchange-033"},{"speaker":"西本委員","kind":"質問","question":"あわせて、伊藤学園のほうはいかがですか。何か学校のほうからお聞きになっていることがございましたら。","respondent":"藤森小中一貫教育担当課長","answer":"それと、前回６月９日でしょうか、運動会が行われました。特に大きな課題として、保護者の方から問題点として挙がってきたというようなご報告は、今のところ教育委員会のほうには届いておりません。","id":"exchange-034"},{"speaker":"西本委員","kind":"質問","question":"ある程度バランスのいい形でできたということ、非常にすばらしいなと思っていたんですが、日野学園のほうはどういう評価になりますか。一つ例にとって運動会でどのような、これは２回されていると思うんです、保護者の方たちの意見とか、それはどうか尋ねました。","respondent":"藤森小中一貫教育担当課長","answer":"一貫校で、１年生から９年生まで一緒にやったところから来る一体感だとか、大変よかったというような評価をおおむねいただいているところです。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問・要望","question":"それで安心しました。小中一貫教育というものが始まる中で、相乗効果が出るような形で、今後も頑張っていっていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"南委員","kind":"質問","question":"その辺というのは具体的にどういうことなのか、１年生ら９年生まで一緒の日に、その辺をちょっと教えていただけますか。","respondent":"藤森小中一貫教育担当課長","answer":"１年生や２年生が体力的に厳しくなっているという状況の場合は、あるいは水を飲ませたりとか、どこの学校でも対応している。１年生から９年生までだから何か特別な対応をとらなければいけないという状況だという認識は、教育委員会としては持ってございません。","id":"exchange-037"},{"speaker":"南委員","kind":"質問","question":"そうすると、どこの学校でも、低学年については、大体３時ぐらいまでかな、２時半か３時ぐらいまで、運動会のスケジュールの中では、休憩はとらせていると、こういうことなんか尋ねました。","respondent":"藤森小中一貫教育担当課長","answer":"対応は考えておりましたけれども、あるいはさまざまな総合的な見地から、全体で休憩をとるというようなことはしなかったわけです。ですから、それもケース・バイ・ケースであると認識しています。","id":"exchange-038"},{"speaker":"南委員","kind":"質問・要望","question":"大丈夫だろうという判断をして、とらせないことがあると、こういうことなんですか。学校側の判断というのはどういうところにあったのか、もう少し具体的に、わかるように教えてほしいと求めました。","respondent":"藤森小中一貫教育担当課長","answer":"その対応をとるということですので、あくまでも今回の運動会における低学年の措置というのは、その域の範囲内だと認識しています。そういったものを断えず学校は判断をして、対応をしているというような認識を持っております。","id":"exchange-039"},{"speaker":"南委員","kind":"質問","question":"今、１年生ら６年生までの一貫校でなくてもそういう対応はしているという話ですから、土台がそういうところにあるんだなと思います。２つ目には、ちょっとど忘れしちゃったんですけれども、そこについての見解をとりあえずお願いしたいと思います。","respondent":"長田教育次長","answer":"引き続きこういった一貫校のよさを生かした上で、特徴を生かした運動会等、学校行事をこれからも実施していきたい。こういうことのスタンスで進めていきたいと、このように考えているところです。","id":"exchange-040"},{"speaker":"南委員","kind":"質問・要望","question":"そこの盛り上がり、効果はどうなっちゃうんですか。その辺について、違うと教育長はおっしゃっているので、専門家としてのご見解をぜひ教えてほしいと求めました。","respondent":"藤森小中一貫教育担当課長","answer":"まさに学校の中での行事の位置づけが非常に重要なものだなということを改めて認識したところです。品川の子どもたちに合った発達段階でさまざまな教育課程を組んでいくという、こういうところでの一つの行事のあり方だということで考えてあります。","id":"exchange-041"},{"speaker":"南委員","kind":"質問・要望","question":"６年生の活躍の場が奪われてしまっているという、どうなのかなというのは、やはり教育委員会としては検証するべきだと思います。子どもの心身の発達に無理を期さないように援助していく、そこのところは見失っていただきたくないということを改めて申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問・要望","question":"多分に、日野学園はいすではなくて、座っていたんじゃないでしょうか。ですから、直接太陽に当たってしまうということがあるので、それだと、学校側で安全性を見たときに、休憩をさせたんじゃないかなと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"そういうふうでありますので、日野学園の今回の対応が違ったということは、環境が、多分座っていたんじゃないかと思います。その辺はいかがか尋ねました。","respondent":"藤森小中一貫教育担当課長","answer":"私の記憶しているところでは、児童用のいすだったと思いますけれども、実際にそこで温度計を持って調べているわけではないですけれども、実際の学校の毎日使っている校庭ですので、その辺のところは最終的には校長の判断があったんではないかなと認識しています。","id":"exchange-044"},{"speaker":"市川委員","kind":"質問","question":"優先順位をどういうふうにして調理代行を実施していくのかということの質問と、実際に石けんを使用している５校を教えてほしいというのと、それともほかの理由で石けんに切りかえることができないのかということを伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"市川委員","kind":"意見","question":"そうですね。どういう理由で調理代行にしていくのかというとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"市川委員","kind":"質問","question":"給湯栓がないというのは考えられないんですけれども、どういうことなんでしょうか。給湯栓設備がないというのは。","respondent":"古里学務課長","answer":"したがって、回転がまのそばに給湯栓がない場合には、そういうことができません。したがって、給湯栓がないところ、それが６校ありますというお答えをさせてあります。","id":"exchange-047"},{"speaker":"市川委員","kind":"質問・要望","question":"石けんを使うことが、構造上難しいということだということがわかりました。その時点で４３校については石けんが使われていて、石けんの利用を促進していただくよう要望いたしまして、私からの質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"南委員","kind":"質問・要望","question":"その確認を。給湯設備がないということがどういうことなのかを確認したいんですけれども、もう一度教えてほしいと求めました。","respondent":"古里学務課長","answer":"回転がまのすぐ横にいわゆる給湯栓、要するに蛇口をひねるとお湯が出るというところがない。そこからホースで持ってくるということができませんから、それが必要になりますので、その栓がないということを申し上げたところです。","id":"exchange-049"},{"speaker":"南委員","kind":"質問","question":"洗浄する流しがあるじゃないですか。深いシンクにお湯を入れて洗うというイメージなんですけれども、回転がまが出てきているというのは、こういう使い方をするものなんか尋ねました。","respondent":"古里学務課長","answer":"回転がまで洗うものについては、トレーですとか、その他いろいろなものがあります。食器については専用の食器洗浄器がありますから、そちらで扱っております。","id":"exchange-050"},{"speaker":"南委員","kind":"質問","question":"そうすると、食器洗浄器の洗剤というのは合成洗剤なんですか。それとも、いわゆるお湯で溶かして使うような、こういう環境に優しい洗剤なんか尋ねました。","respondent":"古里学務課長","answer":"食器洗浄器につきましては、構造上石けんを使うことができませんので、合成洗剤を使っております。それで、専用の中性石けんを使っているというように聞いております。","id":"exchange-051"},{"speaker":"南委員","kind":"質問","question":"そうすると、回転がまで石けんを使っているというのは、トレーとか、食器洗浄器で洗浄しない食器のみにとどまっているということなんですか。あるいは回転がまというのはそういう性格も持って設備されているのか、基本的なところがわからないので、教えてもらいたいんですけれども。","respondent":"古里学務課長","answer":"したがって、一般的なシンクの中にお湯をためますと温度が下がりますから、溶けにくくなる。終了後はきれいに洗って安全にするということ、こうしたことから編み出された洗浄方法ですので、私どもはそれを引き続き今も行っているです。","id":"exchange-052"},{"speaker":"南委員","kind":"質問・要望","question":"どうしても出てくるじゃないですか。質問できないということであっては、自由闊達にやっていくべきだなと考えていますので、いろいろと。","respondent":"若林委員長","answer":"以上で本日の予定はすべて終了いたしました。","id":"exchange-053"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/120587?Template=document&Id=4606#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":36103,"voices":140}},{"id":"h19-20070626-5","meetingId":"h19-cm06","date":"2007年6月26日","dateIso":"2007-06-26","committee":"総務委員会","time":"午前１０時０３分～午後０時１３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件整理しています。","topics":[{"id":"topic-01","title":"平成１９年度組織改正","agenda":"平成１９年度組織改正","exchanges":[{"speaker":"浅野委員","kind":"質問","question":"各課に出すと思うんですけれども、その事務の部分を区民生活事業部に移したという、そのような考え方でよろしいのでしょうか。そういう手順になっていると思うんですけれども、そのような認識でよろしければ問題ないかなと思い、ちょっと質問させていただきました。","respondent":"桑村危機管理室長","answer":"区民への対応とか、計画をつくるところまでは危機管理室で対応いたしますけれども、基本的には防災課の方が対応。それに危機管理室がフォローで入ってくるような形につくり変えたものです。","id":"exchange-001"},{"speaker":"菊地委員","kind":"質問","question":"総務委員会では全体の報告がありますけれども、細かいところに入っていくと、これそのものは各所管でも同じような報告はされるんですか。ちょっとそこをお聞かせ願えますか。","respondent":"堀越行財政改革担当課長","answer":"各所管委員会の方では、事務事業概要の報告のときにあわせて。どこまでやっているかというのは詳細には把握はしていないんですけれども、一定の部分については出させていただいていると思います。","id":"exchange-002"},{"speaker":"菊地委員","kind":"意見","question":"こういう相談も一係、二係、三係というふうにそれぞれやりますよね。わざわざ一つにまとまっていたものを分割していく理由というのが、ちょっとよくわからないんですけれども、その辺がわかればとの意見を述べました。","respondent":"堀越行財政改革担当課長","answer":"エリアごとに一連のケースの相談に応じるというのが効率的であり、より効果的であろうという観点から、今回のような改正を行っています。もちろん、この三係全体の中で全体調整という形も入りますし、その辺はそういった形で進めていくというふうに聞いています。","id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"二係、三係、それぞれに調整会議や何かにも出て行く体制になっていくということになるんでしょうかね。","respondent":"堀越行財政改革担当課長","answer":"個別のケース対応についてはそれぞれの係で行いながら、また必要に応じて、先ほどの繰り返しになりますけれども対応していくという形。統括機能は第一係の方で持っているという形になります。","id":"exchange-004"},{"speaker":"武内副委員長","kind":"質問・要望","question":"どうしても新しい部署を置かないと対応できないということで置いた、１年後とか、またお願いだけさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"}]},{"id":"topic-02","title":"移ります。(3)第６次総合実施計画","agenda":"移ります。(3)第６次総合実施計画","exchanges":[{"speaker":"菊地委員","kind":"意見","question":"一つよくわからないのは、見開きで「基礎自治体としての品川区」というところで、下に「権限委譲のさらなる働きかけ」というのがありますけれども、今、説明をどこか聞き漏らしたのか、もう少し具体的にそこをとの意見を述べました。","respondent":"日下部企画財政課長","answer":"だから、後で最後にご報告しますが、都区のあり方に関する検討という形で、少しステージを変えて、これから進めていかなきゃいけない。全体的にはまだまだ権限とか財源の問題というのが一つの課題として残されておりますので、そういうことも含めて進めていこうという考えです。","id":"exchange-006"}]},{"id":"topic-03","title":"基本構想等の策定","agenda":"基本構想等の策定","exchanges":[{"speaker":"土井委員","kind":"意見","question":"基本構想策定委員会について若干。どういう形でその皆さんに落ち着いたのかなというところの経緯等ありましたら、ちょっとお聞かせいただけませんかとの意見を述べました。","respondent":"福島長期計画担当課長","answer":"区内関係者につきましては、先ほどご説明しましたように、町会連合会長等、区とかかわりのある団体の方を中心に選ばせていただきました。","id":"exchange-007"},{"speaker":"菊地委員","kind":"意見","question":"庁内の検討部会というのがありますね。こういう公募区民の皆さんが集まられて行われる１２回の審議にどういうふうに反映されて、どうしても、その辺をどういうふうに考えればいいのかとの意見を述べました。","respondent":"福島長期計画担当課長","answer":"さらに、特に長期基本計画についてどういった計画をつくっていくか、そういうことについて検討しているものです。一定程度庁内で検討したものを策定委員会に出しまして、策定委員会の方でさらに議論いただきまして、それでさらに議論を進めていくという形です。","id":"exchange-008"},{"speaker":"菊地委員","kind":"質問","question":"ということは、この庁内検討会で出されたものが議論のおおもとになるという考え方でいいんですかね。","respondent":"福島長期計画担当課長、福田企画部長、林委員長","answer":"策定委員会にお出しする原案を作成するです。さらに、今後の品川区の長期計画をどのように進めていくかということについても検討しているものです。したがって、不可分一体のものですので、それを庁内のこの検討部会でよく吟味をして策定委員会にご報告をするという、大ざっぱなシステムです。… 庁内の検討会、部会でつくられたものが原案として提出されるということなんだけど、「原案として」なんていうのはここに一切ないですよ。","id":"exchange-009"},{"speaker":"原委員","kind":"意見","question":"先ほどの件でもう１回ご議論いたしますけれども、学識経験者のご説明を受けて理解したつもりではおるんですけれども、公募区民５名というのは、具体的に何名ぐらいの応募があったのかからお教えいただければと思うんですがとの意見を述べました。","respondent":"福島長期計画担当課長","answer":"公募区民についてご説明します。あるいは居住歴、そういったものを勘案しまして、５名を選ばせていただきました。","id":"exchange-010"},{"speaker":"原委員","kind":"質問","question":"はっきりしないところがありますので、そこのところの年齢とか地域という、その辺のところをもう一度ご説明いただいてよろしいか尋ねました。","respondent":"福島長期計画担当課長","answer":"あるいは無職で子育て中の方、そういう様々な区の層、区民を代表するような層ということで選ばせていただいております。さらに専門的な学識経験者と一般の公募区民の、区民を代表する声、これらの要素を持ちながら検討を加えていただければと考えています。","id":"exchange-011"},{"speaker":"浅野委員","kind":"質問・要望","question":"こちらの方の文章では、現行の基本構想が昭和６３年となっているので、１回見直しか何かされているのかなということをちょっとご説明いただきたい。総合実施計画第６次というのが、何に対して６次なのか、具体的なお考えがありましたら教えてほしいと求めました。","respondent":"林委員長、日下部企画財政課長","answer":"じゃあ、基本構想、長期計画、それから実施計画の全体像を一度企画財政課長から。今回のというよりも、品川区の中の全体の形をご説明ください。当初予定していた施策がどの程度実現を図って、３年スパンで予定をしておりますけれども、これが先ほどの実施計画です。","id":"exchange-012"},{"speaker":"浅野委員","kind":"質問","question":"第三次が１０年というふうに伺ったんですけれども、先ほどの基本構想等の策定について、第三次の次は第四次かなと思っていたんですけれども、それを策定して以来既に１０年というのと、第三次のここに書かれている１０年というのをちょっと理解できないので、すみません。","respondent":"日下部企画財政課長","answer":"ですから、６３年の基本構想に基づいて、それを改定して第三次が平成１３年からスタートした。その間一時、第二次の改定作業というのがありましたが、大きなところで申し上げればそういうことで、平成元年以降、大体１０年スパンで来ているです。","id":"exchange-013"}]},{"id":"topic-04","title":"移ります。(5)パブリックコメント実施（案）","agenda":"移ります。(5)パブリックコメント実施（案）","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"どの程度、重要性として区が考えておられるのかというのを、ちょっと教えていただきたいんですけれども。","respondent":"中川原広報広聴課長","answer":"区民の方に区政参加していただくとか、透明性の確保につきましては、情報公開制度を始め、いろいろな参加の手法があります。今回、改めてパブリックコメントもその一つとして加えさせていただいたです。","id":"exchange-014"},{"speaker":"菊地委員","kind":"意見","question":"先ほどの情報公開のあれもありますけれども、そうすると、ここでつくられている別紙３の要綱という形で制定をされている。要綱と条例の違いといいますか、どうして条例じゃないのかなという思いがあるんですけれども、そこをちょっとの意見を述べました。","respondent":"中川原広報広聴課長","answer":"いろいろと考えながら運営していかなければいけない問題がありますので、よりよい制度としていくために、現段階では要綱設置で運営させていただきたいというふうに考えています。","id":"exchange-015"},{"speaker":"菊地委員","kind":"意見","question":"さっきの話だと、これから要綱からさらに発展して条例にしていく可能性を持っているというとらえ方でいいのかどうか、そこもちょっとお聞かせ願えますかとの意見を述べました。","respondent":"中川原広報広聴課長","answer":"今、パブリックコメントだけを条例化して、うまくいっているという自治体はあまりないんですね。先ほどの最初の質問の答えになるかと思いますが、きょうも再三申し上げておりますが、将来的な課題としてとらえさせていただきたいと思います。","id":"exchange-016"},{"speaker":"原委員","kind":"質問・要望","question":"議員の先生方が入っておられてつくられたということを伺っていたような記憶があるんですけれども、区長の裁量権というか、適用除外の部分なんですね。範囲的なところがはっきり、ある程度の担当部署でのお考えがあるのかどうか、その辺をもうちょっと詳しくご説明いただけると助かるんですが。","respondent":"中川原広報広聴課長","answer":"区民公募手続を書けたほうがいい事業は、区長がやりましょう」という形で各所管に投げかけて、そういう形でこの趣旨を徹底していきたいと考えています。","id":"exchange-017"},{"speaker":"原委員","kind":"質問","question":"３ページ目の左の方にも議会への報告、１行ぱっと書いてあるだけのことなので意味がわかりにくいんですけれども、その辺のところをもう少し教えていただけますか。","respondent":"中川原広報広聴課長","answer":"改めて「こういった形で変更する」ということを議会の方に報告をするという、品川区の場合は、議会との関係を明確に規定しております。そういったことも踏まえまして、品川区の場合はこういった形で、制度の中にルール化をさせていただきました。","id":"exchange-018"},{"speaker":"原委員","kind":"質問・要望","question":"おっしゃるとおり、品川区のはちゃんとしておりますので、それにのっとって運んでいっていただきたいという要望をつけします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"土井委員","kind":"質問・要望","question":"どんどん進めていかなきゃならない中身だということを前提として一つ伺いたいんですけれども、コメントを求めますと。その意味では、我々自身も「そんなんじゃ困るんだよ」ということも含めて言っていかなきゃいけなくなりますので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]},{"id":"topic-05","title":"続きまして(7)東京富裕論に対する反論","agenda":"続きまして(7)東京富裕論に対する反論","exchanges":[{"speaker":"土井委員","kind":"意見","question":"そういうところを、この中身よりも、そういう活動、運動の部分はどうなっているのか、どうするのかというところがすごく問題だ。どうみんなのものにするか、どうみんなで一緒にやるかというために、その辺についてちょっと説明を求めました。","respondent":"日下部企画財政課長","answer":"例えば５月末には８都県市の首脳会議で、６月１２日は、そういう取り組みをしている。それから、東京都をはじめとした関係する大都市部とも一緒に連携しながら、今後、必要な運動展開を進めていくことが大事だと考えています。","id":"exchange-021"},{"speaker":"土井委員","kind":"質問・要望","question":"今までも、集中できないということが起こっているわけで、ここは何とかそうならないように気をつけてやっていただきたいなと思います。まあ、この論には大賛成でありますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"菊地委員","kind":"質問","question":"１ページ目にある、東京の順位は２２番目だとかというのは、同じような体制の中で生活が安心してできる。これは区長会で出していることですからどうのこうのという話でもないんですけれども、そういう打ち出し方でないと、その辺は。","respondent":"日下部企画財政課長","answer":"直接的ではありませんが、このあたりでご説明させていただいているというものでもありますので、その辺はご理解いただきたいと思います。","id":"exchange-023"},{"speaker":"浅野委員","kind":"質問・要望","question":"固定的にかかる部分と、また交付につきましても、どうしても人口比率にして持ってきたほうがいいんじゃないかというような意見も散見されるんですね。ですから、区としては区民の生活を守っていることを前提においてやっていただけたらと、これは要望ということで出します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]},{"id":"topic-06","title":"の２行政視察","agenda":"の２行政視察","exchanges":[{"speaker":"浅野委員","kind":"意見","question":"出てこないとどういうものかというのはなかなかわからないところもあるんですけれども、島根で、あとは住民が相互にテレビ電話で話ができる。これが総務委員会で適切かどうかというのはあると思うんですけれども、そういうのもぜひとも見ておきたいなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"菊地委員","kind":"意見","question":"どこがどう動いているか、インターネットを見たけどよくわからないところなんですけれども、そういうものがあればぜひ行ってみたいなと思いますとの意見を述べました。","respondent":"林委員長","answer":"今、いただいたものを含めて、正副で検討するということでよろしいですか。","id":"exchange-026"},{"speaker":"土井委員","kind":"質問","question":"月曜日は、本会議後すぐですから、避けたほうがいいような気がします。相手の都合もあるしね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]},{"id":"topic-07","title":"の３その他","agenda":"の３その他","exchanges":[{"speaker":"土井委員","kind":"質問","question":"投票所ですが、この前の知事選とか区議選と変わったところはありますでしょうか。というのは、もしも変わるようだったら、早めに知らせる方法はないかなと思ったので。","respondent":"野田口選挙管理委員会事務局長","answer":"投票所とすれば、変更はございません。体育館が教室になるとか、そういうようなところがどうなるかというような調整はありますけれども、投票所は変更がないということです。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/495406?Template=document&Id=1754#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":42244,"voices":110}},{"id":"h19-20070627-14","meetingId":"h19-cm06","date":"2007年6月27日","dateIso":"2007-06-27","committee":"行財政改革特別委員会","time":"午前１０時０２分～午後０時０２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（ひ）委員長","kind":"質問・要望","question":"前回、今後の委員会運営について皆さんからご意見をいただくとともに、文書にて提出をお願いしましたところ、幾つか要望が出されました。そこで先日、理事者の意見も伺いながら、皆さんのご意見も踏まえて正副委員長で調整をさせていただきました。","respondent":"中島経理課長","answer":"こちらに載っています品川区内共通商品券につきましては約１,２４９万円と大きいんですけれども、随意契約で購入しているというものです。","id":"exchange-001"}]},{"id":"topic-02","title":"契約のあり方に関すること","agenda":"契約のあり方に関すること","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"法令遵守は契約をする際に確認されているとは思うんですけれども、どういう形でその確認をするのかということを１つ伺いたいのと、当然。もちろん企画の内容や、その会社に対してどういうふうに判定をしていくのか、その辺の基本的な姿勢について説明を求めました。","respondent":"中島経理課長","answer":"基本的には、先般ご説明しましたけれども、品川区が契約する業者につきましては、まず登録業者になることが必要だです。当然、その基準に沿った形で、必要な場合については処分をかけるということで対応しているです。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"そういう中で、こういった業者と業務委託を結ぶときに、そういうところがどのように対応があったのかなというところが１つ伺いたいところです。そういう状況というのは、そもそも契約のときに区はどうやって把握をするというのか、その仕組みを教えていただけますか尋ねました。","respondent":"中島経理課長","answer":"一部、その段階では入札の基準には該当しているということで、そういった業者を除外するということが実際問題できないものという考えです。先ほども申し上げましたとおり、私どもの基準に従って、一定の処分をかける必要があれば処分をするです。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"裏を返せば、その資格自身の基準がどういう基準なのか僕はまだわからないので、少し説明してほしいと求めました。今の時点で改善策や問題点、どのような認識を持っているのか、ご説明ほしいと求めました。","respondent":"中島経理課長","answer":"そういった意味では、私どもの現在の契約の中での問題点は出ていないものと認識しています。資格基準につきましては、それは今の政令の中にあるもので、今それを出しまして、後ほどご答弁します。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"１つひとつ見るのは大変苦労もあるかと思いますけれども、その業務を契約している相手の中に人材派遣会社というのがあると思うんです。契約の際に、この違法行為が多発している会社に対してどういうチェック機能が働いているのかなというのが１点と、区の現状認識を説明を求めました。","respondent":"中島経理課長","answer":"そこまでの確認をできない限り、私どもとして指名停止をかけるとか、入札に参加させないとかということはなかなか難しい問題だろうと考えています。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"そういう東京労働局の指導を受けている会社があるのかないのか、僕のほうでは調べようがないので、ちょっと状況を教えていただきたいのが１つです。ただ、ちょっとこの派遣業者の法令違反の多さからしても私は問題があるんじゃないかと思うんですけれども、どんなふうにお考えか尋ねました。","respondent":"田中総務部長","answer":"これは例えば品川区も４,０００件ありますし、日本中にはもう大変な数の企業があるわけですから、私どもがなかなか排除はできない。原則は随意契約というのは今日るるご説明申し上げましたとおり、そういうところをきっちりつかまえた上で、こういうところを選ばない。","id":"exchange-006"},{"speaker":"中塚委員","kind":"確認","question":"そういうのが人材派遣会社で行われていると確認され次第、１点教えてください。この状況は区として東京都に連絡をとって把握する必要努力はあるのではないかと思うんですけれども、いかがか尋ねました。","respondent":"中島経理課長","answer":"あるいは、私どものほうで「入札に参加させない」とか、「契約をしない」と言うことは難しい問題かなと考えています。そういった部分ではそのほかの方法もありますし、そういった２３区での情報交換等もありますので、さまざまな方法で確認をさせていただいているです。","id":"exchange-007"},{"speaker":"中塚委員","kind":"意見","question":"３,７５６事業所のうち、１,２７５事業所が指導監督、そのうち是正指導が８８６事業所。指導監督とか是正指導とかを受けている会社がどこなのか、私は把握する必要があるのではないかと思うんですけれども、もう一度お願いいたしますとの意見を述べました。","respondent":"田中総務部長","answer":"件数等いろいろ業種も人材派遣だけではなくてたくさんありますので、どこまで把握ができるかということは非常に難しいという部分が１つあります。確かに、また違うかなと考えています。","id":"exchange-008"},{"speaker":"中塚委員","kind":"意見","question":"１つひとつの積み重ねで最終的に大きく噴き出る。契約の際の基本的な姿勢として問われるところがあるんじゃないかなと思うんですけれども、最後にもう１つだけお願いいたしますとの意見を述べました。","respondent":"田中総務部長","answer":"ああだったというのは、これはあくまで推測、現在そのうわさの中で何が私どもが判断できるかは非常に難しいと考えざるを得ないと思っています。すべておっしゃることに対して対応できるかというのは、これは全く膨大な件数、膨大なチェックが必要ですのでできない。","id":"exchange-009"},{"speaker":"武内委員","kind":"質問・要望","question":"この予定価格を事前公表するメリットとデメリットというところについて教えていただきたいのと、電子入札が昨年の４月から工事案件で３,０００万円以上のものは電子入札となっているんですけれども、教えてほしいと求めました。","respondent":"中島経理課長","answer":"予定価格の公表が高どまりになるというようなデメリットはないものと私どもは考えてあります。第１グループの会社、第２グループの会社はそれぞれペアリングをするという作業がありますので、電子ではやってございません。","id":"exchange-010"},{"speaker":"武内委員","kind":"質問・要望","question":"は今、これが今後もうちょっと方向性として下がっていくのかどうかとか、その辺の動きについて教えていただきたい。は電子入札については、今度は工事案件ではなくてほかの物品とか委託とかその辺まで考えているのかどうかという、この辺を教えていただきたい。","respondent":"中島経理課長","answer":"今回２回目の入札を今度予定しておりますけれども、その２回目につきましては予定価格は変えないで、現在その事務を進めているところです。それと、公表のお話ですけれども、工事については現在１,０００万円以上を予定価格を公表しています。","id":"exchange-011"},{"speaker":"阿部委員","kind":"質問","question":"電子入札の導入前と導入後で、落札率の変化というのはありましたでしょうか。ちょっと数字などを説明を求めました。","respondent":"中島経理課長","answer":"ただ、平成１７年度と１８年度を比較しますと、制限付き一般競争入札の落札率がたしか２％ほど下がっているです。それが電子入札の効果かどうかはあるんですけれども、１つの要素としてはあるのかなとは考えてあります。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問","question":"その点をもう１回お聞きしたかったのと、児童センターとか保育園とかすまいるスクールなどの人材派遣のところの契約がどう行われているのか、その辺を再度。","respondent":"中島経理課長","answer":"今年から総合評価方式を導入しましたので、平成１９年度の契約に向けては、総合評価方式で実施して、３年間引き続き契約するという考え方です。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"中の者だけなんでしょうか。このところ事故が多いものですから、特に命を預かるところにおいての安全性の担保を契約段階でどう確保できるのかというところをお伺いしたい。","respondent":"中島経理課長","answer":"それから「安全対策を具体的にどう考えていますか」、あるいは「万が一、さまざまな項目を審査した上で決めていくです。そういった意味で、ヒアリングあるいは審査の中で一定の安全性は担保できるものと考えています。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１つその辺の給食の調理代行の業者変更について、どういうふうに今考えているのかというところでお聞かせいただきたいんですが。防ぐ手だてというのはないのかと思うんですけれども。","respondent":"中島経理課長","answer":"実際に学校をやっている中で、会社としてこのまま１年間契約することは難しくなってきたということで、会社のほうから申し出があって解除をしたです。ただ、現場に混乱は起きていないと私どもは聞いてあります。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問","question":"本当に１３校と大幅に拡大をしていく中で、そこの業者がどれだけの経験や能力をある方を確保できるのか、やっぱりそこが追いついていっていない。直営に戻すべきであるなというのは常々ずっと思っているわけですけれども、ぜひ今の段階で必要だと思うんですけれども、その辺を再度お伺いします。","respondent":"田中総務部長","answer":"私どもは今、契約のあり方のお話を説明させていただいたのでありまして、給食調理なり。やはり各主管課のほうで、こういう業務執行をすべきではないかというのは、ちょっと私どもは直接的には現在お答えできかねると考えております。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問","question":"だから、契約の段階でどうこのような事故を防いでいくのかというところをお伺いしているんです。だから、仕事をしている部分の職員の方々の立場もきちんとする意味でも、やはりすごく契約の段階での重要性があるんだと思うんですよね。","respondent":"田中総務部長","answer":"そういう意味では事故のないように、あるいは履行をきちっとしていただくようにということを考えて契約業務を進めさせていただいてあります。これは確かですけれども、最大限そういう意味でのチェックはできる限りしていると申し上げたいです。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問","question":"契約はこうだけれども、後の問題だといって済まされるのかどうか。後のチェックの仕方とかはいろいろあると思いますけれども、仕様書とか契約の段階でもっとできることはないのかというところで質問しています。","respondent":"田中総務部長","answer":"あるいは総合評価、そういう方式も含めて、日々努力をしているというふうに申し上げたいと思います。あくまで、学校の調理代行は何校広がる云々というのは、これは私どもが所管しておりませんので、ちょっとその辺についてはお答え申し上げかねます。","id":"exchange-018"},{"speaker":"林委員","kind":"質問","question":"調理代行をやめるべきだなんていう話は、ここでやったら所管の委員会を侵害することになるんですから。その辺をちょっと聞かせてくれませんか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"林委員","kind":"質問・要望","question":"あるいは逆に言うと、品川区の話じゃないかもわからないけど、国の仕事、都の仕事なんていうのはＪＶが多いわけじゃないですか。品川区の場合はせいぜい２か３ぐらいのＪＶだけど、前に進まないということになるんだけど、先は見えていないんか尋ねました。","respondent":"中島経理課長","answer":"今の段階で、具体的にこうすればＪＶに対応できるというような方策はございませんけれども、今の委員のご指摘にもありますので、実施する方向でさまざまな手法を検討していきたいと考えています。","id":"exchange-020"},{"speaker":"原委員","kind":"質問","question":"では、先にＪＶについて事前に今お伺いしたいんですけど、Ａ、Ｂというような２パターンと。以前はＡ、Ｂ、Ｃとかいう段階のこともあったかと思うんですけど、その辺は今どうなっているか説明を求めました。","respondent":"中島経理課長","answer":"基本的には２社でやるのが多いですけれども、そこにつきましては３社ＪＶという形でやってございまして、額によって３社でやるということもあります。ただ、現実的には２社のＪＶ方式が多いです。","id":"exchange-021"},{"speaker":"原委員","kind":"質問","question":"親子という関係以外に、ある種のＡランクだけの関係も、これもまたＪＶであったりするわけですね？ちょっとその辺のことについて表現の仕方が同じなのか、みんな全部ＪＶと言っているのか、その辺のことを説明を求めました。","respondent":"中島経理課長","answer":"ＪＶ、いわゆる建設共同企業体方式というのは、格付のＡとかＢとかＣとかは直接に関係はございません。第２グループ、第３グループの場合に、Ｃということではないと考えております。","id":"exchange-022"},{"speaker":"原委員","kind":"確認","question":"確認ですがＪＶという表現をみんな全部使われてくるという形でよろしいですね。","respondent":"中島経理課長","answer":"そうです。いわゆる共同企業体ＪＶ方式です。","id":"exchange-023"},{"speaker":"原委員","kind":"意見","question":"ほかに、先ほどのご説明の随意契約の中で、たまたま委託で第三日野小学校のこの基準というのが出ている中でのご説明だったと思いますけど、プロポーザル方式で決定すると随意契約と、その辺をもうちょっとご説明ほしいと求めました。","respondent":"中島経理課長","answer":"ご説明していました契約の種別ですけれども、随意契約という３つの方法がありますけれども、それに基づいてやっているプロポーザル方式は随意契約です。","id":"exchange-024"},{"speaker":"原委員","kind":"質問・要望","question":"そのプロポーザル方式をもうちょっとお聞かせいただきたいんですけれども、要するに担当部署内で決定する、その決定のプロセス。現段階でその辺のお考えをお聞かせほしいと求めました。","respondent":"中島経理課長","answer":"公募方式でやるのか、あるいは指名方式でやるのか、そういった中でそれぞれ所管の部課長を中心に審査員を選定して決めていくと。さらに、大きいものについては、課長の他、部長の決定も含めて必要になるです。","id":"exchange-025"},{"speaker":"原委員","kind":"意見","question":"これはどういうふうになっているのか私は把握しておりませんが、３０点は経験値だと、今まで実績があるかないか。今まで区内の工事、もしくは委託とか、その辺のところまでの段階の公表をいただけるのかどうなのかということをちょっとお教えいただければとの意見を述べました。","respondent":"中島経理課長","answer":"契約簿という中で、例えばどういう契約についてプロポーザル方式でやったというのはわかるんですけれども、具体的に点数については現時点ではまだ公表はしてございません。","id":"exchange-026"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"先ほど来の質疑の中でちょっと私が聞き漏らしていたら申しわけないですが、指名停止の基準的なものは何か出してもらえるのかどうか。品川区でこういうケースがあったのかどうなのかというのが１点と、区としてどういうふうに考えていくのか、その考え方を説明を求めました。","respondent":"中島経理課長","answer":"それにつきましては私どもは既にもう当然公正取引委員会からの情報を得ておりますので、現在、その処分に向けて準備を進めているところです。","id":"exchange-027"},{"speaker":"鈴木（真）副委員長","kind":"意見","question":"今の中で、現実的に仮契約を結んだ後にというケースですよね、今回は。そのような形というのは区の中にあったのかというのと、もし、そのケースがなければ、考え方として今後どうするのかとの意見を述べました。","respondent":"中島経理課長","answer":"仮契約した後に、議決を受ける間に指名停止処分があったという場合については、契約はできないということになります。それで、最近そういった形で契約できなかったというのは、昨年はなかったと認識しています。","id":"exchange-028"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"仮契約したときに念書をとって、ことにこれは学校なので、工期の関係で契約が議会案件に上がったみたいなケースで読んでいるんですけど。これですと学校ということで２年間の補助金の期間も決まっちゃうので、そういうことはあり得ないということでいいわけか尋ねました。","respondent":"中島経理課長","answer":"議案というのは品川区の議案ということではなくて、東京都の議案だとすれば、東京都のほうで議案で上がって、議決される前に指名停止ということになれば、そことは契約できないものと考えています。","id":"exchange-029"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"２年間という期間が限られているのかなということも含めてさっき聞いたんですけど、品川区としては、ほかではあっても品川区ではないんだよということでいいわけか尋ねました。","respondent":"中島経理課長","answer":"第２回定例会の時期だと思うんですけれども、指名停止のおそれがあるというようなことで、今いろいろな問題になっているのかなと考えています。品川区では現時点ではそういった問題はまだ起きてございません。","id":"exchange-030"},{"speaker":"鈴木（真）副委員長","kind":"意見","question":"最後に、現時点じゃなくて、今後の考え方として、区としてこういうケースがあったときにはどう判断するのかなということを聞きたかったんですけれどもとの意見を述べました。","respondent":"中島経理課長","answer":"それで、今般、この防衛施設庁の関係で当然対象になれば指名停止になるわけですけれども、その場合、指名停止の期間が問題になります。当然その間に第３回定例会なんかもあるわけですから、その仮契約をしていたとしても、そこと契約することはできないです。","id":"exchange-031"},{"speaker":"阿部委員","kind":"質問","question":"先ほど別の委員からもちょっとプロポーザル方式についてお話があったので伺いたいんですけれども。基本設計ですから、より一層の透明性をつくっていくために何かお考えがあれば、説明を求めました。","respondent":"中島経理課長","answer":"ただいまのプロポーザル方式に関するご質問ですけれども、そういった透明性の部分で問題意識は当然持ってあります。そういった中で、今年試行しました総合評価方式にしましても、来年ぐらいには公表できるような形で検討を進めてまいりたいと考えています。","id":"exchange-032"},{"speaker":"阿部委員","kind":"質問","question":"その公表というのは、個々のということですか。それとも、仕組みとして、そういう公表の仕組みをつくっていくということなんか尋ねました。","respondent":"中島経理課長、堀越行財政改革担当課長","answer":"仕組みをつくって公表していくです。それから、(2)がランニング経費の縮減、(3)といたしまして民間経営のノウハウを取り入れると、ニーズへの対応が可能となるというものです。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問・要望","question":"指定管理者制度の仕組みについてちょっとお伺いしたいと思うんですけれども、その管理者としての区が連座制を適用されると。そこをちょっとご説明いただきたいのが１つ目と、今のこの資料だと２ページ目の５のところに、その取り消す区も処分を受けると。","respondent":"堀越行財政改革担当課長","answer":"もう１つ、その設置者として区のほうでその処分を受けるという関係にありますので、その関係の法令にのっとって処分を受けたです。取り消しですとか、そういった対応をしていきながら、設置者としての責任を果たしていくということになろうかと思います。","id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"この連座制というのは、そもそもこの指定管理者の中でどういう仕組みなのか、もうちょっとわかりやすく説明していただきたいと思ったんですね。その辺の関係が僕自身まだ不勉強なものですから、もう少し説明してほしいと求めました。","respondent":"堀越行財政改革担当課長","answer":"コミュニケーションをとりながら進めていくということが１つあります。そのような場合は設置者としての区のほうの責任というのは一定のものがあると思いますし、その場合はもちろん事業者としての責任もありますので。","id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"もう１つ指定管理者制度の仕組みで伺いたかったのは、一方で議会としては、議決を経て指定が決まるわけですよね。設置者としての責任はご説明があったので、議会として議決をした、指定したというのは問われるものがあるのかというのをお伺いしたいと思います。","respondent":"堀越行財政改革担当課長","answer":"議決事項は先ほどご説明させていただいた３つの事項ということです。一般的な考え方として、それに対して設置者として区のほうで責任が一義的にはあるというふうになっておりますので。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問","question":"どういう運営業態をしているのか、情報公開条例が１つかなめになると思うんですけれども、品川区の場合では指定管理者の相手ですね。受託業者の指定管理者の情報が、今の品川区の情報公開条例でどこまで及ぶのか、ご説明いただけますか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"基本的には指定管理をしていただく中で、協定等の中で区の基本的な情報公開に対する考え方にのっとった形で対応していただけるように協議をしながら。実際に情報公開というような形で請求があった場合には、協議をしながら対応していくという形で運用しています。","id":"exchange-037"},{"speaker":"中塚委員","kind":"質問・要望","question":"例えば千代田区では情報公開条例を改定して、いわゆる区の受託業者や指定管理者が保有する文書も制度の対象にというふうに明確に位置づけたんですね。区が管理する公文書と同様に、この認識と品川区の認識、位置づけと同等なのかどうかを聞かせてほしいと求めました。","respondent":"堀越行財政改革担当課長","answer":"先ほどご説明いたしましたとおり、協定等においてそのようなことを入れまして、実質的には同様の効果が得られているものと考えております。特に今、全体的な数をかっちりお答えするわけではないのですが、品川区と同様な考え方をとっているところも数多くあると認識しております。","id":"exchange-038"},{"speaker":"中塚委員","kind":"質問・要望","question":"情報公開条例の対象にすべきだと思うんですけれども、どんな議論があるのか、区の問題意識を教えていただきたいというのが１点。私は区の公文書と同様に指定管理者自身の公文書も情報公開条例の対象と明確にすべきじゃないのかなと思うんですけれども、２点、説明を求めました。","respondent":"堀越行財政改革担当課長","answer":"今、区の情報公開条例の中の公文書として位置づけるかどうかというその位置づけについて一定の議論があると申し上げたことです。２つ目のご質問に対する答えといたしましては、指定管理者側と協議をしながら対応をしているです。","id":"exchange-039"},{"speaker":"中塚委員","kind":"意見","question":"同様に扱っているという先ほどのお話と実際の運用と、ちょっとかけ離れている部分があるのではないかなと思うんですよね。ぜひこの情報公開の対象を明確にして、請求に真摯に応ずるべきではないかと思うんですけれども、現状のお考えを説明を求めました。","respondent":"堀越行財政改革担当課長","answer":"情報公開請求イコールすべて公開というわけではございませんので、そういった考え方にのっとって対応をしているです。いろいろな法的な位置づけですとか、そういった部分は区といたしましては工夫をしながら対応をしているというところをご理解いただきたいと思います。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問","question":"特にその法人が、丸投げと言っていますけど、その先にどう委託をしているか。社会福祉法人などに言わせると、どういう状況で行われているのかというところまで本当にどう把握をするのか、その辺をどう考えていらっしゃいますか。","respondent":"堀越行財政改革担当課長","answer":"そういった裁量の範囲を狭めないような、なおかつ、きちんと業務を遂行していただけるような観点からチェックをしていくと。法で定められているような有資格者等については、それに加えて把握をしていくという、そういった考え方が基本になろうかと思います。","id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問・要望","question":"指定管理者が把握をしている情報を文書できちんと行政が求めるべきであると思うんですけれども、事前にその辺をきちんと指定管理者が持っている情報を区が同等に持つべきであると思うんですけれども、その点はいかがか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"そちらにつきましては、当初の事業計画書の中にいろいろな組織管理体制、職員の配置体制とか、そういった部分について一定の記載事項がありますので、そういった中で事前に把握をしています。","id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問","question":"事前に把握しているということなので、指定管理者が委託をしている先までもきちんと事前に把握をしているということでよろしいんか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"いろいろな施設の性格ですとか、その配置、法令の資格ですとか、そういった種別に応じて、裁量を損なわない形で、なおかつ、適正な仕様にのっとった形で仕様の水準の業務を遂行していただくような形での人数の把握をしているです。","id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/471723?Template=document&Id=5820#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":37170,"voices":103}},{"id":"h19-20070628-16","meetingId":"h19-cm06","date":"2007年6月28日","dateIso":"2007-06-28","committee":"街づくり特別委員会","time":"午前１０時０３分～午後０時０８分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"山路委員長","kind":"質問・要望","question":"前回、今後の委員会運営についてご意見をいただきましたが、理事者のご意見も伺いながら、正副委員長で調整させていただきました。今年度１年間、このような形で進めさせてほしいと求めました。","respondent":"松代管理工事課長","answer":"前回のときにもご説明をしてまいりましたが、輪という連携が、あらゆる連携の方策等を検討していくというように考えていきたいと思っています。","id":"exchange-001"},{"speaker":"本多委員","kind":"質問・要望","question":"何点か、教えてください。もっと拡大をすると思うんですが、今時点で、わかる範囲でちょっと教えていただきたいと思うんです。","respondent":"松代管理工事課長","answer":"今のところは非常に難しいと考えていますが、規制緩和も含めて、今後どういうふうな形でできるのか。今後のいろいろな検討課題、実施できるような計画の位置づけという中でも考えていきたいと、思っているところです。","id":"exchange-002"},{"speaker":"本多委員","kind":"意見","question":"水上バスのルートがさらに拡大するように、そういう趣旨で、ちょっと聞かせていただきました。もし、何かあればとの意見を述べました。","respondent":"松代管理工事課長","answer":"それも、今のところは、防災上の観点といったことの利用ということで考えております。民間等が一緒になって進めていけるようなもの、今後、探っていきたいと考えているところです。","id":"exchange-003"},{"speaker":"本多委員","kind":"質問・要望","question":"ちょっと教えていただきたいんですけれども、そういうねらいとかがあれば、教えていただきたい。","respondent":"藤田道路公園課長","answer":"その数が、毎年４万から５万券発券されて、そういった方々が利用されているところです。お互いに案を出し合いながら検討をし、進めていこうということで、お話し合いをしています。","id":"exchange-004"},{"speaker":"山元委員","kind":"質問","question":"四季折々、ほんとうに、それこそ花の種からいろいろな援助をしていただいて、ずっとやってきました。運河がきれいになったら、もっと皆さん楽しめるんではないかなと思うんですが、その辺はいかがなんか尋ねました。","respondent":"松代管理工事課長","answer":"それぞれの個々の切り口でさらに細かくご説明をしますが、その一つとして、今の浄化対策等をきちんとご説明をする機会をつくりたいと考えています。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"その地域から伺って、親水公園を整備するということに対する要望はどういうふうに上がっているのかということ。そちらでの、親水公園としての実績というのは、どのように評価しているのかということをお聞きしたいと思います。","respondent":"松代管理工事課長、青木都市開発課長","answer":"乗っていただく、そういった活動を、今進めているところです。水上バスのところでお答えしましたように、そこで発着できるような形での利用等が、将来できないものかと考えているところです。 東五反田二丁目の親水広場について、補足してご説明申し上げます。そうしたご要望については、現実には、もうちょっと五反田駅に近いところに船着場が設置できないかというようなご要望はいただいたことがあります。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"今後、どうしても緑化指導をした以上のＣＯ２などがすごく出てしまい、ヒートアイランド現象に拍車をかけることは疑いがないことだと思うんですね。さらに、そのネットワーク構想の中に位置づけていこうとお考えなのか、現時点での考えをお聞かせほしいと求めました。","respondent":"藤田道路公園課長、青木都市開発課長","answer":"当然ながら、建物を建てたり、そういった活動の中で可能な範囲でのお願いになってきているというのが現状だと考えています。国や都へ、そういった制度を何とかつくれないかということで、私どものほうとしては要望しています。 どこにビルが建とうと、全地球的規模での取り組みということですので、ちょっと別の議論をいただく必要があることかと考えています。筋が違うことなのかなと思いますので、そういった点、十分にご配慮いただければと考えています。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"ヒートアイランド現象とは別の議論だとおっしゃったんですけれども、私がそれを理解する上で、ヒートアイランド現象とはどういう現象かと、区としては認識されているのか、ちょっとお伺いしていいか尋ねました。","respondent":"岩田まちづくり事業部長","answer":"単純にＣＯ２が増えるからこのビルをつくることはだめだということはできませんので、ＣＯ２が出ないような、例えば電気であれば。日進月歩でどんどん新しい技術革新が進んでまいりますので、行政としても、今後とも指導してまいります。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"せっかくこうやってつくっているわけですから、いろいろなあれが出てくると、真っ直ぐいかないという部分があると思うんです。ですから、いろいろな部署と共同しながら、ひとづくりはしていただきたい。","respondent":"松代管理工事課長","answer":"現在、関連するところが８課、３４事業ございました。連携を図ってよりよい形になるというような可能性が出てまいりましたので、今後の計画の中に、構想の中に盛り込んでいきたいと考えているところです。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問","question":"構想なので、実現しないと構想で終わってしまうということもあるわけですから、そこの中で幾つか聞きたいんです。区がある程度主導的に指導をして、こういう公開空地をつくってほしいみたいなことが可能なのか、可能じゃないのか。","respondent":"松代管理工事課長、青木都市開発課長","answer":"それをより継続させ、今後、十分に検討していきたいと考えています。そういった視点から、この構想の中では、いろいろな工夫、もしくはいろいろな検討を進めたいと考えているところです。 確かに、私ども、今まで、再開発等で、あるいは民間開発におきましても、公開空地等を設置する場合には指導してまいりました。ご意見を、ありがとうございました。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問","question":"もう一段お聞きをしたいのは、これの６番、ここは「子供や子孫のために」と書いてある。そこら辺の考え方をちょっと。","respondent":"松代管理工事課長","answer":"２点目の、子どもたちが参加する機会、まさにおっしゃるとおりだと思います。委員からお話があったように、そういった子どもたちの参加、かかわりといったものをうたい上げているようにしてまいりたいと思います。","id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"意見","question":"今おっしゃったところで、ほんとうに、教育の部分は、施設内と施設外を分けて考えていただいたほうがいいと思うので、そこだけお願いしたい。構想の中では、非常におもしろいのではないかなと思っているので、それはお願いをしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"浅野委員","kind":"質問・要望","question":"どうするのかとか、そういう管理項目というんですか、そういうものが多分必要ではないかなと思うんです。もし公表できる、そういうものがございましたら、教えてほしいと求めました。","respondent":"松代管理工事課長、藤田道路公園課長","answer":"そういった事業で、数値等をもう少し読み込んで、目標をもう一度定めることができれば、その中でも、きちんと検討をしたいと思っています。目標値を出しながら、それに向けて計画的に事業を進めると… 管理の主体は、今までどおり、私どもが主体的にやっていく。皆さんちょっとできませんよとお断りをするというのは、そういったことはできませんので、これからも進めてまいりたいと考えています。","id":"exchange-013"},{"speaker":"南委員","kind":"質問","question":"一定程度の検証というんですか、どういうふうな総括、伺いたいなと思うのが一つ。溝を浅く３０cmぐらい掘って、ごらんになったでしょうか、そういうテレビを見たんです。","respondent":"松代管理工事課長","answer":"少しでも触れられるようなものができないか、そういったものを、今後の課題として取り組んでいければと考えています。そういった意見がありましたので、今後、また検討する中で、海水の活用ができるのか検討してまいりたいと考えています。","id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"５００ｍメッシュで調査、具体的にそれぞれの検証状況がどうだったのかというのを、二の例を挙げて教えていただきたいなと思うんです。どういうものがあるのか、どういう効果があるのかの研究等々を専門機関と一緒にしていただければということで、よろしくお願いしたいと思います。","respondent":"松代管理工事課長、家壽田下水道河川課長","answer":"この辺のところが、今後の部分で、さらに充実させていく必要があるのかなと考えています。そういったものも広く、今後、考えていきたいと思っているところです。 その辺の技術的な検討、検証、実験等々を行っております。この辺もまた含めまして、そういった閉鎖性水域の改善などにつきましては、区としても努力してまいりたいと考えています。","id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"東京湾全体ですから、なかなか進まないのは事実ですから、思いとして持っております。そういうふうに思うので、今これからの新たな構想の段階だということで、その辺の見解も伺っておきたいなと思います。","respondent":"松代管理工事課長、岩田まちづくり事業部長","answer":"そこに主体となってやっていただく方々ときちんと会話をし、情報発信をし、先に事業を進めていこうというスタンスで考えております。したがいまして、それぞれにステージがちょっと違うような… 長期基本計画なり、実施計画などで、具体的な施策として落としていくということになります。それを集約して、行政として、こういう意見にはこう対応したという形でオープンにする。","id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"そういう感じ方をする人もいるんじゃないかなと思いますので、その辺がちょっと気になったので、質問させていただいたんです。その辺っていうのは、どういうふうに考えておけばいいんか尋ねました。","respondent":"岩田まちづくり事業部長","answer":"国民が自分たちが公園をつくったという認識というのはありませんから、都市においては、公園なんかのボランティアは極めて少ないです。そこの開発が行われるという具体的なものというのは、全然ありませんので、ご理解いただきたいと思います。","id":"exchange-017"},{"speaker":"須貝委員","kind":"質問","question":"その上にせせらぎというんですか、川の通路があるわけですから、考え方というのは可能なんでしょうか。それを、ちょっと説明を求めました。","respondent":"家壽田下水道河川課長","answer":"ただ、当区の立会川というのは、既に下水が３６５日流れておりますので、そのふたを外すということは、環境上、非常に難しい問題があると思います。区としても重要だと思いますので、都などとも連携しながら、可能なところからやっていきたいと思っています。","id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"都のほうも、いろいろ取り組みなり、構想なりはあると思うんですが、大体どのぐらいの年数がかかるという試算ぐらいはしているんでしょうか。もし概算でもあったら、説明を求めました。","respondent":"家壽田下水道河川課長","answer":"ですから、抜本的な改善というのは大変難しい状況にございまして、当区としましても、今年度、そういった実験・調査を予定しております。今、都に、早急に整備するように申し伝えているところです。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/823348?Template=document&Id=6346#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":37412,"voices":55}},{"id":"h19-20070730-6","meetingId":"h19-cm07","date":"2007年7月30日","dateIso":"2007-07-30","committee":"区民委員会","time":"午後１時０３分～午後４時０９分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を50件整理しています。","topics":[{"id":"topic-01","title":"の１番、報告事項","agenda":"の１番、報告事項","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"まず検討部会が６回、協議会が２回行われたということなんですが、主にどういう立場についている方が参加されているのか。自主運営というやり方というのは、これまで例があったのかということをお願いしますとの意見を述べました。","respondent":"中山地域活動課長","answer":"検討部会の構成ですが、公募委員の方ですので、特に事前の段階では何ら制限を設けることなく、熱心に参画していただける方を募集したものです。比較的フリーハンドな施設にしていくべきではないかということで、その辺をさらに追求していこうというふうに考えているものです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"区として管理責任者を置くつもりはないのかということと、そういう職員を配置してほしいというような意見というのは、検討会の中では挙がっていないのかということをお伺いしたいと思います。","respondent":"中山地域活動課長","answer":"今までの検討は、大体基本設計に至る部分がまとまりましたので、これからいよいよ運営のあり方についてご議論いただくという形になります。したがって、具体的な運営体制ということについては、この検討会の中で詰められている状況ではございませんけれども。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"必要なところは、やっぱり区のしっかりとした体制の援助、予算の援助というのも必要なのではないかということをお願いしたいと思います。最後に、この協議会と検討部会との関係というのはどういった関係、どういうリンクのされ方なんか尋ねました。","respondent":"中山地域活動課長","answer":"検討部会は、企画等について検討を行い、地区委員の会長等も含めた協議会で検討部会から挙げられた意見を確認していく。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"最終的には合同会議になりますということですが、合同会議というのはもう行われたんか尋ねました。","respondent":"中山地域活動課長","answer":"この６回、２回と書いておりますけれども、そのうち協議会が行われるときというのは、検討部会も実際に行われておりますので、２回は合同会議です。","id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"確認","question":"避難所機能、地域防災機能ということでちょっと確認をさせてもらいたいんですが、学校のときの避難所機能は、これは学校がもう移っているわけですね。ここはそういう、これからの避難体制の場所には考えていないということなんか尋ねました。","respondent":"久保田防災課長","answer":"こちらの説明の全体のところで若干触れていると思うんですけれども、地域防災機能の維持・強化というふうに位置づけております。旧原小学校が避難先であった町会は、引き続きここで避難していただくということで耐震補強をして、そういう形での準備をしていくという考えです。","id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"確認","question":"それから、そういういろいろな対応の中で難しそうな問題というのは、この辺の仕組みはできるのかどうかという点をちょっと確認をさせてください。防災備蓄倉庫なんかもあるので、かなり有効に使える部分になると思うんですけれども、その辺も含めて。","respondent":"久保田防災課長","answer":"全部で２,０００戸予定ですので、それから計算しますと、これまで原小学校のほうに避難する収容予定人数は７００人ですので。いざというときに対応していく、こういうような考え方で、検討しております。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問","question":"１,０００人ぐらいの枠があるということは、その辺もこれからここの活用が図れるのかなということを思ったので、その辺が１点。もう１点、平成２０年９月ごろにはこちらが開設できるということは、どっちが先に終わるという感じで行くんか尋ねました。","respondent":"久保田防災課長、中山地域活動課長","answer":"最初に帰宅困難者の対応のところでお答え申し上げますけれども、あるいは避難対策等をやっていただくというのが東京都の震災対策条例の基本です。一定程度の対応はしていただけると思いますけれども… 主校舎の福祉施設部分と地域交流の工事の発注ですけれども、これは別の工事の発注になります。調整はもちろんやってまいりますけれども、別の発注で、スケジュールも完成は別ということです。","id":"exchange-007"},{"speaker":"飯沼副委員長","kind":"質問","question":"３点お伺いしたいんですが、１つは、校庭の利用についていろいろかかわっていらした方がいらっしゃいますよね。強化されているというところで、こういった面での外部の侵入者に対するチェックとか、そういう面がどうされるのかをお聞きします。","respondent":"中山地域活動課長","answer":"可能なものについては聞いていくという形で対応していますが、難しいものは難しいということで、その段階でお答えをしております。建物については当然セキュリティーをかけてまいりますし、福祉施設の部分については、その施設の周りには一定のフェンス等ができるということです。","id":"exchange-008"},{"speaker":"飯沼副委員長","kind":"質問","question":"何かより緩やかな、いろいろな方の意見をたくさん入れて新しいものができるといいなと思いますので、その点をお願いしたいと思います。区切られることになるんか尋ねました。","respondent":"中山地域活動課長","answer":"ここで答えるのは難しいんですが、どこかで敷地境界を設けて、セキュリティーをかける部分とオープンの部分を分けるという作業が今後出てまいります。もう１つは、特に保育園機能の幼保一体施設の利用の形態が出てきた段階で、この辺の時間の調整についても図っていきます。","id":"exchange-009"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"今まで校庭だったから今までどおりに使わせてほしいという声も上がるだろうし、また、運営事業者が一応管理することになりますよね。だから、そういった面でかなりいろいろな面で難しいかとは思いますけれども、調整を十分にとっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"別紙２の２階の会議室というのは、主にどういう、地域センターの会議室とは違うんですか。どういう方が、どういうふうなことで利用できるのか尋ねました。","respondent":"中山地域活動課長","answer":"運用の部分については、現段階では白紙です。もう少しいろいろな講座中心になるのかというのは、これから地域のニーズを聞いたり、運営委員の意見を聞く中で決まっていくです。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"２番目の主催というところの品川区防災協議会各地区協議会という組織のメンバー等についてもう少し説明してください。教えていただきたいのと、どういった団体があるのかなというのを幾つか教えていただきたいのと、簡単にお伺いしたいのと。","respondent":"久保田防災課長","answer":"ケーブルテレビでの対応ですけれども、１０月１日からこの一般提供開始に当たって、一般家庭での配信のサービスというのを検討しているようです。そういうようなサービスをするように、今、ケーブルテレビ品川では検討しているというふうに聞いております。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問","question":"最後になりますけれども、１０月ですからＮＨＫでテレビでもアップしているという状況なんですが、それ以外に品川区で、その機器を取り付ければ、それ以上の詳しい情報が出るということなんか尋ねました。","respondent":"久保田防災課長","answer":"あるいはどんなものになるか、どの機器がどのぐらい活用できるのかできないのかというのは、今の段階ではちょっとお話はできません。","id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問","question":"緊急地震速報の件なんですが、これ、ＮＨＫの場合は無料ですか。区がつくったのではないからしようがないんだけれども、意味が伝わらないのではないかなという気がするんですけれども、その辺いかがか尋ねました。","respondent":"久保田防災課長","answer":"当然、あるいはそういう形の体制づくりというのも考えられるんですけれども、パニック防止をしていくかというのが大きな課題だと思っています。これは１回や２回ではなくて、自衛消防訓練とか、今後体制づくりをしていきたいというふうに考えております。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"意見","question":"確かに訓練しておかないと、わからないんじゃないかなと思ったのと、地区防災訓練にしても、職員防災訓練にしても、職員の方も、特に地区防災訓練なんて毎週続いていて大変だと思いますが、ぜひまたこれからもよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"稲川委員","kind":"質問","question":"この場所で質問すべきかどうかあれなんですが、そういった区の職員というのはどういった形でメンタル面というんですか、精神的な部分というのは考えているんか尋ねました。","respondent":"久保田防災課長","answer":"一応、災害対策本部従事免除というような規定を設けまして、一部そういう方たちを免除するという形にしてあります。５分の１ぐらいの方はそういう対象にはなっておりますけれども、従来、それぞれの配備されている業務の中に従事するということになってあります。","id":"exchange-016"},{"speaker":"飯沼副委員長","kind":"意見","question":"２点。伝える部分でどうなっているのかが１点と、その辺、昼間などに災害が起きたときの事業との連携がどの程度話し合われているのかお知らせくださいとの意見を述べました。","respondent":"久保田防災課長","answer":"地域と事業者、それから行政が一体となった三者連絡会議というものを大崎第１と、それから品川第２地区で設けております。その１つとして、今年の５月、６月に、帰宅困難者徒歩訓練というものを実施しました。","id":"exchange-017"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"若い人にたくさん参加していただきたいのになかなかという、あとやっぱり毎年やられているのは大事だけれども、パターン的にもうちょっと参加できない人のためにもいろいろ工夫した参加の仕方というのも考えていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"渡部委員","kind":"質問・要望","question":"原小学校の避難予定人員が７００人というお話がありましたが、これもいわゆる各地域における算出方法というのを教えていただきたいのと、大体何日ぐらい備蓄分が使えるかということをいま一度教えていただけないか尋ねました。","respondent":"久保田防災課長","answer":"ここのほうでその辺は全体として収容するというような考えで、今、進んでおります。３,０００食用意していますので、約２日分、これは４日から５日ぐらいは大丈夫かなというようなところです。","id":"exchange-019"},{"speaker":"川西委員長","kind":"質問","question":"よろしいですか。ちょっと済みません、私のほうから、このパンフレットの配布先について伺っておきたいと思います。","respondent":"久保田防災課長","answer":"これは当然お金がかかりますので、また補正なり何なりで計上したときにその辺はもう少し説明したいなと考えています。その放映を繰り返し放映するようなことも今後検討していきたいなというふうに、今、考えています。","id":"exchange-020"},{"speaker":"安藤委員","kind":"意見","question":"１点だけ、済みません。どんな感じだったのか、どういう活動なのか、もう少し説明を求めました。","respondent":"田村環境課長","answer":"それを体育館の中に展示して、売れた代金を寄附というか、そういう形をとろうということで実施しました。やはり今後取り組みをするときも、新たな試みをする場合には、やはりレイアウトも検討する必要があると考えています。","id":"exchange-021"},{"speaker":"安藤委員","kind":"意見","question":"環境バザーの環境というのは、そのバザーでの売り上げを環境に資するようなところに寄附するというので環境バザーなのか、それとも環境に関する品物を売るものであるのか、どちらになりますかとの意見を述べました。","respondent":"田村環境課長","answer":"そこまでは私のほうでは特に校長先生と話していませんで、それは大崎高校の判断でご利用いただくと、そういうような考え方です。","id":"exchange-022"},{"speaker":"稲川委員","kind":"質問","question":"もう１点が、ここにＥＣＯフェスティバル参加団体とあるんですが、この選定というか、これはどういう形で選ばれるんですか。お願いします。","respondent":"田村環境課長","answer":"考え方です。総合庁舎の２階の駐車場だとか、しながわ中央公園で環境についてのＰＲを引き続きやっていきたい、そのように思っております。","id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今日、ここで質疑して、事前審査にならないんですか。ちょっとそれが気になっていたんですけれども、どういうふうに考えれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"確認","question":"いや、どこまで言っていいかわからない。運営についてちょっと確認しているので、中身に入っていってしまうと、結構入っていってしまうのではないかなという気がするので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"では、ちょっと質問なんですが、３番目の改定内容というところで、これはちょっとわからなかったところで、1)と2)の関係というのは、素人目でわかりづらいので説明していただけますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"特に零細の方ですとか、料金の改定に対しての意見であるとかというのは、聞いておられるのでしょうか。実際、どこの部門というか、どういう事業者が増えているのか尋ねました。","respondent":"秋山資源循環推進課長","answer":"人件費が後ほどご説明いたしますけれども、それから、若干ずつ廃棄物の処理原価は減少していくというふうに聞いております。ですので、正確な事業系の量というのはわからないです。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"今回の改定で、ちょっと今、零細のところが特に厳しいと思います。まだ説明していない段階なので聞いていないかもしれないんですけれども、そういったところからのご意見というのは伺っているのか尋ねました。","respondent":"秋山資源循環推進課長","answer":"区収が今度、３２円５０銭になりますけれども、単価も一般の許可業者と契約することによって下げることもできるというふうに考えております。まだ区長会で決まっただけですので、ＰＲに関して今後行っていくですので、まだそのようなことは確かめておりません。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"あえて取り組むというのは、その考え方というのは、どういうことなんでしょう。どういうところにあるのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"質問","question":"それにどのようによい影響が出てくるというか、品川区の負担が減ってくるのかという点を教えてください。それからもう１点、先ほどの話まで出てしまうと、その辺は疑問があるんですけれども。","respondent":"秋山資源循環推進課長","answer":"品川区では、手数料の改定によって、全体で約３,６００万円の歳入が増というふうに試算をしております。ＰＲですけれども、条例改正からということに、正式には条例を改正をして、それに基づいてケアをしていくという形になるかと思います。","id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"意見","question":"逆に分担金のほうで行きますと、一部事務組合ということは、２３で割ってしまっていいのかな。それとも、１億円弱が分担金から減るというふうに単純に判断していいかどうか、その辺をとの意見を述べました。","respondent":"秋山資源循環推進課長","answer":"一組のほうの増収ですので、一組の歳入の中の増収部分ですから、分担金の部分が減るというふうになります。","id":"exchange-031"},{"speaker":"飯沼副委員長","kind":"質問","question":"１点だけ。副区長会に検討を下命する」とあるんですが、３定に条例を提出するというところの、この辺の流れが今後どうなるか説明を求めました。","respondent":"秋山資源循環推進課長","answer":"副区長会に検討を下命するということありますので、ここについてはこれから検討するという状況ですので、そういうことを決めているわけではございません。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"やっぱり今回の手数料改定というのは、区民にとってどういう影響があるかということを広く知らせた上で、ちょっと言い方がおかしいんじゃないかなと。正式に情報をお知らせして、晴れてＰＲしていくというふうな言い方が正確なのではないかなと思うんですが、そこら辺についてはいかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"３の(3)の3)のところに、具体的にどういうところから要請があって説明会をしたのかというのがわかれば教えていただきたいのと、あと。特に４番目の(4)のところに廃プラスチックの燃焼についての不安はやっぱり引き続きあると思いますし、あと、意見などなかったのか尋ねました。","respondent":"秋山資源循環推進課長","answer":"最初の行政による分別の説明ですが、これは主にマンション等の自治会や管理組合から要望をいただいているようで、６回実施しております。その中でご説明をしていますし、今年につきましては、廃プラスチックの燃焼についての不安というご意見は説明会の中ではあまり出ていなくて。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問","question":"そういう感覚的にこれを燃やしていいのだろうかというような声というのは、これだけきめ細かく説明している中では結構出ているのではないかなと思うんですけれども、いかがか尋ねました。","respondent":"秋山資源循環推進課長","answer":"このＡ３の用紙で行けば、そういう具体的なご意見が多くて、こういう燃やすことについてどうだというご意見のほうが少なかったように感じております。","id":"exchange-035"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その辺をもう１回お願いしたいのと、それから、どのぐらいこれによって資源の量が増えてくるのかなというのが、大体区の見込みを教えてください。平ボディというんですか、変化が出てくるのかどうか、その辺のご見解をお願いします。","respondent":"秋山資源循環推進課長","answer":"今後、プラスチック製の容器包装は、容器包装リサイクル法に基づいて容器包装リサイクル協会のほうに持っていく予定にしています。鋭意ご説明をして、これは分別率ですとか、正確なものを今現時点でということは難しいのかなというふうに考えております。","id":"exchange-036"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"先ほど月に１３トンから１４トンというお話だったのは、それはこのモデル地区の中で全部で１３トンから１４トンということだったんですか。その辺がちょっとよくわからなかったので、もう１回確認させてください。","respondent":"秋山資源循環推進課長","answer":"モデル収集で約１３トン、モデル収集の期間というか、モデル収集の１カ月に１３トンです。","id":"exchange-037"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"本当に環境に優しい方法でごみをゼロにしていくという方法を求められているのに、私はこのサーマルは基本的なところで逆行するなと思っているんです。ちょっとこのやり方でそうなるのかなとすごい疑問が出るんですけれども、その辺いかがか尋ねました。","respondent":"岩崎環境清掃事業部長、秋山資源循環推進課長","answer":"これは全く法的な制度がありませんから、技術的にも非常に困難なんですが、どうしていいかわからないというような状況です。今の段階では、その焼却しているものの中から資源化するものは… ルートですけれども、日本容器包装リサイクル協会を経由して再利用、再資源化ということであります。それから１軒１軒、これはなかなか他区にはない取り組みですので、今後も続けていきたいというふうに考えてあります。","id":"exchange-038"},{"speaker":"飯沼副委員長","kind":"意見","question":"集めたものをどういうふうに処理して再利用にするのかということの意見を述べました。","respondent":"秋山資源循環推進課長","answer":"集めたものは、容器包装リサイクル協会が入札を行って落札した業者が取りに来て、そこが再資源化するということになりますので、私どもがどこそこに持っていくということではない。","id":"exchange-039"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"私はせっかく掲げたからには、どうしたらここが進むのかなというところを１つ求めてほしいんですが、私はそこが不足していると思うんです。ぜひそこのところをお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"物をつくらないでほしいというのではなくて、ごみにならないような製品をつくるという努力を製造者がするというところをやっぱり追い求めているのが。やはりＣＯ２削減をお金がかかろうとも、追い求めなかったらどうするんだという段階に来ていると思うので、意見ですが言わせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"渡部委員","kind":"質問","question":"やはり西中１丁目のほうはモデル地区になったから、このごみは持って帰れないよ、そのようなことはないわけです。その辺はいかがか尋ねました。","respondent":"島袋品川区清掃事務所長","answer":"我々も一応原則は持って行きます。ただし、我々、ふれあい指導というものがありまして、専門の職員がシールを張って、指導をしていく、そういうことを徹底していきます。","id":"exchange-042"},{"speaker":"安藤委員","kind":"質問・要望","question":"というのは、大いにやっていただきたいと思うんですが、それとこれまでは不燃ごみとして出されていたものが可燃ごみになりました。燃やしたらどういう影響があるのかとか、１枚目のものでも、いかがか尋ねました。","respondent":"秋山資源循環推進課長","answer":"それから本年度も先ほどお話ししたような説明会を行ってご理解をいただいていけるというふうに考えております。今回、昨年来のかなりの回数の説明会や、今回のモデル地域への説明ということでかなりのご理解をいただいているというふうに考えております。","id":"exchange-043"},{"speaker":"安藤委員","kind":"質問・要望","question":"営利企業ということを含めて、これがやっぱり単純にＣＯ２がどんどん燃やすということなので増えると思うんですけれども、増えないでしょうか。増えないなら、なぜ増えないのか尋ねました。","respondent":"秋山資源循環推進課長","answer":"発電に伴うＣＯ２ですけれども、燃料がごみですので、通常の石油等々を燃料としたすＣＯ２と同じ計算ができるかです。正確な資料は持ち合わせていないんですけれども、ＣＯ２の発生ということについては、石油を使った火力発電所とは違うというふうに聞いています。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"ＣＯ２の削減目標を自治体が率先してクリアしていこうという時代に、そのことについては、どんなものなのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"安藤委員","kind":"質問","question":"ただ、発生抑制というのがまず第一次的に責任というか、ちょっとそこですごく矛盾があるのではないかなというふうに率直な印象としてあるんですね。そういった矛盾というところに関しては、そこら辺の必要性と矛盾の点に関してはどのような見解をお持ちなのかなということでお伺いしたいのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"ですから、ちょっとどういう事業をしているのか、わからないので、できたら資料をもう少し出して説明をしていただきたい。〔「ホームページをごらんください」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"ただ１枚ペラッとあっただけで、ほとんどわからないので、探しようがないんです。この株主総会は２名の方の株主参加ですか、きょうの資料の中で、もうちょっとこの設立の目的というのを明確に教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"飯沼副委員長","kind":"質問","question":"もう１点なんですが、最後の資料のところの運転管理受託工場数が３年目で黒字になったと、５、６と増えていますよね。売電の量を増やしていくという、そういう方向性を持っているのかどうか、その点についてお伺いしたい。","respondent":"秋山資源循環推進課長","answer":"この受託工場数については、運転管理事業の受託ですので、工場の運転を行う実際の運転作業員ですとか、工場の運転をすることを委託する事業ですので、これは売電の数、売電する工場の数とは違います。","id":"exchange-049"}]},{"id":"topic-02","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"稲川委員","kind":"質問","question":"どうでもいいことなんですけれども、これはマイクロバスで行くんですか。電車か尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/598842?Template=document&Id=2492#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":52779,"voices":192}},{"id":"h19-20070730-7","meetingId":"h19-cm07","date":"2007年7月30日","dateIso":"2007-07-30","committee":"厚生委員会","time":"午後１時０２分～午後３時３６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"委託先が協議会というお話なんですけども、常設的につくられて、どのくらいのスペースでもっていくのか。常時これだけのメンバーが出たり入ったりという形になると、どのくらいの時間帯でどういうふうにもっていくのか説明を求めました。","respondent":"諸岡児童課長","answer":"予定をしておりますのは２名体制でございまして、電話等による受け付け、また依頼する会員の面談を行います。したがいまして、事務所スペースということでそう広いスペースは必要としていないと考えています。","id":"exchange-001"},{"speaker":"須藤委員","kind":"質問・要望","question":"そのあたりは一緒に使うようになるのか、そのあたりのトイレのありようをどういうふうにお考えになっているのか、教えてほしいと求めました。この辺もこういうメンバーをある程度想定していますというようなお考えで、この数と広さを考えられてきているのか、そのあたりを説明を求めました。","respondent":"蓼沼高齢福祉課長、小林保育課長","answer":"この２階、運営事業者のほうでこれまでの施設運営の実績から考えて、この時点では１基で機能できるのではないかということでの内容です。さらに、Ｃタイプについては数としては１というカウントになっておりますけれども… １００名の標準的な施設の場合、トイレについてはこちらで充足していけるかと考えております。ちょっと見づらくて恐縮なんですけど、職員便所ということで２個、別途の設置となっております。","id":"exchange-002"},{"speaker":"須藤委員","kind":"質問","question":"２階だけ、３階だけということでなくて、かなり車いすだとかそういう人たちが多くなってくると混雑する。エレベーターでも寝台用ですから、４回往復したりすればいいと思うんだけど、その辺ももしご配慮してもらえればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１つは、高優賃のほうは全部何平米というのが出ているんですけど、保育園のほうの遊戯室、それから０・１歳から５歳児までの部屋のスペースが書かれていないので、部屋のスペースを教えてほしいと求めました。","respondent":"小林保育課長","answer":"現在、こちらはご提案いただいている内容を精査しているところで、それぞれの定数についてはまだ協定前で確定してございませんが、いずれにいたしましても、この１００名の規模からいうと施設的には十分な面積が確保できてあります。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回、そのケアハウス制度と高優賃とではどう違うのか、入居対象の方は要介護どれくらいを考えているのかということについてお聞きしたいと思います。とりあえず、そこのところだけお願いします。","respondent":"蓼沼高齢福祉課長","answer":"数がここに予定をしております４０、３階フロアに整備することで戸数がより多く確保できるということ、高優賃制度を活用したものです。基本的には中度、重度の方が中心になると考えておりますが、さらにその対象者像については検討してまいりたいと考えています。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこら辺のところを１つ教えていただきたい。それの１割負担と食費ということになるのか、そこら辺の本人の負担がどういうふうになっていくのかということについて教えてほしいと求めました。","respondent":"蓼沼高齢福祉課長","answer":"今回、そういった利用の実態を見ながら、場合によってはＢタイプのほうの可能性についても検討していくことが必要かと考えております。ですから、単純に西五反田と比較はできないわけですけれども、そのご本人の負担については介護保険制度を使えますので１割負担。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本人の利用料負担なんですが、そこら辺のところについてもう１回お聞きしたいのと、西五反田よりもかなり低廉なということになってくるんでしょうか。この高優賃の制度を見ていたら、家賃の減額に要する費用の助成というところがあったんですけど、そのことについてもお聞かせほしいと求めました。","respondent":"蓼沼高齢福祉課長","answer":"で、都南病院もそうなんですけども、利用料については極力西五反田よりも低廉な料金ということを１つの目標にして検討しています。これは収入に応じて最大２万５,６００円だったと思いますけれども、そういうものもこの原小では当然活用しながら、利用料の設定をしていくです。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１０万円後半から２０万円というのは、食費と特定施設の１割も含めた、全部ひっくるめた額ということでいいんでしょうか。こういうのができるというのはどこにどういうふうに定めてあるのかということと、それと、そのことについても教えてほしいと求めました。","respondent":"蓼沼高齢福祉課長","answer":"運営事業者と双方でなるべく低廉な価格にならないかということで、今現在、鋭意検討している状況です。このたび運営事業者に決定いたしました社会福祉法人こうほうえんでは高優賃を特定施設として活用している施設を持っていると聞いております。","id":"exchange-008"},{"speaker":"本間委員","kind":"質問","question":"一部見ますと、小さな庭というような部分がありますし、屋上の部分が１階、２階にあるようですが、これはどうなっているのか。と同時に、校庭の部分の整備は、その辺は手をつけるのかつけないのか、整備するのかしないのかという点を、簡単で結構ですから説明を求めました。","respondent":"蓼沼高齢福祉課長","answer":"緑化につきましては、今後どのような取り組みができるのかは引き続き検討してまいりたいと思います。これについては地域の方々もさまざま解放してほしいということもありますので、この校庭の活用については今いろいろ検討しています。","id":"exchange-009"},{"speaker":"堺委員","kind":"質問・要望","question":"狭い道路ですから、特に車の出入り口、それから何台ぐらいを想定しているのか。３点目に避難路の件についてちょっと教えていただきたいのが、要するに、ここへ行くまでの避難通路というのはどこを使うんか尋ねました。","respondent":"蓼沼高齢福祉課長、小林保育課長","answer":"３階が整備できないということが、いろいろ検討する中で、これは増築であるということがありました。そういうことで、このベランダ、その外の床を通ってこの避難階段のほうに避難をしていくというのが避難のルートになるものです。ちょうどその反対側、左手なんですが、ステージの下と書いてあるところにもう１つ通路が確保される予定です。","id":"exchange-010"},{"speaker":"堺委員","kind":"質問","question":"入り口を利用者の人にわかりやすい案内ですか、例えば西大井の駅あたりからになるんでしょうか、なかなかわかりにくいかなという気がしますので。車いすをご利用される方も想定されている施設ですから、そういう人たちについてはどういう形、それについては何か想定していることはありますか。","respondent":"蓼沼高齢福祉課長","answer":"それは人と、あとはそういうエレベーターという道具を使って、あるいは人力で避難階段を使ってというような形ではないかと考えているところです。","id":"exchange-011"},{"speaker":"堺委員","kind":"確認","question":"今後の予定の中で平成２１年の２月に開設となっておりますが、シルバーセンター、すべてがこの２月から稼働開始という理解をしていいんでしょうか。ここで２月に保育園が開設されるとすると、若干どういう形で動いていくのか、その辺がちょっと気になったもので、教えていただけますか。","respondent":"小林保育課長","answer":"準備期間によっては２月の中旬、３月入所というようなタイミングは別途検討させていただきたいと思いますけれども、基本的には開設と同時に施設を運営していただくという予定で事業者と打ち合わせをしてまいりたいと考えています。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今まで、特別養護老人ホームだと介護報酬の中で３対１の体制しかとれないと、もっと手厚い人員配置をというご答弁でした。そこら辺の仕組みはどうなのかについてお聞かせほしいと求めました。","respondent":"蓼沼高齢福祉課長","answer":"ですから、そういった形で家賃は設定いたします。１.８とか１.９とか１.７とか、それは当然人件費がかかるわけですので、それらについてはやはり一定程度の利用者の負担の中に入ってくるです。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうすると、さっき言った特定施設の介護報酬の１割負担プラス食費プラス家賃プラスその上乗せ介護という形になっていくんでしょうか。その家賃の中に上乗せ介護費というのも含んだ形で家賃の設定というのができるのか、そこら辺のところについて教えてほしいと求めました。","respondent":"木下福祉高齢事業部長","answer":"もう１つが、いわゆる生活支援費ということで、日常の相談とか食事サービスとか。例えば２対１とか、１.８対１とかというようなものを体制をとって賄っていく、そういう柔軟性がある制度だと受けとめていただければと考えています。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"たしか、特別養護老人ホームだと大体減免制度がなければ食費が１カ月４万８,０００円くらいだと思うんですが、では、それにそういう上乗せ介護費もプラスされた形で、生活支援費ということで、食費を上回る形での利用料になっていくんか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"生活支援サービスという中に食事があって、それが月当たり５万円とか、そのほかに日常的な支援というのがありますね。その中で職員体制としては、例えば２対１とか１.８とかいうことを考え、シュミレーションして組み立てていくということであります。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それに食費が５万円、家賃そのものは約１０万円いかないくらいの、そんなような形で考えていいんでしょうか。そこが１つと、改めて幾らになるのかも教えてほしいと求めました。","respondent":"蓼沼高齢福祉課長","answer":"それから、家賃が１０万円を切るのかどうかというお尋ねです。その辺は利用料の設定にもかかわってくることですので、今、種々検討しています。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それで、こうほうえんが都道府県知事にもう認定の申請を出して認可をされているということでいいんでしょうか。認可されたのはいつぐらいかということを最後にお聞きしたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"今、供給計画を策定していますけれども、その後、申請の手続をするということで、この秋ぐらいには認定されるスケジュールで事業を進めております。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"事業主体はこうほうえんになりますけれども、この供給計画は区と一緒につくっているということでいいんか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"供給計画についてはご指摘のとおり、区と運営事業者で作成をしています。","id":"exchange-018"},{"speaker":"宮崎副委員長","kind":"意見","question":"今の家賃、いわゆる建設費というのはかなり安くなってくるので、どういうふうに家賃を決めていくのかというのがいま一つよくわからない。そこのところはどういうふうになるんでしょうとの意見を述べました。","respondent":"蓼沼高齢福祉課長","answer":"家賃設定の仕方は、今、委員のご指摘がありました近傍家賃と、それから建設費を勘案して家賃を設定するということになっております。","id":"exchange-019"},{"speaker":"宮崎副委員長","kind":"質問","question":"両方を勘案してということなんですが、やっぱりどっちにシフトして考えるのかということで、全然家賃が変わってくるのではないかと思うんですよね。ですから、そこの考え方を聞いているんですけど。","respondent":"蓼沼高齢福祉課長","answer":"それと、建設費については、例えば西五反田と比較すれば、新築と改修ですから、それは改修のほうが低くおさまるものです。これについてどちらにウエイトを置くのか置かないのかというところは、それは総合的に検討して定めるべきものではないかと考えています。","id":"exchange-020"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"これはやっぱり１円でも安く、それに応じた家賃にしていただきたいということを強く要望しておきたいと思います。シルバーセンターの運営もこうほうえんに委託するということは、何でこういうふうになるんか尋ねました。","respondent":"冨岡高齢事業課長","answer":"シルバーセンターの運営につきましては、やはり一体的な運営ということで、今回、民設民営という形をとらせていただきます。さらに団塊の世代をにらんだ運営の仕方とか、付加価値をつけまして運営をしていただくという目的を持ちまして、民営で運営をしていただきます。","id":"exchange-021"},{"speaker":"宮崎副委員長","kind":"意見","question":"は、シルバーセンターも目的外の使用なんかもいろいろあったんですけど、そういうところはどうなるのか。ちょっとこれだけだとイメージがよくわからないんですけど、説明をお願いしたいと思いますとの意見を述べました。","respondent":"冨岡高齢事業課長","answer":"西大井で実施していた事業、それから利用者の方に対しては、そのままご利用いただくのが基本です。そういう形でさらに付加価値をつけるという形で、民間の力を活かして柔軟な対応ができるようになればと考えています。","id":"exchange-022"},{"speaker":"宮崎副委員長","kind":"質問","question":"それと、先ほどの質問のところで、そこら辺の現実的な見通しというのはどういうふうにされているのか。今時点でわかっていればお願いしたいと思います。","respondent":"小林保育課長","answer":"通常の朝７時半から６時半までの基本保育のほかに、また、創意工夫の中で地域との交流等もご提案いただければという思いでお願いをしています。","id":"exchange-023"},{"speaker":"宮崎副委員長","kind":"質問","question":"定員のところは一応１００名となっているんですけど、大体年長になるにつれて需要が少なくなっていくと思うんですけども、大体０歳とか１歳とか、そこら辺のところはすぐに埋まると思うんですけど、そこら辺の募集の仕方というのはどういうふうな感じで考えていくようになるんか尋ねました。","respondent":"小林保育課長","answer":"各年齢の傾向につきましては、今お話のあったとおりです。特に、０・１・２・３歳に若干名の待機児等も存在していますので、それで周辺で入園を希望される方のご応募をお待ちするという想定をしています。","id":"exchange-024"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"宮崎副委員長","kind":"質問","question":"ゆたかシルバーセンターの開設が昭和３３年ですよね。そういう声もあるんですけど、施設について大体均等にしてこうだとか、そういう考え方というのは何かあるんか尋ねました。","respondent":"冨岡高齢事業課長","answer":"それで新たにつける場合には状況の変化といいますか、やはり営業等を脅かさないような状況が必要ということが１点あります。新たにこちらのほうで設置をいたしますと、それについては慎重にしたい、難しいだろうと考えています。","id":"exchange-025"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"特にちょっと体が弱ってきた場合、１人でなかなか風呂に行けない。とりあえず、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"須藤委員","kind":"質問・要望","question":"ですから、このあたりの数の変化というのはどういうふうにとらえていっていいのかなということ。そんなことをお考えがあったら理事者のほうからお聞きしたいし、また、せっかくですから各委員の中で今お話ししたようなことをどう考えているか。","respondent":"蓼沼高齢福祉課長、冨岡高齢事業課長","answer":"それを換金して介護保険料に充てることを可とするという方針が示されまして、ポイントシステムについては今、庁内で検討しています。将来ご自分、原形のようなものがさわやかサービスでありまして… では、これからどうしていったらいいのかということになると、まだこれは検討しなければいけない課題だと考えています。","id":"exchange-027"},{"speaker":"須藤委員","kind":"質問","question":"ですから、なかなか入れません、２年も３年も待っています」というような話が片方である。そういったときの方向性をつくってあげなきゃいけないと思うんだけども、いかがか尋ねました。","respondent":"木下福祉高齢事業部長、松澤委員長","answer":"したがって、その一人称から三人称の両方とも大事で、そういうつながりができるような支援を区として考えていく必要があるだろうと考えています。それは地域の中で活かされてくると考えていますので… 他にないようですので、本件を終了いたします。シルバーセンターなど実際の施設や現場の視察を行い、元気高齢者に対する支援について、より具体的に調査をしていきたいと考えております。","id":"exchange-028"}]},{"id":"topic-03","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"今までの厚生委員会の視察では、３日間の日程で、本当にハードな日程を組んで、５箇所程度の視察があったように思うけれども、この案だと、視察項目が少ないような気がするけれども、これは、移動に時間がかかるということか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"須藤委員","kind":"質問","question":"今回についてもせっかく行くのだから、時刻表を見なければわからないんだけど、できればもっと回ることはできないかと。それを信頼しているから、そこへ行くような話になってくるんだろうと思うんだけど、そこをまず見たいということからスタートされたわけか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私もそのこうほうえんがどういう事業所なのかというところはぜひ見たいというのが１つはあるんですけども、この中にそれは入っているんでしょうか。特に遠いところまで行かなくてはなかなか大変だということであれば、私は１泊２日ということもあり得るのではないかと思うんですけど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"須藤委員","kind":"質問","question":"先様のご都合もある。正副に申し出て、「もう少しこのあたりにこういう情報が入ってきたけどどうですか」というようなものを、日程的にはこの日程でいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/928192?Template=document&Id=3178#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":35804,"voices":91}},{"id":"h19-20070730-9","meetingId":"h19-cm07","date":"2007年7月30日","dateIso":"2007-07-30","committee":"文教委員会","time":"午後１時０２分～午後３時２４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を45件整理しています。","topics":[{"id":"topic-01","title":"校舎改築事業の進捗状況","agenda":"校舎改築事業の進捗状況","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"そこに幼稚園機能を入れるというんじゃなくて、これを見るとゼロ歳からになっていますので、認定こども園、どういうイメージなんでしょうか。そういうものを小中一貫教育の中に組み入れてきた背景というんですか、どういう経過で、どういう検討があって。","respondent":"市川庶務課長","answer":"したがいまして、今回の荏原西地区の小中一貫校の開設にあたりましては、基本的には平塚幼稚園も移設をするという考え方が１つございました。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"子どもを育てる施設をつくってほしいという要求は一般的にはありますけれども、その辺もちょっと説明していただきたいと思うんです。施設の配置だとか、その辺がどういうふうに配慮されているのかというのがいま一つわからないので、そこも説明を求めました。","respondent":"市川庶務課長","answer":"１点目のご質問で、しかるべきタイミングで所管委員会で説明があろうかと思いますので、これの結論をいただいて設計を進めてあります。こういうことについては所管の部局の職員から意見を聴取したものを設計の中に反映していると考えています。","id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"この地域はたしか今年の１月、２月ごろに突然、この幼保一体型のものを入れた計画になっていくという説明はされてきているんか尋ねました。","respondent":"市川庶務課長","answer":"各地の説明会の中で、児童保健事業部の職員が同席した上で説明をしてきております。","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"今の説明は、その幼保一体型を入れるという説明をしているという意味ですか。前任の文教委員にも確認しましたけれども、学校関係者に説明されたのか、平塚中学校と荏原第二中学校一体の施設をつくるという点ですから。","respondent":"市川庶務課長","answer":"時期的に少しずれましたけれども、今日が最初のタイミングと考えて、ほかの案件と一緒に報告をさせていただいているです。昨年の２月ですか、プレス発表時にこれはもう公にしていますので、何もこの時期になっていきなりこの話を持ち出しているわけではございません。","id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"当然、どうしても制服を着用させるという点では出てくると思いますので、ちょっとその辺のこともつかんでおられる内容について伺いたいです。それから３点目については、その結果がどういうふうになっているのかをこの場でつかんでいたら教えていただきたい。","respondent":"市川庶務課長、藤森小中一貫教育担当課長","answer":"１点目のご質問の工事の概算費用ですけれども、おおむね２１億、２２億円、このあたりを今、見込んです。先ほどの説明の中でも触れましたが、増築だけではなくて設備更新を行いますので、少し変動要因があると見てあります。２点目の費用ですけれども、これも標準服検討委員会で検討していることですけれども、２万５,０００円前後ぐらいという話を聞いているところです。","id":"exchange-005"},{"speaker":"南委員","kind":"確認","question":"通学路というんですか、この図面を見ると、これは今までの指導もこういうことだったということで行っているのかどうかを確認したいのと。どういうふうに考えておられるのか、それを伺いたいし、その辺も伺っておきたいと思います。","respondent":"市川庶務課長、古里学務課長","answer":"背の低いものでもいいのでフェンスを設けてほしいという声が相当数ありますので、それを受けたような考え方を今、お示ししています。子どもたちの動線もいきなり校庭に入るのではなくて… 支援ですけれども、行われている支援については就学援助というものがありますけれども、小学校段階では制服代というのは特に就学援助の規定の中ではございません。","id":"exchange-006"},{"speaker":"南委員","kind":"質問","question":"ないわけですから、その部分をどういうふうに考えるのかという質問をしているんですけれども。","respondent":"古里学務課長","answer":"標準服という規定ですので、特段強制にわたるようなものではございませんので、今の段階で就学援助の規定を変更するというつもりはございません。","id":"exchange-007"},{"speaker":"南委員","kind":"質問","question":"中学校がここしかなくなるわけですから、よその学校は遠くて選ばせたくない、非常に経済的に厳しいという家庭の方もいらっしゃると思うんです。その辺への配慮、考慮、そういうものは考えないということなんか尋ねました。","respondent":"古里学務課長","answer":"今申し上げたとおり、就学援助の規定の中で運用していますので、その規定を今の段階で就学援助費用の拡大ということについては考えていないです。","id":"exchange-008"},{"speaker":"南委員","kind":"質問","question":"それは子どもにとって、もうはっきり差別化になっちゃうと思うんですけれども、そうすると教育的配慮というのはどういうふうに考えているんか尋ねました。","respondent":"藤森小中一貫教育担当課長","answer":"着せないというのは保護者のご判断で対応していただいているという状況がありますので、着ている、さまざまご心配な点があろうかと思います。そういった一般的に子どもたちの悩みというのは十分対応していく、今、個々の先生方で十分ご検討いただいているという状況です。","id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"先ほどアンケートの結果についてどういうことをつかんでおられるか質問したんですけれども、ないので、改めて答弁していただきたいんですけれども。経済的な支援をちゃんと図るというふうにしていかなきゃいけないと思うんですけれども、最後にその点の答弁を聞いて終わりたいと思います。","respondent":"藤森小中一貫教育担当課長","answer":"経済的な支援ということではないですけれども、そういうようなことについては教育委員会ではできるだけのことは支援をしていきたいと考えています。","id":"exchange-010"},{"speaker":"山内委員","kind":"質問","question":"本日は校舎改築事業の進捗状況について今、話をしているので、その点について質問します。先ほど八潮地区の小中一貫校は２１億か２２億円の費用ということを伺いましたが、それから第三日野小学校の改築工事にかかる費用を説明を求めました。","respondent":"市川庶務課長","answer":"次に第一日野小学校、五反田文化センター等の工事につきましては４３億円程度、第三日野小学校の改築につきましては２９億円程度と見込んです。これは地中工事というか、擁壁工事、がけと校庭の関係がちょっとはっきりしないところがございまして、高目に見込んです。","id":"exchange-011"},{"speaker":"山内委員","kind":"質問・要望","question":"それともう１点、ほかの小学校のグラウンドのところにはトラックの真ん中に直線がありますよね。例えば第一日野小学校は６０ｍで、第三日野小学校は５０ｍ、これをまず荏原西地区では直線で何ｍぐらいになるか教えていただきたい。","respondent":"市川庶務課長","answer":"このお示しした図面の端から端までが１００ｍです。走り切ると、１００ｍ走で使えるか使えないかというのは非常に微妙で、この直線の端から端までがおよそ１００ｍということでとってあります。","id":"exchange-012"},{"speaker":"山内委員","kind":"質問","question":"もう１点、それでそこにアリーナをつくり、その上に屋上プールをつくるというつくりになっていますよね。その辺のそういうメンテが非常にこれはかかるのではないのかなということが予想されるんですが、それについてはどうなんか尋ねました。","respondent":"市川庶務課長","answer":"これは３面が地中なんですが、１面というんですか、これは全く四辺がすっぽり地中におさまるよりは条件がいいと考えています。がけの擁壁を持っているわけですが、この部分がかなり費用的にはちょっとかさんでしまうのではないかと危惧している、そういう説明です。","id":"exchange-013"},{"speaker":"山内委員","kind":"質問","question":"先ほど第一日野小学校のところで、１年生から６年生まで１５クラスを考えているところというのはどういう形で考えているんか尋ねました。","respondent":"市川庶務課長","answer":"６学年で１５クラスというのは、改築いたしました台場小学校の想定クラスを考えたときに、いわゆるクラスが増えたときの対策は講じてあります。","id":"exchange-014"},{"speaker":"山内委員","kind":"意見","question":"必ず部屋を確保しておくということで、例えば、遊んでというのは変なんですけれども、そういう教室というか、それができちゃうということが想定されるんですが、そういうときというのは何か、例えばこういう多目的で使いましょうとか、そういう考えというのはありますかとの意見を述べました。","respondent":"市川庶務課長","answer":"２つ考え方がございまして、１つは最初から部屋をつくっておく、そういうものに応じた部屋として使っていくということが１つあります。それからもう１つの考え方は、今のような２つの考え方で一応、予備教室というのは考えてあります。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問・要望","question":"６カ所にできるわけですから、かなりいい施設になるのではないかなというお考えはないのかどうか、荏原西地区が２クラスなんですよね。今後１クラスの人数ですね、これがどうなるかわからないということですが、その考え方はいかがか尋ねました。","respondent":"市川庶務課長","answer":"６校構想をまず実施いたしまして、これの検討結果も踏まえて、その上で改築計画ということを定めていく必要があるという認識を持ってあります。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問・要望","question":"今後、改築する際に地域のバランスを見て、地域開放という観点も含めて考え方に入れていただきたいなというふうに要望しておきます。品川区の出さなきゃいけないというんですか、していくというものなのか、予算立てのことについて教えていただけますか。","respondent":"市川庶務課長","answer":"なおかつ５０年に１度改築をするという前提で、いただいているという言い方はあれですけれども、配分を受けているわけです。その差を普通に考えれば、この部分をこれから計画的にどういうふうに積み上げていくのか、こういう課題があると認識しております。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問・要望","question":"いい校舎で、新しい校舎でというのは、子どもたちの教育環境としては向上すると思います。これは全体的な品川区の財政をどういうふうにしていくかという話になりますので、教育委員会だけがいろいろ考えて、要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"石田（慎）委員","kind":"質問","question":"４点ほどお伺いしたいんですが、２点目が、そんな中での防犯対策等というのはしっかりと考えられているのかということを。もう１つは、そういう動き等というのはあるのかという４点をお聞きしたいんですが、。","respondent":"市川庶務課長","answer":"ほぼ１学年３クラスの、いわゆる学区域内の就学人口が見込めるということから、単独の小学校として改築をいたします。品川区が進めてあります小中一貫教育、先ほどご質問いただいたときにお答えしましたけれども、設計ということも視野に入れているところです。","id":"exchange-019"},{"speaker":"金野委員","kind":"意見","question":"各学校の校庭の土なんですが、今、巻き上がらないようにスプリンクラーとかをつけているんですが、この改築にあたっての校庭の土等はどういうものにとの意見を述べました。","respondent":"市川庶務課長","answer":"普通の土を入れると周辺の近隣対策という面でちょっと耐えられないということで人工芝を採用したということです。そこの難しさはあるんですが、基本的にはほこりの立ちにくい土を採用していくということ、これを基本にしています。","id":"exchange-020"},{"speaker":"市川委員","kind":"質問","question":"第三日野小学校の少人数学習という部屋がありますね。第三日野小学校の場合はこの部屋がすまいるスクールの部屋というふうなことなんか尋ねました。","respondent":"市川庶務課長","answer":"すまいるスクールの配置につきましては、極力低学年の指導に向いた場所ということで調整をしています。現在、この部屋割りの中には示してございませんが、今、いろいろな部屋同士の調整の中で検討を進めているところです。","id":"exchange-021"},{"speaker":"南委員","kind":"質問・要望","question":"非常階段のことを伺いたいんですけれども、非常時の関係で、改めて非常階段がどういうふうになっているのかを説明してほしいと求めました。そういう非常時にどうなのかなとちょっと心配になるので、どういうふうな検討をされてそこはクリアされたのか、そこを教えてほしいと求めました。","respondent":"市川庶務課長","answer":"今の学校、外から逃げるという考え方をとっておりますけれども、今の建物は中の階段を確保して避難にあたるという考え方をとっているのが通常です。そこのところから避難をするという考え方です。","id":"exchange-022"},{"speaker":"南委員","kind":"質問","question":"図面上で教えてもらいたいんですけれども、階段の外にあるこれじゃないですよね。第一日野小学校で言うと３階に外階段みたいな箇所があるんですけれども、内階段だから。","respondent":"市川庶務課長","answer":"検討中だということで申し上げたんですが、セキュリティーの問題、生活通路の問題という２面の問題があります。今、考え方を整理している、こういう状況です。","id":"exchange-023"},{"speaker":"南委員","kind":"確認","question":"その辺の確認をしたくて伺ったわけですけれども、こういう耐震構造の建物ですから、それの確認をしたんですけれども。そういうことを含んで設定していくわけですけれども、そういうことになるのかなというのがちょっと１つ確認したくて質問したんですけれども。","respondent":"市川庶務課長","answer":"したがって、かつての避難訓練の様子とは全然違うパターンになっていますので、そういう趣旨で先ほど説明させていただいたわけです。給食の実施段階、給食の実施段階では調理代行に委託ということで、こういう予定です。","id":"exchange-024"}]},{"id":"topic-02","title":"荏原第二中学校と平塚中学校の統合","agenda":"荏原第二中学校と平塚中学校の統合","exchanges":[{"speaker":"西本委員","kind":"質問","question":"それなりの意味が、深い意味を私は感じてはいるんですが、教育委員会としてどういうふうな使い方をしているんでしょうか。その意味も含めてお伺いさせてください。","respondent":"古里学務課長","answer":"そういうふうな形で考えていて、学校の設置条例の変更については、検討中です。統合という形の言葉遣いに統一をしてまいりしたいと、少なくとも学務課での説明はそのような言葉にしてまいりたいと考えています。","id":"exchange-025"},{"speaker":"西本委員","kind":"質問・要望","question":"今までもずっと統合という言葉を使って進めてきたと私は認識しております。統合ですから、品川区の学校をどういうふうにつくっていくか、方針を確認させてほしいと求めました。","respondent":"古里学務課長","answer":"八潮ももちろん同じようなことでやっておりますから、そのような考え方はこれからもきちんと堅持をしてやってまいりたいと考えています。そういうことが発生した場合は、このような形で進めてまいりたいと考えています。","id":"exchange-026"},{"speaker":"南委員","kind":"質問","question":"ですからそれぞれの学校のよさを生かすって当たり前のことなんですけれども、そういうことに至るまでの経過、そこが大事だと思うんです。ですから改めてですけれども、特徴的で結構ですから、その辺を改めて報告を伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"南委員","kind":"質問","question":"同じだから質問できないんですか。委員長に伺いたいんですけれども、同じ質問はしちゃいけないんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"南委員","kind":"質問","question":"前回も質問を確かにしましたけれども、特徴的に父母がどういう意見を出していたかというところが具体的にはなかったです。答弁してください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"南委員","kind":"質問","question":"私は違うことを聞いているんですから、答弁してもらうように促してください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"南委員","kind":"質問","question":"ストップじゃないですか。前回聞いたことをまた繰り返して聞いちゃいけないという制限なんかないじゃないか尋ねました。","respondent":"古里学務課長","answer":"保護者からのいろいろな質問、特徴的な質問ですけれども、新しい学校に対する不安ということが非常に多かったと聞いております。今、先ほど申し上げたとおり、新しい学校づくりについて皆さんがいろいろ話し合いをしながら準備を始めているです。","id":"exchange-031"},{"speaker":"南委員","kind":"質問・要望","question":"１回聞いたから聞いちゃいけないとか、そういうふうに言うというのは委員長としてやっていただきたくないと思うし、やるべきじゃないと思うんです。やりとりの中ではそういうことを聞くことだって必要な場面だってあるわけですから、質問させていただけるように計らってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"南委員","kind":"質問","question":"そうでしたら、委員長のほうでそういうふうにおっしゃる必要はないんじゃないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"南委員","kind":"質問","question":"それを委員長がご自分のご判断で質問を遮る、答弁する必要はないんじゃないかみたいに言うというのは、私はそれはやり過ぎだと思います。発言セーブだと思いますから、そういう運営はしていただきたくないと思って申し上げました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"南委員","kind":"意見","question":"委員長として検討してください。そういう運営をしていいのかどうかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"}]},{"id":"topic-03","title":"戸越体育館の改修工事","agenda":"戸越体育館の改修工事","exchanges":[{"speaker":"西本委員","kind":"質問","question":"これをどういうふうにされているのかというのが１つと、多分無理だと思いますが、もう少しスペースがあるといいなとか思っているんです。これは今回、工事する予定とかはないんか尋ねました。","respondent":"富田生涯学習課長","answer":"１点目の現在の利用団体についてですが、これから当該施設等々体育館の利用者に対して、掲示等でお知らせをしていくことになってまいります。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"フォローしていただきたいなと、かなり調整しながら体育館を使っていただいているという現状がありますので、その辺も今後教えてほしいと求めました。","respondent":"富田生涯学習課長","answer":"そういった各団体からのご相談につきましては、学校施設の利用の仕方についてご案内をしていくようにしてまいりたいと思います。","id":"exchange-037"},{"speaker":"南委員","kind":"質問","question":"４カ月前に申し込みができるので１２月からという設定かと伺ったんですけれども、伺っていたんですけれども、その辺というのはどうなんか尋ねました。","respondent":"富田生涯学習課長","answer":"１１月あたりまでに展開されるということになりますので、そういう意味では、比較的冬場というのは利用がそういった季節に比べれば少ない時期という状況でこの時期になったということもあります。","id":"exchange-038"},{"speaker":"南委員","kind":"質問","question":"１年に１回ぐらいしか利用実績を聞かないのでよくわからないですけれども、新設というふうな理解なんでしょうか。これは必要かなと思うんですけれども。","respondent":"富田生涯学習課長","answer":"現在もエレベーターはありますので、現在のエレベーター設備の一部を改修するです。","id":"exchange-039"},{"speaker":"金野委員","kind":"質問・要望","question":"私もわからない部分であるので教えていただきたいんですが、隣の大崎高校のそういう施設だとか、そういうところも都にかけ合ってとかということもできるんか尋ねました。","respondent":"富田生涯学習課長","answer":"部活動、さまざまな競技展開しているということでしたので、都立学校の利用は困難だろうと考えています。","id":"exchange-040"}]},{"id":"topic-04","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"南委員","kind":"質問","question":"今のおっしゃっていることは、この３日間のそれぞれの視察内容のことをおっしゃっているんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"南委員","kind":"質問・要望","question":"私たちが意見を出したものを最低限基礎にして、こういう項目を立てていただいたと思うんですけれども、例えば幼稚園と小学校の連携についてというのは、具体的に町の名前はあるんですけれども、どんなふうな内容で事業を行っているのかという、その辺の説明をしていただきたいんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"南委員","kind":"質問・要望","question":"人口規模が８,７３０人で品川とは全然比較にならないというか、そういう状況なので、財政だって体制だって全然違うんじゃないですかね。山形県に行くわけですから、その辺も見ていきたいなと考えていますので、そこも検討していただけるのであればお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"２日目は、１つの学校だけだとちょっと１日なので、やはり２つの施設は難しいですかね。よろしくお願いしたいと思います。","respondent":"若林委員長","answer":"検討はしてみますけれども、そこはご理解を賜りながら実り多い視察を選んでいきたいと思いますので、よろしくお願いします。","id":"exchange-044"},{"speaker":"南委員","kind":"質問・要望","question":"ですから時間的にどうなるかわからないけれども、やっぱりどうせ行くのであれば、いろいろなところを見たいと思いますよね。経費を使っていくわけですから、寄れるところはできるだけ寄っていきたいと私も思いますので、その辺を検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/120587?Template=document&Id=4608#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":38989,"voices":115}}]);
